@pytest.fixture(autouse=True)
def _standalone_tests_use_explicit_direct_transport(monkeypatch):
    """Keep legacy fake-urlopen tests independent from host proxy variables."""

    monkeypatch.setenv("AXIO_FUSION_NETWORK_MODE", "off")
    original_build_opener = provider_module.urllib.request.build_opener
    original_urlopen = provider_module.urllib.request.urlopen

    def direct_or_fake_opener(*handlers):
        class Opener:
            def open(self, request, data=None, timeout=None):
                current_urlopen = provider_module.urllib.request.urlopen
                if current_urlopen is not original_urlopen:
                    return current_urlopen(request, timeout=timeout)
                if data is not None and hasattr(request, "data"):
                    request.data = data
                return original_build_opener(*handlers).open(request, timeout=timeout)

        return Opener()

    monkeypatch.setattr(
        provider_module.urllib.request,
        "build_opener",
        direct_or_fake_opener,
    )


def _benchmark_suite_count() -> int:
    return int(benchmark_manifest()["suite_count"])


def _benchmark_local_jsonl_suite_count() -> int:
    plan = build_benchmark_dataset_manifest_template()["dataset_acquisition_plan"]
    return int(plan["local_jsonl_suite_count"])


def _benchmark_official_import_suite_count() -> int:
    plan = build_benchmark_dataset_manifest_template()["dataset_acquisition_plan"]
    return int(plan["official_or_audited_import_suite_count"])


def _benchmark_claim_family_size() -> int:
    return _benchmark_suite_count() * 3


