def test_standalone_selected_unassigned_spare_does_not_change_initial_fusion_estimate():
    shared_profiles = [
        {
            "provider": "primary",
            "model": "solver",
            "input_cost_per_million": 0.10,
            "output_cost_per_million": 0.20,
            "p50_latency_ms": 300,
            "capabilities": {
                "daily_work": 0.99,
                "logic": 0.98,
                "critique": 0.45,
                "structured_output": 0.84,
            },
        },
        {
            "provider": "independent",
            "model": "checker",
            "input_cost_per_million": 0.12,
            "output_cost_per_million": 0.22,
            "p50_latency_ms": 300,
            "capabilities": {
                "daily_work": 0.93,
                "logic": 0.92,
                "critique": 0.76,
                "structured_output": 0.90,
            },
        },
        {
            "provider": "critic",
            "model": "reviewer",
            "input_cost_per_million": 0.15,
            "output_cost_per_million": 0.25,
            "p50_latency_ms": 300,
            "capabilities": {
                "daily_work": 0.72,
                "logic": 0.76,
                "critique": 0.99,
                "structured_output": 0.99,
            },
        },
        {
            "provider": "domain",
            "model": "specialist",
            "input_cost_per_million": 0.11,
            "output_cost_per_million": 0.21,
            "p50_latency_ms": 300,
            "capabilities": {
                "daily_work": 0.70,
                "logic": 0.70,
                "critique": 0.60,
                "structured_output": 0.70,
            },
        },
    ]
    cheap_spare = {
        "provider": "reserve",
        "model": "spare",
        "input_cost_per_million": 0.11,
        "output_cost_per_million": 0.21,
        "p50_latency_ms": 300,
        "capabilities": {
            "daily_work": 0.01,
            "logic": 0.01,
            "critique": 0.01,
            "structured_output": 0.01,
        },
    }
    extreme_spare = {
        **cheap_spare,
        "input_cost_per_million": 10_000.0,
        "output_cost_per_million": 20_000.0,
        "p50_latency_ms": 100_000,
    }
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "max_models": 5,
            "messages": [
                {
                    "role": "user",
                    "content": "Review a production workflow for logical consistency and risk.",
                }
            ],
        }
    )

    cheap_plan = FusionEngine(
        [normalize_profile(row) for row in [*shared_profiles, cheap_spare]]
    ).complete(request, live=False).route_plan
    extreme_plan = FusionEngine(
        [normalize_profile(row) for row in [*shared_profiles, extreme_spare]]
    ).complete(request, live=False).route_plan

    cheap_admission = cheap_plan["fusion_admission"]
    extreme_admission = extreme_plan["fusion_admission"]
    spare_hash = sha256_text("reserve/spare")
    extreme_cost = extreme_admission["fusion_candidate"]["planned_initial_cost"]
    extreme_latency = extreme_admission["fusion_candidate"]["planned_initial_execution"]

    assert cheap_admission["activated"] is True
    assert extreme_admission["activated"] is True
    assert spare_hash not in {
        sha256_text(row["profile_id"])
        for row in extreme_plan["selected_models"]
    }
    assert spare_hash not in extreme_cost["profile_hashes"]
    assert spare_hash not in extreme_latency["expert_profile_hashes"]
    assert spare_hash != extreme_latency["judge_profile_sha256"]
    assert spare_hash != extreme_latency["synthesizer_profile_sha256"]
    assert extreme_admission["fusion_candidate"]["estimated_cost_usd"] == cheap_admission["fusion_candidate"]["estimated_cost_usd"]
    assert extreme_admission["fusion_candidate"]["estimated_latency_ms"] == cheap_admission["fusion_candidate"]["estimated_latency_ms"]
    assert extreme_admission["fusion_candidate"]["expected_quality"] == cheap_admission["fusion_candidate"]["expected_quality"]
    assert extreme_admission["utility_score"] == cheap_admission["utility_score"]
    assert extreme_admission["latency_multiplier_guard"]["blocked"] is False


def test_standalone_initial_cost_estimate_uses_runtime_role_output_budget_defaults():
    profile = normalize_profile(
        {
            "provider": "cost-provider",
            "model": "cost-model",
            "input_cost_per_million": 1.0,
            "output_cost_per_million": 1.0,
        }
    )
    analysis = {"estimated_steps": 1, "complexity": 0.0, "expected_output_tokens": 9_999}
    roles = [
        {"role": "primary_solver", "model": profile.safe_dict()},
        {"role": "independent_solver", "model": profile.safe_dict()},
        {"role": "judge", "model": profile.safe_dict()},
        {"role": "synthesizer", "model": profile.safe_dict()},
    ]

    estimated_cost, receipt = router_module._estimated_fusion_execution_cost_usd(
        [profile],
        roles,
        analysis,
        max_output_tokens=None,
    )

    input_tokens = router_module._estimated_input_tokens_for_route(analysis)
    expected = (
        2 * (input_tokens + 1024)
        + (max(input_tokens, 1024 * 2) + 1024)
        + (max(input_tokens, 1024 * 2) + 1024)
    ) / 1_000_000

    assert estimated_cost == pytest.approx(expected)
    assert receipt["estimated_total_cost_usd"] == round(expected, 8)
    assert receipt["role_call_count"] == 4


