def test_standalone_high_quality_pro_requires_five_calls_for_complete_three_candidate_fusion():
    profiles = [
        normalize_profile(
            {
                "provider": provider,
                "model": f"{provider}-model",
                "capabilities": {
                    "science_knowledge": 0.9,
                    "logic": 0.9,
                    "critique": 0.9,
                    "structured_output": 0.9,
                },
            }
        )
        for provider in ("alpha", "beta", "gamma", "delta")
    ]
    base_payload = {
        "model": "axio-pro",
        "quality_target": 0.95,
        "messages": [
            {
                "role": "user",
                "content": "Review medical research logic, evidence constraints, and operational workflow risk.",
            }
        ],
    }
    four_call_plan = FusionEngine(profiles).complete(
        canonicalize_payload({**base_payload, "max_total_model_calls": 4}),
        live=False,
    ).route_plan
    five_call_plan = FusionEngine(profiles).complete(
        canonicalize_payload({**base_payload, "max_total_model_calls": 5}),
        live=False,
    ).route_plan
    four_call_admission = four_call_plan["fusion_admission"]
    five_call_admission = five_call_plan["fusion_admission"]
    four_call_budget = four_call_admission["initial_fusion_call_plan"]
    five_call_budget = five_call_admission["initial_fusion_call_plan"]

    assert four_call_plan["strategy"] == "pro_direct_with_verifier_gap"
    assert four_call_admission["activated"] is False
    assert four_call_admission["decision_reason"] == "max_total_model_calls_below_complete_fusion_floor"
    assert four_call_budget["configured_min_judge_candidate_count"] == 3
    assert four_call_budget["minimum_complete_fusion_call_count"] == 5
    assert four_call_budget["planned_initial_fusion_call_count"] == 0
    assert four_call_budget["blocked_by_call_budget"] is True

    assert five_call_plan["strategy"] == "pro_panel_judge_escalation"
    assert five_call_admission["activated"] is True
    assert five_call_budget["configured_min_judge_candidate_count"] == 3
    assert five_call_budget["minimum_expert_call_count"] == 3
    assert five_call_budget["minimum_complete_fusion_call_count"] == 5
    assert five_call_budget["planned_initial_fusion_call_count"] == 5
    assert five_call_budget["complete_fusion_feasible"] is True
    assert five_call_budget["role_budget_constrained"] is True
    assert {"primary_solver", "independent_solver", "critic", "judge", "synthesizer"}.issubset(
        {row["role"] for row in five_call_plan["roles"]}
    )


