    serialized = json.dumps({"public_payloads": public_payloads, "receipt": receipt}, ensure_ascii=False)

    assert response.route_plan["fusion_admission"]["activated"] is True
    for payload in public_payloads:
        summary = payload["metadata"]["route_summary"]
