    assert call_plan["role_budget_constrained"] is True
    assert receipt["raw_prompt_persisted"] is False
    assert receipt["raw_model_names_persisted"] is False
    assert secret_provider not in serialized
    assert secret_model not in serialized
    assert secret_prompt not in serialized
    assert '"raw_provider_model_ids_persisted": true' not in serialized
    assert '"raw_prompt_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


