def test_standalone_live_executes_domain_specialist_and_records_task_receipts():
    secret_prompt = "SECRET_DOMAIN_SPECIALIST_DAG_PROMPT"

    class DomainSpecialistClient:
        def __init__(self):
            self.calls = []
            self.judge_packets = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt, "system": system})
            if "Compare these Axio Fusion candidate answers" in prompt:
                packet_text = prompt.split("Candidate packet:\n", 1)[1].split("\n\nLocal rubric", 1)[0]
                packet = json.loads(packet_text)
                self.judge_packets.append(packet)
                domain_packet = next(row for row in packet if row["role"] == "domain_specialist")
                node_ids = {
                    row["id"]
                    for row in domain_packet["task_execution"]["node_receipts"]
                }
                assert "domain_specialist_code_risk_review" in node_ids
                assert domain_packet["task_execution"]["verification_node_count"] >= 1
                return json.dumps(
                    {
                        "consensus": [],
                        "contradictions": [],
                        "missing_coverage": ["final synthesis required"],
                        "collective_blind_spots": [],
                        "ranked_candidates": [
                            {"candidate_id": "domain_specialist", "score": 0.92},
                            {"candidate_id": "critic", "score": 0.9},
                            {"candidate_id": "primary_solver", "score": 0.88},
                            {"candidate_id": "independent_solver", "score": 0.86},
                        ],
                        "follow_up_tasks": ["synthesize domain specialist risk review"],
                        "ready_for_synthesis": False,
                    }
                )
            if "Synthesize one final answer" in prompt:
                assert "domain_specialist_code_risk_review" in prompt
                return "domain specialist DAG final answer"
            role = "domain_specialist" if "domain specialist" in system.lower() else (
                "critic" if "you are a critic" in system.lower() else (
                    "independent_solver" if "independent solver" in system.lower() else "primary_solver"
                )
            )
            return json.dumps(
                {
                    "answer": f"{role} candidate from {profile.provider}",
                    "reasoning_summary": [f"{role} covered assigned DAG nodes"],
                    "evidence": [{"claim": role, "source": "fixture", "reliability": 0.86}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.86,
                }
            )

    profiles = [
        normalize_profile({"provider": "alpha", "model": "primary", "capabilities": {"code": 0.92, "logic": 0.88, "agentic_tool_calling": 0.82, "critique": 0.7, "structured_output": 0.84}}),
        normalize_profile({"provider": "beta", "model": "independent", "capabilities": {"code": 0.86, "logic": 0.86, "agentic_tool_calling": 0.84, "critique": 0.78, "structured_output": 0.86}}),
        normalize_profile({"provider": "gamma", "model": "critic", "capabilities": {"code": 0.82, "logic": 0.82, "agentic_tool_calling": 0.76, "critique": 0.97, "structured_output": 0.94}}),
        normalize_profile({"provider": "delta", "model": "domain", "capabilities": {"code": 0.98, "logic": 0.92, "agentic_tool_calling": 0.88, "critique": 0.82, "structured_output": 0.88}}),
    ]
    fake = DomainSpecialistClient()
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "task_type": "code_security_review",
            "quality_target": 0.95,
            "max_depth": 0,
            "max_total_model_calls": 8,
            "messages": [
                {
                    "role": "user",
                    "content": f"Analyze complex python agent tool workflow authorization injection logic security {secret_prompt}",
                }
            ],
        }
    )

    response = FusionEngine(profiles, client=fake).complete(request, live=True)
    receipt = safe_execution_trace(response, tenant_key="domain-specialist-dag-test")
    serialized_safe = json.dumps({"trace": response.trace, "receipt": receipt}, ensure_ascii=False)
    role_names = [role["role"] for role in response.route_plan["roles"]]
    called_systems = "\n".join(call["system"] for call in fake.calls)
    domain_candidate = next(candidate for candidate in response.candidates if candidate.role == "domain_specialist")
    domain_receipt = next(row for row in receipt["candidate_outputs"] if row["role"] == "domain_specialist")

    assert response.text == "domain specialist DAG final answer"
    assert "domain_specialist" in role_names
    assert "domain specialist" in called_systems.lower()
    assert fake.judge_packets
    assert {row["role"] for row in fake.judge_packets[0]}.issuperset(
        {"primary_solver", "independent_solver", "critic", "domain_specialist"}
    )
    assert response.trace["provider_call_count"] == 6
    assert response.trace["judge_provider_call_count"] == 1
    assert response.trace["synthesis_provider_call_count"] == 1
    assert domain_candidate.task_execution["assigned_node_count"] >= 1
    assert domain_candidate.task_execution["verification_node_count"] >= 1
    assert domain_receipt["task_execution"]["assigned_node_count"] >= 1
    assert receipt["runtime_guards"]["dag_role_execution_receipts_enabled"] is True
    assert secret_prompt not in serialized_safe
    assert response.trace["raw_prompt_persisted"] is False


def test_standalone_four_api_shapes_render_public_axio_models_only():
    engine = FusionEngine([normalize_profile({"provider": "secret-provider", "model": "private-fast-model"})])
    cases = [
        (
            "chat/completions",
            {"model": "axio-fast", "messages": [{"role": "user", "content": "hello"}]},
            ("model", "axio-fast"),
        ),
        (
            "responses",
            {"model": "axio-terra", "instructions": "brief", "input": "hello"},
            ("model", "axio-terra"),
        ),
        (
            "anthropic",
            {"model": "axio-pro", "system": "brief", "messages": [{"role": "user", "content": "hello"}]},
            ("model", "axio-pro"),
        ),
        (
            "gemini",
            {"model": "axio-fast", "contents": [{"role": "user", "parts": [{"text": "hello"}]}]},
            ("modelVersion", "axio-fast"),
        ),
    ]

    for api_format, payload, expected in cases:
        request = canonicalize_payload(payload, api_format=api_format)
        rendered = render_response(engine.complete(request, live=False), api_format=api_format)
        key, value = expected
        serialized = json.dumps(rendered, ensure_ascii=False)

        assert rendered[key] == value
        assert rendered["metadata"]["external_model_name"] == value
        assert rendered["metadata"]["provider_calls_recorded"] is False
        assert rendered["metadata"]["internal_details_redacted"] is True
        assert rendered["metadata"]["provider_identifiers_redacted"] is True
        assert rendered["metadata"]["route_summary"]["selected_profile_hashes"]
        assert "route_plan" not in rendered["metadata"]
        assert "fusion_trace" not in rendered["metadata"]
        assert "judge_result" not in rendered["metadata"]
        assert "secret-provider" not in serialized
        assert "private-fast-model" not in serialized
        assert "secret-provider/private-fast-model" not in serialized
        assert "raw_provider_model_ids_persisted\": true" not in serialized


def test_standalone_live_panel_judges_and_synthesizes_with_fake_client():
    class FakeClient:
        def __init__(self):
            self.calls = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt, "system": system})
            if "Compare these Axio Fusion candidate answers" in prompt:
                return json.dumps(
                    {
                        "consensus": [
                            {
                                "claim": "candidate beta has stronger evidence",
                                "supporting_candidates": ["independent_solver"],
                                "evidence_strength": 0.88,
                            }
                        ],
                        "contradictions": [],
                        "missing_coverage": [],
                        "collective_blind_spots": [],
                        "ranked_candidates": [
                            {"candidate_id": "independent_solver", "score": 0.91},
                            {"candidate_id": "primary_solver", "score": 0.82},
                        ],
                        "follow_up_tasks": [],
                        "ready_for_synthesis": True,
                    }
                )
            if "Synthesize one final answer" in prompt:
                return "final synthesized answer"
            return json.dumps(
                {
                    "answer": f"candidate from {profile.provider}",
                    "evidence": [{"claim": "x", "source": "unit", "reliability": 0.8}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.82,
                }
            )

    profiles = [
        normalize_profile({"provider": "alpha", "model": "reasoner-120b", "capabilities": {"science_knowledge": 0.9, "critique": 0.8, "structured_output": 0.8}}),
        normalize_profile({"provider": "beta", "model": "critic-70b", "capabilities": {"science_knowledge": 0.75, "critique": 0.9, "structured_output": 0.85}}),
    ]
    fake = FakeClient()
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "task_type": "science_research",
            "messages": [{"role": "user", "content": "compare two scientific hypotheses"}],
        }
    )

    response = FusionEngine(profiles, client=fake).complete(request, live=True)
    rendered = render_response(response)
