def test_standalone_local_judge_clusters_numeric_fraction_decimal_and_percent_claims_safely():
    class NumericEquivalentClaimClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            lowered_system = system.lower()
            lowered_prompt = prompt.lower()
            if "compare these axio fusion candidate answers" in lowered_prompt:
                raise AssertionError("provider judge should be skipped by call budget")
            if "synthesize one final answer" in lowered_prompt:
                raise AssertionError("provider synthesizer should be skipped by call budget")
            if "critic" in lowered_system:
                answer = "Final answer: 50%."
                confidence = 0.84
            elif "independent solver" in lowered_system:
                answer = "The result is 0.5000 because the numerator is half the denominator."
                confidence = 0.86
            else:
                answer = "Final answer: 1/2."
                confidence = 0.83
            return json.dumps(
                {
                    "answer": answer,
                    "evidence": [{"claim": "equivalent rational value", "source": "fixture", "reliability": 0.85}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": confidence,
                }
            )

    profiles = [
        normalize_profile({"provider": "alpha", "model": "fraction-solver", "capabilities": {"math": 0.87, "logic": 0.83, "critique": 0.72, "structured_output": 0.82}}),
        normalize_profile({"provider": "beta", "model": "decimal-verifier", "capabilities": {"math": 0.85, "logic": 0.86, "critique": 0.8, "structured_output": 0.84}}),
        normalize_profile({"provider": "gamma", "model": "percent-critic", "capabilities": {"math": 0.84, "logic": 0.82, "critique": 0.86, "structured_output": 0.83}}),
    ]
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "max_total_model_calls": 3,
            "messages": [{"role": "user", "content": "Solve the probability ratio and return the final value."}],
        }
    )

    response = _complete_with_runtime_call_cap(
        FusionEngine(profiles, client=NumericEquivalentClaimClient()),
        request,
        runtime_max_total_model_calls=3,
    )
    receipt = safe_execution_trace(response, tenant_key="numeric-claim-equivalence-test")
    serialized_receipt = json.dumps(receipt, ensure_ascii=False)
    clusters = response.judge_result["answer_claim_clusters"]

    assert response.trace["judge_provider_call_count"] == 0
    assert response.trace["synthesis_provider_call_count"] == 0
    assert response.judge_result["judge_provider_call_skipped"] is True
    assert clusters[0]["candidate_count"] == 3
    assert clusters[0]["support_fraction"] == 1.0
    assert clusters[0]["unique_profile_count"] == 3
    assert clusters[0]["unique_provider_count"] == 3
    assert clusters[0]["answer_claim_equivalence_type"] == "numeric_value"
    assert clusters[0]["answer_claim_equivalence_type_counts"] == {"numeric_value": 3}
    assert response.judge_result["coverage_summary"]["answer_claim_consensus_detected"] is True
    assert response.judge_result["contradictions"] == []
    assert response.judge_result["consensus"][0]["claim"] == "answer_claim_cluster_converges"
    assert receipt["judge_result"]["largest_answer_claim_equivalence_type"] == "numeric_value"
    assert receipt["judge_result"]["largest_answer_claim_support_fraction"] == 1.0
    assert receipt["judge_result"]["largest_answer_claim_unique_profile_count"] == 3
    assert receipt["judge_result"]["largest_answer_claim_unique_provider_count"] == 3
    assert receipt["early_exit"]["answer_claim_consensus"]["passed"] is True
    assert receipt["early_exit"]["answer_claim_consensus"]["independent_detected"] is True
    assert receipt["early_exit"]["answer_claim_consensus"]["largest_answer_claim_equivalence_type"] == "numeric_value"
    assert "0.5000" not in serialized_receipt
    assert "50%" not in serialized_receipt
    assert "1/2" not in serialized_receipt
    assert "half the denominator" not in serialized_receipt


def test_standalone_runtime_budget_lock_caps_judge_and_synthesis_calls():
    class BudgetedClient:
        def __init__(self):
            self.calls = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt})
            if "Compare these Axio Fusion candidate answers" in prompt:
                raise AssertionError("judge provider call should be skipped by budget lock")
            if "Synthesize one final answer" in prompt:
                raise AssertionError("synthesizer provider call should be skipped by budget lock")
            return json.dumps(
                {
                    "answer": f"budgeted candidate from {profile.provider}",
                    "evidence": [{"claim": "unit", "source": "fixture", "reliability": 0.8}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.82,
                }
            )

    profiles = [
        normalize_profile({"provider": "alpha", "model": "solver-120b", "capabilities": {"daily_work": 0.9, "critique": 0.8, "structured_output": 0.8}}),
        normalize_profile({"provider": "beta", "model": "judge-70b", "capabilities": {"daily_work": 0.75, "critique": 0.95, "structured_output": 0.95}}),
    ]
    fake = BudgetedClient()
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "max_total_model_calls": 2,
            "messages": [{"role": "user", "content": "Review this workflow."}],
        }
    )

    response = _complete_with_runtime_call_cap(
        FusionEngine(profiles, client=fake),
        request,
        runtime_max_total_model_calls=2,
    )
    receipt = safe_execution_trace(response, tenant_key="budget-test")
    skipped_kinds = {row["kind"] for row in response.trace["budget_lock"]["skipped_calls"]}
    serialized_receipt = json.dumps(receipt, ensure_ascii=False)

    assert len(fake.calls) == 2
    assert all("Compare these Axio Fusion candidate answers" not in call["prompt"] for call in fake.calls)
    assert all("Synthesize one final answer" not in call["prompt"] for call in fake.calls)
    assert response.trace["provider_call_count"] == 2
    assert response.trace["budget_lock"]["max_total_model_calls"] == 2
    assert response.trace["budget_lock"]["used_model_call_count"] == 2
    assert response.trace["budget_lock"]["skipped_call_count"] == 2
    assert {"judge", "synthesizer"}.issubset(skipped_kinds)
    assert response.judge_result["judge_provider_call_skipped"] is True
    assert response.judge_result["judge_skip_reason"] == "max_total_model_calls_exhausted"
    assert response.trace["judge_provider_call_count"] == 0
    assert response.trace["synthesis_provider_call_count"] == 0
    assert receipt["budget_lock"]["used_model_call_count"] == 2
    assert receipt["budget_lock"]["skipped_call_count"] == 2
    assert "alpha/solver-120b" not in serialized_receipt
    assert "beta/judge-70b" not in serialized_receipt


