def test_standalone_runtime_deadline_budget_skips_optional_late_stages(monkeypatch):
    clock = {"now": 0.0}
    lock = threading.Lock()

    def fake_monotonic():
        return clock["now"]

    class DeadlineClient:
        def __init__(self):
            self.calls = []
            self.candidate_call_count = 0

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt, "timeout": timeout})
            if "Compare these Axio Fusion candidate answers" in prompt:
                raise AssertionError("judge provider call should be skipped after deadline")
            if "Synthesize one final answer" in prompt:
                raise AssertionError("synthesizer provider call should be skipped after deadline")
            with lock:
                self.candidate_call_count += 1
                if self.candidate_call_count == 2:
                    clock["now"] = 0.003
            return json.dumps(
                {
                    "answer": f"deadline candidate from {profile.provider}",
                    "evidence": [{"claim": "unit", "source": "fixture", "reliability": 0.8}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.82,
                }
            )

    monkeypatch.setattr(orchestrator_module.time, "monotonic", fake_monotonic)
    profiles = [
        normalize_profile({"provider": "alpha", "model": "solver-120b", "capabilities": {"daily_work": 0.9, "critique": 0.8, "structured_output": 0.8}}),
        normalize_profile({"provider": "beta", "model": "judge-70b", "capabilities": {"daily_work": 0.75, "critique": 0.95, "structured_output": 0.95}}),
    ]
    fake = DeadlineClient()
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "max_latency_ms": 2,
            "max_total_model_calls": 8,
            "messages": [{"role": "user", "content": "Review this workflow."}],
        }
    )

    response = FusionEngine(profiles, client=fake).complete(request, live=True)
    receipt = safe_execution_trace(response, tenant_key="deadline-test")
    skipped_kinds = {row["kind"] for row in response.trace["deadline_budget"]["skipped_calls"]}
    serialized_receipt = json.dumps(receipt, ensure_ascii=False)

    assert len(fake.calls) == 2
    assert all(call["timeout"] <= 0.002 for call in fake.calls)
    assert all("Compare these Axio Fusion candidate answers" not in call["prompt"] for call in fake.calls)
    assert all("Synthesize one final answer" not in call["prompt"] for call in fake.calls)
    assert response.trace["provider_call_count"] == 2
    assert response.trace["judge_provider_call_count"] == 0
    assert response.trace["synthesis_provider_call_count"] == 0
    assert response.trace["deadline_budget"]["max_latency_ms"] == 2
    assert response.trace["deadline_budget"]["skipped_call_count"] == 2
    assert {"judge", "synthesizer"}.issubset(skipped_kinds)
    assert response.judge_result["judge_provider_call_skipped"] is True
    assert response.judge_result["judge_skip_reason"] == "max_latency_ms_exhausted"
    assert receipt["runtime_guards"]["deadline_budget_enabled"] is True
    assert receipt["runtime_guards"]["max_latency_ms"] == 2
    assert receipt["deadline_budget"]["skipped_call_count"] == 2
    assert "alpha/solver-120b" not in serialized_receipt
    assert "beta/judge-70b" not in serialized_receipt


def test_standalone_server_dispatches_gemini_and_models(monkeypatch):
    monkeypatch.delenv("UNIT_MODELS_BASE_URL", raising=False)
    monkeypatch.delenv("UNIT_MODELS_API_KEY", raising=False)
    engine = FusionEngine(
        [
            normalize_profile(
                {
                    "provider": "unit",
                    "model": "fast-model",
                    "base_url_env": "UNIT_MODELS_BASE_URL",
                    "api_key_env": "UNIT_MODELS_API_KEY",
                }
            )
        ]
    )
    models_status, _, models_body = handle_request(
        method="GET",
        path="/v1/models",
        engine=engine,
    )
    gemini_status, _, gemini_body = handle_request(
        method="POST",
        path="/v1beta/models/axio-fast:generateContent",
        body=json.dumps({"contents": [{"role": "user", "parts": [{"text": "hello"}]}]}),
        engine=engine,
    )

    models = json.loads(models_body.decode("utf-8"))
    gemini = json.loads(gemini_body.decode("utf-8"))
    serialized_models = json.dumps(models, ensure_ascii=False)
    serialized_gemini = json.dumps(gemini, ensure_ascii=False)

    assert models_status == 200
    assert {item["id"] for item in models["data"]} == {"axio-fast", "axio-terra", "axio-pro"}
    assert models["registry_summary"]["schema"] == "axio_fusion_api.public_models_registry_summary.v1"
    assert models["registry_summary"]["all_listed_models_usable"] is True
    assert models["registry_summary"]["all_listed_models_live_usable"] is False
    assert models["registry_summary"]["live_credential_summary"]["schema"] == "axio_fusion_api.live_provider_credential_summary.v1"
    assert models["registry_summary"]["live_credential_summary"]["credential_ready"] is False
    assert "registry" not in models
    assert all(item["usable"] is True for item in models["data"])
    assert all(item["live_usable"] is False for item in models["data"])
    assert all(item["live_status"] == "credentials_required" for item in models["data"])
    assert all(item["metadata"]["raw_provider_model_ids_persisted"] is False for item in models["data"])
    assert "fast-model" not in serialized_models
    assert "UNIT_MODELS_BASE_URL" not in serialized_models
    assert "UNIT_MODELS_API_KEY" not in serialized_models
    assert gemini_status == 200
    assert gemini["modelVersion"] == "axio-fast"
    assert gemini["metadata"]["raw_prompt_persisted"] is False
    assert gemini["metadata"]["internal_details_redacted"] is True
    assert "route_plan" not in gemini["metadata"]
    assert "fusion_trace" not in gemini["metadata"]
    assert "judge_result" not in gemini["metadata"]
    assert "fast-model" not in serialized_gemini
    assert "unit/fast-model" not in serialized_gemini


