def test_standalone_fusion_deliberation_live_smoke_exercises_complete_panel_without_persisting_content(monkeypatch, tmp_path):
    class FakeFusionDeliberationClient:
        def __init__(self):
            self.calls = []
            self.judge_calls = 0
            self.synthesis_calls = 0

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append(
                {
                    "profile_id": profile.profile_id,
                    "public_model": request.public_model,
                    "prompt": prompt,
                    "system": system,
                    "timeout": timeout,
                    "max_total_model_calls": request.policy.max_total_model_calls,
                }
            )
            lowered_system = system.lower()
            if "structured judge" in lowered_system:
                self.judge_calls += 1
                return json.dumps(
                    {
                        "consensus": [],
                        "contradictions": [],
                        "unique_insights": ["independent_approaches_preserved"],
                        "missing_coverage": [],
                        "collective_blind_spots": [],
                        "ranked_candidates": [
                            {"candidate_id": "primary_solver", "score": 0.91},
                            {"candidate_id": "independent_solver", "score": 0.89},
                            {"candidate_id": "critic", "score": 0.84},
                        ],
                        "follow_up_tasks": [],
                        "ready_for_synthesis": True,
                    }
                )
            if "fusion synthesizer" in lowered_system:
                self.synthesis_calls += 1
                return "FUSION_SMOKE_SYNTHESIS_OUTPUT_MUST_NOT_PERSIST"
            if "independent solver" in lowered_system:
                answer = "Independent option beta with explicit assumption handling."
            elif "critic" in lowered_system:
                answer = "Critic option gamma identifies a residual implementation risk."
            else:
                answer = "Primary option alpha balances the synthetic decision."
            return json.dumps(
                {
                    "answer": answer,
                    "reasoning_summary": ["synthetic bounded rationale"],
                    "evidence": [{"claim": "synthetic fixture evidence", "source": "fixture", "reliability": 0.8}],
                    "assumptions": ["synthetic input only"],
                    "uncertainties": ["fixture uncertainty"],
                    "confidence": 0.86,
                }
            )

    reset_runtime_state_for_tests()
    monkeypatch.delenv("AXIO_FUSION_API_KEYS", raising=False)
    registry_path = _benchmark_registry_path(tmp_path)
    client = FakeFusionDeliberationClient()
    secret_prompt = "SECRET_FUSION_DELIBERATION_PROMPT_MUST_NOT_PERSIST"
    runtime_before = runtime_state().snapshot()

    payload = build_fusion_deliberation_live_smoke(
        registry_path=str(registry_path),
        models=["axio-pro"],
        prompt=secret_prompt,
        max_latency_ms=30_000,
        max_output_tokens=128,
        max_total_model_calls=6,
        max_cost_usd=0.02,
        live=True,
        client=client,
        require_live_credentials=False,
    )
    serialized = json.dumps(payload, ensure_ascii=False)

    assert payload["schema"] == "axio_fusion_api.fusion_deliberation_live_smoke.v1"
    assert payload["mode"] == "live_fusion_deliberation_smoke"
    assert payload["status"] == "passed"
    assert payload["public_models"] == ["axio-pro"]
    assert payload["expected_request_count"] == 1
    assert payload["attempted_request_count"] == 1
    assert payload["passed_request_count"] == 1
    assert payload["failed_request_count"] == 0
    assert payload["all_required_fusion_deliberation_paths_live"] is True
    assert payload["network_calls_performed"] is False
    assert payload["bounded_execution_policy"]["cache_disabled"] is True
    assert payload["bounded_execution_policy"]["execution_traces_written"] is False
    assert payload["bounded_execution_policy"]["runtime_budget_accounting_written"] is False
    assert payload["bounded_execution_policy"]["not_a_benchmark"] is True
    assert payload["bounded_execution_policy"]["does_not_prove_fusion_quality"] is True
    assert payload["bounded_execution_policy"]["does_not_prove_latency_superiority"] is True
    assert payload["completion_contract"]["process_receipt_contract_version"] == 2
    assert (
        payload["completion_contract"][
            "requires_hermes_acting_synthesizer_when_hermes_enabled"
        ]
        is True
    )
    assert runtime_state().snapshot() == runtime_before
    assert len(payload["rows"]) == 1
    row = payload["rows"][0]
    assert row["deliberation_smoke_passed"] is True
    assert row["fusion_activated"] is True
    assert row["complete_admitted_fusion_finalized"] is True
    assert row["completed_candidate_count"] >= 2
    assert row["judge_output_accepted"] is True
    assert row["synthesis_output_accepted"] is True
    assert row["judge_parse_failed"] is False
    assert row["hermes_process_contract_required"] is True
    assert row["hermes_execution_enabled"] is True
    assert row["hermes_process_contract_completed"] is True
    assert row["hermes_aggregator_output_accepted"] is True
    assert row["judge_provider_call_count"] >= 1
    assert row["synthesis_provider_call_count"] >= 1
    assert row["early_exit_triggered"] is False
    assert 1 <= row["provider_call_count"] <= 6
    assert row["answer_sha256"]
    assert client.judge_calls >= 1
    assert client.synthesis_calls >= 1
    assert len(client.calls) == row["provider_call_count"]
    assert all(call["max_total_model_calls"] == 6 for call in client.calls)
    assert secret_prompt not in serialized
    assert "FUSION_SMOKE_SYNTHESIS_OUTPUT_MUST_NOT_PERSIST" not in serialized
    assert "synthetic fixture evidence" not in serialized
    assert "unit/solver" not in serialized
    assert str(registry_path) not in serialized
    assert '"raw_prompt_persisted": true' not in serialized
    assert '"raw_response_text_persisted": true' not in serialized
    assert '"raw_candidate_text_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


def test_standalone_fusion_deliberation_smoke_rejects_hermes_early_exit() -> None:
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "messages": [{"role": "user", "content": "synthetic private task"}],
        }
    )
    response = FusionResponse(
        text="degraded reference answer",
        request=request,
        route_plan={
            "fusion_admission": {"activated": True},
            "hermes_moa": {"enabled": True},
        },
        trace={
            "runtime_fusion_stage_outcome": {
                "completed_candidate_count": 2,
                "complete_admitted_fusion_finalized": True,
                "hermes_process_contract_required": True,
                "hermes_process_contract_completed": False,
            },
            "hermes_moa_execution": {
                "enabled": True,
                "process_contract_completed": False,
                "aggregator_output_accepted": False,
            },
            "early_exit": {"triggered": True},
            "judge_provider_call_count": 1,
            "synthesis_provider_call_count": 0,
            "provider_call_count": 3,
        },
        provider_calls_recorded=True,
    )

    row = server_module._fusion_deliberation_live_smoke_row(
        model="axio-pro",
        response=response,
        end_to_end_latency_ms=50.0,
        max_total_model_calls=6,
    )

    assert row["deliberation_smoke_passed"] is False
    assert row["hermes_process_contract_required"] is True
    assert row["hermes_process_contract_completed"] is False
    assert "hermes_acting_synthesizer_not_executed" in row["reason_codes"]
    assert (
        "hermes_acting_synthesizer_bypassed_by_early_exit"
        in row["reason_codes"]
    )
    assert "hermes_process_contract_incomplete" in row["reason_codes"]


