def test_standalone_gateway_cors_preflight_requires_explicit_allowlist_and_preserves_auth(monkeypatch):
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "public-key")
    monkeypatch.setenv("AXIO_FUSION_OPERATOR_API_KEYS", "operator-key")
    monkeypatch.setenv("AXIO_FUSION_CORS_ALLOW_ORIGINS", "https://studio.example")

    status, headers, body = handle_request(
        method="OPTIONS",
        path="/v1/chat/completions",
        headers={
            "Origin": "https://studio.example",
            "Access-Control-Request-Method": "POST",
            "Access-Control-Request-Headers": "Authorization, X-Api-Key, X-Axio-Tenant",
        },
    )
    assert status == 204
    assert body == b""
    assert headers["Access-Control-Allow-Origin"] == "https://studio.example"
    assert "POST" in headers["Access-Control-Allow-Methods"]
    assert "authorization" in headers["Access-Control-Allow-Headers"]
    assert "x-api-key" in headers["Access-Control-Allow-Headers"]
    assert "x-axio-tenant" in headers["Access-Control-Allow-Headers"]
    assert "Access-Control-Request-Headers" in headers["Vary"]

    unauthorized_status, unauthorized_headers, unauthorized_body = handle_request(
        method="GET",
        path="/v1/models",
        headers={"Origin": "https://studio.example"},
    )
    unauthorized = json.loads(unauthorized_body.decode("utf-8"))
    assert unauthorized_status == 401
    assert unauthorized_headers["Access-Control-Allow-Origin"] == "https://studio.example"
    assert unauthorized["error"]["code"] == "unauthorized"

    authorized_status, authorized_headers, authorized_body = handle_request(
        method="GET",
        path="/v1/models",
        headers={"Origin": "https://studio.example", "x-api-key": "public-key"},
    )
    authorized = json.loads(authorized_body.decode("utf-8"))
    assert authorized_status == 200
    assert authorized_headers["Access-Control-Allow-Origin"] == "https://studio.example"
    assert authorized["object"] == "list"

    operator_status, operator_headers, operator_body = handle_request(
        method="POST",
        path="/v1/axio/route-plan",
        headers={"Origin": "https://studio.example", "x-api-key": "public-key"},
        body=b"{}",
    )
    operator = json.loads(operator_body.decode("utf-8"))
    assert operator_status == 403
    assert operator_headers["Access-Control-Allow-Origin"] == "https://studio.example"
    assert operator["error"]["code"] == "operator_authorization_required"


