def test_standalone_openai_stream_tool_events_reassemble_to_non_stream_shape():
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "messages": [{"role": "user", "content": "Call the lookup tool."}],
        }
    )
    response = FusionResponse(
        text="",
        request=request,
        route_plan={},
        response_id="resp_stream_contract",
        tool_calls=(
            {
                "id": "call_lookup_stream",
                "name": "lookup",
                "arguments": {"value": 42},
            },
        ),
    )

    stream = render_stream_events(response, api_format="chat/completions").decode("utf-8")
    rows = [
        json.loads(line[6:])
        for line in stream.splitlines()
        if line.startswith("data: {")
    ]
    deltas = [
        choice["delta"]
        for row in rows
        for choice in row.get("choices", [])
        if isinstance(choice, dict) and isinstance(choice.get("delta"), dict)
    ]
    streamed_calls = [
        call
        for delta in deltas
        for call in delta.get("tool_calls", [])
        if isinstance(call, dict)
    ]
    arguments = "".join(
        str(call.get("function", {}).get("arguments") or "")
        for call in streamed_calls
    )

    rendered = render_response(response, api_format="chat/completions")
    assert streamed_calls[0]["id"] == "call_lookup_stream"
    assert streamed_calls[0]["function"]["name"] == "lookup"
    assert json.loads(arguments) == {"value": 42}
    assert rows[-1]["choices"][0]["finish_reason"] == "tool_calls"
    assert "data: [DONE]" in stream
    assert rendered["choices"][0]["message"]["tool_calls"][0]["function"]["arguments"] == arguments


def test_standalone_responses_stream_exposes_complete_item_lifecycle_and_function_argument_events():
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "input": "Return text and a tool call.",
        },
        api_format="responses",
    )
    response = FusionResponse(
        text="answer",
        request=request,
        route_plan={},
        response_id="resp_responses_stream_contract",
        tool_calls=(
            {
                "id": "call_responses_stream",
                "name": "lookup",
                "arguments": {"value": 7},
            },
        ),
    )

    stream = render_stream_events(response, api_format="responses").decode("utf-8")
    event_names = [
        line[len("event: "):]
        for line in stream.splitlines()
        if line.startswith("event: ")
    ]
    payloads = []
    pending_event = None
    for line in stream.splitlines():
        if line.startswith("event: "):
            pending_event = line[len("event: "):]
        elif line.startswith("data: {"):
            payloads.append((pending_event, json.loads(line[6:])))

    assert event_names[:2] == ["response.created", "response.in_progress"]
    assert "response.output_item.added" in event_names
    assert "response.content_part.added" in event_names
    assert "response.output_text.done" in event_names
    assert "response.content_part.done" in event_names
    assert "response.function_call_arguments.delta" in event_names
    assert "response.function_call_arguments.done" in event_names
    assert event_names[-1] == "response.completed"
    assert [
        payload["sequence_number"]
        for _, payload in payloads
    ] == list(range(1, len(payloads) + 1))
    assert all(payload["response_id"] == "resp_responses_stream_contract" for _, payload in payloads)
    argument_done = next(
        payload for event, payload in payloads
        if event == "response.function_call_arguments.done"
    )
    assert argument_done["name"] == "lookup"
    assert argument_done["call_id"] == "call_responses_stream"
    completed = next(payload for event, payload in payloads if event == "response.completed")
    assert json.loads(argument_done["arguments"]) == {"value": 7}
    assert completed["response"]["status"] == "completed"
    assert completed["response"]["background"] is False
    assert completed["response"]["service_tier"] == "default"
    assert completed["response"]["text"] == {"format": {"type": "text"}}
    assert completed["response"]["truncation"] == "disabled"
    assert completed["response"]["usage"]["input_tokens_details"] == {"cached_tokens": 0}
    assert completed["response"]["usage"]["output_tokens_details"] == {"reasoning_tokens": 0}
    assert completed["response"]["output"][0]["type"] == "message"
    assert completed["response"]["output"][1]["type"] == "function_call"


