def test_standalone_http_server_loopback_preserves_four_public_api_surfaces(monkeypatch):
    monkeypatch.delenv("AXIO_FUSION_API_KEYS", raising=False)
    monkeypatch.delenv("AXIO_FUSION_ACCESS_LOG", raising=False)
    engine = FusionEngine(
        [normalize_profile({"provider": "unit", "model": "loopback-model"})]
    )
    server = create_http_server(
        host="127.0.0.1",
        port=0,
        engine=engine,
        record_trace=False,
        record_runtime=False,
    )
    worker = threading.Thread(target=server.serve_forever, daemon=True)
    worker.start()
    secret_prompt = "SECRET_HTTP_LOOPBACK_PROMPT_MUST_NOT_PERSIST"
    cases = [
        (
            "chat",
            "/v1/chat/completions",
            {
                "model": "axio-fast",
                "messages": [{"role": "user", "content": secret_prompt}],
                "max_tokens": 16,
            },
            "axio-fast",
        ),
        (
            "responses",
            "/v1/responses",
            {"model": "axio-terra", "input": secret_prompt, "max_output_tokens": 16},
            "axio-terra",
        ),
        (
            "anthropic",
            "/v1/messages",
            {
                "model": "axio-pro",
                "messages": [{"role": "user", "content": secret_prompt}],
                "max_tokens": 16,
            },
            "axio-pro",
        ),
        (
            "gemini",
            "/v1beta/models/axio-pro:generateContent",
            {
                "contents": [{"role": "user", "parts": [{"text": secret_prompt}]}],
                "generationConfig": {"maxOutputTokens": 16},
            },
            "axio-pro",
        ),
    ]
    observed_surfaces = set()
    try:
        host, port = server.server_address[:2]
        for surface, path, payload, expected_model in cases:
            request = urllib.request.Request(
                f"http://{host}:{port}{path}",
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urllib.request.urlopen(request, timeout=5) as response:
                body = json.loads(response.read().decode("utf-8"))
                serialized = json.dumps(body, ensure_ascii=False)
                status = response.status
                content_type = str(response.headers.get("Content-Type") or "")

            observed_surfaces.add(surface)
            assert status == 200
            assert "json" in content_type.lower()
            assert str(body.get("model") or body.get("modelVersion") or "") == expected_model
            assert isinstance(body.get("metadata"), dict)
            assert secret_prompt not in serialized
            assert body["metadata"]["raw_prompt_persisted"] is False
            assert body["metadata"]["secrets_persisted"] is False
    finally:
        server.shutdown()
        server.server_close()
        worker.join(timeout=5)

    assert worker.is_alive() is False
    assert observed_surfaces == {"chat", "responses", "anthropic", "gemini"}


def test_standalone_http_server_loopback_preserves_native_stream_terminal_semantics(monkeypatch):
    monkeypatch.delenv("AXIO_FUSION_API_KEYS", raising=False)
    monkeypatch.delenv("AXIO_FUSION_ACCESS_LOG", raising=False)
    engine = FusionEngine(
        [normalize_profile({"provider": "unit", "model": "stream-loopback-model"})]
    )
    server = create_http_server(
        host="127.0.0.1",
        port=0,
        engine=engine,
        record_trace=False,
        record_runtime=False,
    )
    worker = threading.Thread(target=server.serve_forever, daemon=True)
    worker.start()
    secret_prompt = "SECRET_HTTP_STREAM_LOOPBACK_PROMPT_MUST_NOT_PERSIST"
    cases = [
        (
            "chat",
            "/v1/chat/completions",
            {
                "model": "axio-fast",
                "stream": True,
                "messages": [{"role": "user", "content": secret_prompt}],
            },
            "chat.completion.chunk",
            True,
        ),
        (
            "responses",
            "/v1/responses",
            {"model": "axio-terra", "stream": True, "input": secret_prompt},
            "event: response.completed",
            False,
        ),
        (
            "anthropic",
            "/v1/messages",
            {
                "model": "axio-pro",
                "stream": True,
                "messages": [{"role": "user", "content": secret_prompt}],
            },
            "event: message_stop",
            False,
        ),
        (
            "gemini",
            "/v1beta/models/axio-pro:streamGenerateContent?alt=sse",
            {"contents": [{"role": "user", "parts": [{"text": secret_prompt}]}]},
            "usageMetadata",
            False,
        ),
    ]
    observed_surfaces = set()
    try:
        host, port = server.server_address[:2]
        for surface, path, payload, marker, has_openai_done_sentinel in cases:
            request = urllib.request.Request(
                f"http://{host}:{port}{path}",
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urllib.request.urlopen(request, timeout=5) as response:
                stream = response.read().decode("utf-8")
                status = response.status
                content_type = str(response.headers.get("Content-Type") or "")

            observed_surfaces.add(surface)
            assert status == 200
            assert content_type.startswith("text/event-stream")
            assert marker in stream
            assert ("data: [DONE]" in stream) is has_openai_done_sentinel
            assert secret_prompt not in stream
            assert "raw_prompt_persisted" in stream
    finally:
        server.shutdown()
        server.server_close()
        worker.join(timeout=5)

    assert worker.is_alive() is False
    assert observed_surfaces == {"chat", "responses", "anthropic", "gemini"}


def test_standalone_cli_serve_exits_cleanly_after_keyboard_interrupt(monkeypatch):
    calls = []

    def interrupted_serve(*, host, port, live):
        calls.append({"host": host, "port": port, "live": live})
        raise KeyboardInterrupt

    monkeypatch.setattr(cli_module, "serve", interrupted_serve)

    assert fusion_cli_main(["serve", "--host", "127.0.0.1", "--port", "8793", "--live"]) == 0
    assert calls == [{"host": "127.0.0.1", "port": 8793, "live": True}]


def test_standalone_public_generation_error_redacts_internal_trace():
    class FailingClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            del profile, request, prompt, system, timeout
            raise RuntimeError("SECRET_PROVIDER_FAILURE_SHOULD_NOT_LEAK")

    engine = FusionEngine(
        [
            normalize_profile(
                {
                    "provider": "secret-provider-alpha",
                    "model": "secret-model-alpha",
                    "capabilities": {"daily_work": 0.9, "structured_output": 0.9},
                }
            )
        ],
        client=FailingClient(),
        cache_enabled=False,
    )

    status, _, body = handle_request(
        method="POST",
        path="/v1/chat/completions",
        body=json.dumps(
            {
                "model": "axio-fast",
                "live": True,
                "messages": [{"role": "user", "content": "trigger provider failure"}],
            }
        ),
        engine=engine,
    )
    payload = json.loads(body.decode("utf-8"))
    metadata = payload["metadata"]
    summary = metadata["trace_summary"]
    serialized = json.dumps(payload, ensure_ascii=False)

    assert status == 502
    assert payload["error"]["code"] == "provider_execution_failed"
    assert "trace" not in metadata
    assert summary["schema"] == "axio_fusion_api.public_error_trace_summary.v1"
    assert summary["candidate_status_counts"]["failed"] == 1
    assert summary["candidate_error_type_counts"]["RuntimeError"] == 1
    assert summary["raw_provider_names_persisted"] is False
    assert metadata["internal_details_redacted"] is True
    assert metadata["provider_identifiers_redacted"] is True
    assert "secret-provider-alpha" not in serialized
    assert "secret-model-alpha" not in serialized
    assert "secret-provider-alpha/secret-model-alpha" not in serialized
    assert "SECRET_PROVIDER_FAILURE_SHOULD_NOT_LEAK" not in serialized


