def test_standalone_gateway_operator_auth_separates_control_plane(monkeypatch):
    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "pub-key")
    monkeypatch.setenv("AXIO_FUSION_OPERATOR_API_KEYS", "op-key")
    engine = FusionEngine([normalize_profile({"provider": "unit", "model": "fast-model"})])

    generation_status, _, generation_body = handle_request(
        method="POST",
        path="/v1/chat/completions",
        headers={"x-api-key": "pub-key"},
        body=json.dumps({"model": "axio-fast", "messages": [{"role": "user", "content": "hello"}]}),
        engine=engine,
    )
    generation = json.loads(generation_body.decode("utf-8"))

    assert generation_status == 200
    assert generation["model"] == "axio-fast"

    control_cases = [
        ("GET", "/v1/axio/runtime", None),
        ("POST", "/v1/axio/route-plan", {"request": {"model": "axio-fast", "messages": [{"role": "user", "content": "plan"}]}}),
        ("POST", "/v1/inventory", {"live": False}),
        ("POST", "/v1/axio/feedback", {"response_id": "unit", "score": 1, "notes": "private operator note"}),
        ("POST", "/v1/axio/agent-outcome", {"task_success": True, "task_id": "private-task"}),
        (
            "POST",
            "/v1/axio/tools/execute",
            {"role": "primary_solver", "call": {"name": "math_eval", "arguments": {"expression": "1 + 1"}}},
        ),
    ]

    for method, path, payload in control_cases:
        status, _, body = handle_request(
            method=method,
            path=path,
            headers={"x-api-key": "pub-key"},
            body=json.dumps(payload) if payload is not None else None,
            engine=engine,
        )
        forbidden = json.loads(body.decode("utf-8"))
        serialized = json.dumps(forbidden, ensure_ascii=False)

        assert status == 403
        assert forbidden["error"]["code"] == "operator_authorization_required"
        assert forbidden["metadata"]["operator_endpoint"] is True
        assert forbidden["metadata"]["raw_api_keys_persisted"] is False
        assert "pub-key" not in serialized
        assert "op-key" not in serialized

    for method, path, payload in control_cases:
        status, _, body = handle_request(
            method=method,
            path=path,
            headers={"x-axio-operator-key": "op-key"},
            body=json.dumps(payload) if payload is not None else None,
            engine=engine,
        )
        serialized = body.decode("utf-8")

        assert status == 200
        assert "pub-key" not in serialized
        assert "op-key" not in serialized

    bearer_status, _, bearer_body = handle_request(
        method="POST",
        path="/v1/axio/route-plan",
        headers={"authorization": "Bearer op-key"},
        body=json.dumps({"request": {"model": "axio-fast", "messages": [{"role": "user", "content": "plan"}]}}),
        engine=engine,
    )
    bearer_payload = json.loads(bearer_body.decode("utf-8"))

    assert bearer_status == 200
    assert bearer_payload["public_model"] == "axio-fast"


