def test_standalone_tool_execution_gateway_cli_and_artifact_are_safe(monkeypatch, tmp_path):
    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_ARTIFACT_DIR", str(tmp_path))
    secret_text = "SECRET_TOOL_TEXT_SHOULD_NOT_PERSIST"
    engine = FusionEngine([normalize_profile({"provider": "unit", "model": "fast-model"})])
    calls = [
        {"name": "math_eval", "arguments": {"expression": "2 + 3 * 4"}},
        {"name": "text_search", "arguments": {"text": f"alpha {secret_text} beta alpha", "query": "alpha"}},
        {"name": "shell_exec", "arguments": {"command": "rm -rf /"}, "approved": True},
    ]

    status, _, body = handle_request(
        method="POST",
        path="/v1/axio/tools/execute",
        body=json.dumps({"role": "primary_solver", "calls": calls, "max_tool_calls": 3}),
        engine=engine,
    )
    payload = json.loads(body.decode("utf-8"))
    artifact = (tmp_path / "tool_executions.jsonl").read_text(encoding="utf-8")
    call_file = tmp_path / "calls.json"
    call_file.write_text(json.dumps({"calls": calls[:2]}), encoding="utf-8")
    cli_output = tmp_path / "tool_cli.json"

    assert fusion_cli_main(
        [
            "tool-execute",
            "--role",
            "primary_solver",
            "--call-file",
            str(call_file),
            "--output",
            str(cli_output),
        ]
    ) == 0

    cli_payload = json.loads(cli_output.read_text(encoding="utf-8"))
    serialized_artifact = json.dumps({"artifact": artifact, "cli": cli_payload}, ensure_ascii=False)

    assert status == 200
    assert payload["success_count"] == 2
    assert payload["blocked_count"] == 1
    assert payload["results"][0]["result"]["value"] == 14
    assert payload["results"][1]["result"]["match_count"] == 2
    assert payload["results"][2]["status"] == "blocked"
    assert payload["results"][2]["error_code"] == "blocked_destructive_tools_disabled"
    assert cli_payload["success_count"] == 2
    assert secret_text not in serialized_artifact
    assert "rm -rf" not in serialized_artifact
    assert '"raw_tool_arguments_persisted": false' in artifact
    assert '"raw_tool_result_persisted": false' in artifact


def test_standalone_live_expert_tool_calls_execute_under_route_policy(monkeypatch, tmp_path):
    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_ARTIFACT_DIR", str(tmp_path))
    secret_text = "SECRET_AUTO_TOOL_TEXT_SHOULD_NOT_PERSIST"
    dangerous_command = "rm -rf /"

    class ToolCallingClient:
        def __init__(self):
            self.prompts = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            del profile, request, system, timeout
            self.prompts.append(prompt)
            assert "Available safe tool call contract" in prompt
            assert "tool_calls" in prompt
            return json.dumps(
                {
                    "answer": "need calculation",
                    "tool_calls": [
                        {"tool_index": 0, "name": "math_eval", "type": "function", "arguments": {"expression": "6 * 7"}},
                        {
                            "tool_index": 1,
                            "name": "text_search",
                            "type": "function",
                            "arguments": {"text": f"alpha {secret_text} beta alpha", "query": "alpha"},
                        },
                        {
                            "tool_index": 2,
                            "name": "shell_exec",
                            "type": "function",
                            "arguments": {"command": dangerous_command},
                            "approved": True,
                        },
                    ],
                    "evidence": [],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.8,
                }
            )

    fake = ToolCallingClient()
    profiles = [
        normalize_profile(
            {
                "provider": "unit",
                "model": "tool-model",
                "capabilities": {"agentic_tool_calling": 0.9, "daily_work": 0.8, "structured_output": 0.85},
            }
        )
    ]
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [{"role": "user", "content": "Use declared tools to calculate and search safely."}],
            "tools": [
                {"type": "function", "function": {"name": "math_eval"}},
                {"type": "function", "function": {"name": "text_search"}},
                {"type": "function", "function": {"name": "shell_exec"}},
            ],
        }
    )

    response = FusionEngine(profiles, client=fake).complete(request, live=True)
    candidate = response.candidates[0]
    safe_candidate = candidate.safe_dict()
    receipt = safe_execution_trace(response, tenant_key="auto-tool-test")
    artifact = (tmp_path / "tool_executions.jsonl").read_text(encoding="utf-8")
    serialized_safe = json.dumps(
        {"trace": response.trace, "receipt": receipt, "candidate": safe_candidate, "artifact": artifact},
        ensure_ascii=False,
    )

    assert len(fake.prompts) == 1
    assert response.trace["provider_call_count"] == 1
    assert response.trace["budget_lock"]["used_model_call_count"] == 1
    assert candidate.tool_execution["success_count"] == 2
    assert candidate.tool_execution["blocked_count"] == 1
    assert candidate.tool_execution["results"][0]["result"]["value"] == 42
    assert candidate.tool_execution["results"][1]["result"]["match_count"] == 2
    assert candidate.tool_execution["results"][2]["status"] == "blocked"
    assert candidate.tool_execution["results"][2]["error_code"] == "blocked_by_route_tool_policy"
    assert safe_candidate["tool_execution"]["success_count"] == 2
    assert safe_candidate["tool_execution"]["blocked_count"] == 1
    assert safe_candidate["tool_execution"]["raw_tool_arguments_persisted"] is False
    assert receipt["candidate_outputs"][0]["tool_execution"]["success_count"] == 2
    assert receipt["candidate_outputs"][0]["tool_execution"]["blocked_count"] == 1
    assert "42" in response.text
    assert "match_count" in response.text
    assert "blocked_by_route_tool_policy" in response.text
    assert secret_text not in serialized_safe
    assert dangerous_command not in serialized_safe
    assert "shell_exec" not in serialized_safe
    assert '"raw_tool_arguments_persisted": false' in artifact
    assert '"raw_tool_result_persisted": false' in artifact


def test_standalone_tool_execution_enforces_route_plan_tool_policy(monkeypatch, tmp_path):
    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_ARTIFACT_DIR", str(tmp_path))
    engine = FusionEngine(
        [
            normalize_profile({"provider": "unit", "model": "tool-router", "capabilities": {"agentic_tool_calling": 0.9, "daily_work": 0.8, "structured_output": 0.82, "critique": 0.74}}),
            normalize_profile({"provider": "judge", "model": "tool-judge", "capabilities": {"agentic_tool_calling": 0.72, "daily_work": 0.76, "structured_output": 0.9, "critique": 0.92}}),
        ]
    )
    route_request = canonicalize_payload(
        {
            "model": "axio-pro",
            "messages": [{"role": "user", "content": "Plan a safe tool workflow."}],
            "tools": [
                {"type": "function", "function": {"name": "math_eval"}},
                {"type": "function", "function": {"name": "shell_exec"}},
            ],
        }
    )
    route_plan = engine.complete(route_request, live=False).route_plan
    calls = [
        {"type": "function", "function": {"name": "math_eval", "arguments": json.dumps({"expression": "40 + 2"})}},
        {"type": "function", "function": {"name": "shell_exec", "arguments": json.dumps({"command": "rm -rf /"})}, "approved": True},
    ]

    status, _, body = handle_request(
        method="POST",
        path="/v1/axio/tools/execute",
        body=json.dumps({"role": "primary_solver", "route_plan": route_plan, "calls": calls}),
        engine=engine,
    )
    payload = json.loads(body.decode("utf-8"))
    route_plan_path = tmp_path / "route_plan.json"
    calls_path = tmp_path / "calls.json"
    cli_output_path = tmp_path / "tool_policy_cli.json"
    route_plan_path.write_text(json.dumps({"route_plan": route_plan}), encoding="utf-8")
    calls_path.write_text(json.dumps({"calls": calls}), encoding="utf-8")

    assert fusion_cli_main(
        [
            "tool-execute",
            "--role",
            "primary_solver",
            "--call-file",
            str(calls_path),
            "--tool-policy-file",
            str(route_plan_path),
            "--output",
            str(cli_output_path),
        ]
    ) == 0

    cli_payload = json.loads(cli_output_path.read_text(encoding="utf-8"))
    artifact = (tmp_path / "tool_executions.jsonl").read_text(encoding="utf-8")
    serialized_artifact = json.dumps({"artifact": artifact}, ensure_ascii=False)

    assert status == 200
    assert payload["route_tool_policy"]["enforced"] is True
    assert payload["route_tool_policy"]["role_found"] is True
    assert payload["success_count"] == 1
    assert payload["blocked_count"] == 1
    assert payload["results"][0]["status"] == "completed"
    assert payload["results"][0]["result"]["value"] == 42
    assert payload["results"][0]["route_tool_policy_enforced"] is True
    assert payload["results"][1]["status"] == "blocked"
    assert payload["results"][1]["error_code"] == "blocked_by_route_tool_policy"
    assert cli_payload["route_tool_policy"]["enforced"] is True
    assert cli_payload["results"][1]["error_code"] == "blocked_by_route_tool_policy"
    assert "40 + 2" not in serialized_artifact
    assert "rm -rf" not in serialized_artifact
    assert "shell_exec" not in serialized_artifact
    assert '"route_tool_policy_enforced": true' in artifact
    assert '"raw_tool_schema_persisted": false' in artifact


def test_standalone_tool_execution_blocks_judge_and_unknown_tools():
    engine = FusionEngine([normalize_profile({"provider": "unit", "model": "fast-model"})])

    judge_status, _, judge_body = handle_request(
        method="POST",
        path="/v1/axio/tools/execute",
        body=json.dumps(
            {
                "role": "judge",
                "call": {"name": "math_eval", "arguments": {"expression": "1 + 1"}},
            }
        ),
        engine=engine,
    )
    unknown_status, _, unknown_body = handle_request(
        method="POST",
        path="/v1/axio/tools/execute",
        body=json.dumps(
            {
                "role": "primary_solver",
                "call": {"name": "unknown_tool", "arguments": {}},
            }
        ),
        engine=engine,
    )
    judge = json.loads(judge_body.decode("utf-8"))
    unknown = json.loads(unknown_body.decode("utf-8"))

    assert judge_status == 200
    assert unknown_status == 200
    assert judge["results"][0]["status"] == "blocked"
    assert judge["results"][0]["error_code"] == "blocked_role_read_only"
    assert unknown["results"][0]["status"] == "blocked"
    assert unknown["results"][0]["error_code"] == "blocked_unknown_tool"

    fusion_status, _, fusion_body = handle_request(
        method="POST",
        path="/v1/axio/tools/execute",
        body=json.dumps(
            {
                "role": "primary_solver",
                "call": {"type": "fusion", "name": "openrouter:fusion"},
            }
        ),
        engine=engine,
    )
    fusion = json.loads(fusion_body.decode("utf-8"))

    assert fusion_status == 200
    assert fusion["results"][0]["status"] == "blocked"
    assert fusion["results"][0]["tool_category"] == "fusion_plugin"
    assert fusion["results"][0]["error_code"] == "blocked_fusion_plugin_route_only"


def test_standalone_registry_calibration_updates_dynamic_model_profile(tmp_path):
    registry_path = tmp_path / "registry.json"
    registry_path.write_text(
        json.dumps(
            {
                "models": [
                    {
                        "provider": "unit",
                        "model": "fast-good",
                        "api_format": "chat",
                        "capabilities": {
                            "logic": 0.62,
                            "daily_work": 0.62,
                            "structured_output": 0.65,
                            "critique": 0.60,
                        },
                    },
                    {
                        "provider": "unit",
                        "model": "static-strong-but-down",
                        "api_format": "chat",
                        "capabilities": {
                            "logic": 0.95,
                            "daily_work": 0.95,
                            "structured_output": 0.95,
                            "critique": 0.95,
                        },
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    probe_path = tmp_path / "probe.json"
    probe_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.provider_probe.v1",
                "probes": [
                    {
                        "profile_id": "unit/fast-good",
                        "provider": "unit",
                        "model": "fast-good",
                        "status": "available",
                        "latency_ms": 420,
                        "raw_provider_output_persisted": False,
                    },
                    {
                        "profile_id": "unit/static-strong-but-down",
                        "provider": "unit",
                        "model": "static-strong-but-down",
                        "status": "failed",
                        "latency_ms": 2200,
                        "raw_provider_output_persisted": False,
                    },
                ],
            }
        ),
        encoding="utf-8",
    )
    benchmark_path = tmp_path / "benchmark.json"
    benchmark_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.multiple_choice_benchmark_run.v1",
                "suite_id": "arc_challenge",
                "candidate_id": "provider::unit/fast-good",
                "case_count": 10,
                "attempted_count": 10,
                "correct_count": 9,
                "accuracy": 0.9,
                "raw_prompt_persisted": False,
            }
        ),
        encoding="utf-8",
    )
    feedback_path = tmp_path / "feedback.jsonl"
    feedback_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.feedback_receipt.v1",
                "score": 0.8,
                "accepted": True,
                "route_snapshot": {
                    "selected_profile_hashes": [sha256_text("unit/fast-good")],
                    "strategy": "terra_cost_guarded_fusion",
                    "task_type": "logic_reasoning",
                },
                "training_signal": {"eligible_for_router_learning": True},
                "raw_feedback_text_persisted": False,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    trace_path = tmp_path / "trace.jsonl"
    trace_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.execution_trace_receipt.v1",
                "routing_decision": {
                    "selected_profile_hashes": [sha256_text("unit/fast-good")],
                    "strategy": "terra_cost_guarded_fusion",
                },
                "request_analysis": {"task_type": "logic_reasoning"},
                "cost": {"actual_cost_usd": 0.001, "provider_call_count": 1},
                "latency_ms": 430,
                "raw_prompt_persisted": False,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    report_path = tmp_path / "calibration.json"
    updated_registry_path = tmp_path / "updated_registry.json"

    blocked_calibration = build_registry_calibration(
        registry_path=registry_path,
        probe_paths=[probe_path],
        benchmark_paths=[benchmark_path],
        feedback_paths=[feedback_path],
        trace_paths=[trace_path],
    )
    assert blocked_calibration["application_contract"]["safe_to_write_registry"] is False
    assert blocked_calibration["application_contract"]["benchmark_calibration_blocked"] is True
    assert blocked_calibration["input_artifacts"]["benchmark_row_count"] == 0
    assert "benchmark_calibration_requires_explicit_opt_in" in blocked_calibration["application_contract"]["blocker_reason_codes"]
    blocked_report_path = tmp_path / "blocked_calibration.json"
    blocked_registry_path = tmp_path / "blocked_updated_registry.json"
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "calibrate-registry",
            "--probe-file",
            str(probe_path),
            "--benchmark-file",
            str(benchmark_path),
            "--output",
            str(blocked_report_path),
            "--updated-registry-output",
            str(blocked_registry_path),
        ]
    ) == 2
    assert blocked_report_path.exists()
    assert not blocked_registry_path.exists()

    calibration = build_registry_calibration(
        registry_path=registry_path,
        probe_paths=[probe_path],
        benchmark_paths=[benchmark_path],
        feedback_paths=[feedback_path],
        trace_paths=[trace_path],
        allow_benchmark_calibration=True,
    )
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "calibrate-registry",
            "--probe-file",
            str(probe_path),
            "--benchmark-file",
            str(benchmark_path),
            "--allow-benchmark-calibration",
            "--feedback-file",
            str(feedback_path),
            "--trace-file",
            str(trace_path),
            "--output",
            str(report_path),
            "--updated-registry-output",
            str(updated_registry_path),
        ]
    ) == 0

    updated = json.loads(updated_registry_path.read_text(encoding="utf-8"))
    fast = next(row for row in updated["models"] if row["model"] == "fast-good")
    down = next(row for row in updated["models"] if row["model"] == "static-strong-but-down")
    route = FusionEngine(load_registry(updated_registry_path)).complete(
        canonicalize_payload(
            {
                "model": "axio-fast",
                "messages": [{"role": "user", "content": "simple logic task"}],
            }
        ),
        live=False,
    ).route_plan
    serialized = json.dumps(calibration, ensure_ascii=False)

    assert calibration["schema"] == "axio_fusion_api.registry_calibration.v1"
    assert calibration["input_artifacts"]["probe_row_count"] == 2
    assert fast["health"] == "available"
    assert fast["availability"] == 1.0
    assert fast["recent_success_rate"] == 1.0
    assert fast["p50_latency_ms"] in {425, 430}
    assert fast["capabilities"]["logic"] > 0.62
    assert down["health"] == "unavailable"
    assert down["availability"] == 0.0
    assert route["selected_models"][0]["profile_id"] == "unit/fast-good"
    assert report_path.exists()
    assert calibration["application_contract"]["raw_prompt_persisted"] is False
    assert "SECRET" not in serialized


def test_standalone_learning_report_uses_feedback_without_raw_text(monkeypatch, tmp_path):
    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_ARTIFACT_DIR", str(tmp_path))
    engine = FusionEngine([normalize_profile({"provider": "unit", "model": "fast-model"})])
    secret_feedback = "SECRET_LEARNING_FEEDBACK_SHOULD_NOT_PERSIST"
    route_plan = {
        "public_model": "axio-pro",
        "strategy": "pro_panel_judge_escalation",
        "request_analysis": {
            "task_type": "science_research",
            "privacy_level": "internal",
            "complexity": 0.8,
            "risk": 0.4,
            "uncertainty": 0.6,
        },
        "selected_models": [{"profile_id": "provider/model-a"}],
    }
    fusion_trace = {
        "actual_cost_usd": 0.01,
        "latency_ms": 1234,
        "provider_call_count": 3,
        "raw_candidate_text_persisted": False,
    }

    status, _, body = handle_request(
        method="POST",
        path="/v1/axio/feedback",
        body=json.dumps(
            {
                "response_id": "fusion-learning",
                "request_fingerprint": "fingerprint-learning",
                "score": -0.2,
                "accepted": False,
                "notes": secret_feedback,
                "route_plan": route_plan,
                "fusion_trace": fusion_trace,
            }
        ),
        engine=engine,
    )
    feedback_path = tmp_path / "feedback.jsonl"
    report = build_learning_signal_report(
        feedback_paths=[feedback_path],
        min_examples_for_policy_update=2,
    )
    report_path = tmp_path / "learning.json"

    assert fusion_cli_main(
        [
            "learning-report",
            "--feedback-file",
            str(feedback_path),
            "--min-examples",
            "2",
            "--output",
            str(report_path),
        ]
    ) == 0

    receipt = json.loads(body.decode("utf-8"))
    serialized = json.dumps({"receipt": receipt, "report": report, "artifact": feedback_path.read_text(encoding="utf-8")}, ensure_ascii=False)

    assert status == 200
    assert receipt["route_snapshot"]["strategy"] == "pro_panel_judge_escalation"
    assert receipt["route_snapshot"]["selected_profile_hashes"]
    assert report["eligible_feedback_count"] == 1
    assert report["policy_suggestions"][0]["kind"] == "collect_more_feedback"
    assert report["training_dataset_manifest"]["raw_prompt_persisted"] is False
    assert report_path.exists()
    assert secret_feedback not in serialized
    assert "provider/model-a" not in serialized


def test_standalone_learning_report_keeps_benchmark_scorecards_diagnostic_only(tmp_path):
    scorecard_path = tmp_path / "scorecard.json"
    blocked_output = tmp_path / "learning_blocked.json"
    admitted_output = tmp_path / "learning_diagnostic.json"
    scorecard_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.benchmark_scorecard.v1",
                "candidates": [
                    {"candidate_id": "axio-pro", "case_count": 20, "accuracy": 0.61},
                    {"candidate_id": "provider::" + sha256_text("rank-1"), "case_count": 20, "accuracy": 0.72},
                ],
            }
        ),
        encoding="utf-8",
    )

    blocked = build_learning_signal_report(scorecard_paths=[scorecard_path])
    admitted = build_learning_signal_report(
        scorecard_paths=[scorecard_path],
        allow_benchmark_diagnostics=True,
    )

    assert blocked["benchmark_summary"]["scorecard_count"] == 0
    assert blocked["benchmark_learning_contract"]["benchmark_diagnostics_admitted"] is False
    assert blocked["benchmark_learning_contract"]["blocked_reason_codes"] == [
        "benchmark_scorecard_diagnostic_requires_explicit_opt_in"
    ]
    assert blocked["training_dataset_manifest"]["benchmark_scores_used_for_training"] is False
    assert not any(
        item["kind"] == "keep_baseline_guardrail"
        for item in blocked["policy_suggestions"]
    )

    assert admitted["benchmark_summary"]["scorecard_count"] == 1
    assert admitted["benchmark_learning_contract"]["benchmark_diagnostics_admitted"] is True
    assert admitted["benchmark_diagnostic_suggestions"][0]["automatic_policy_change"] is False
    assert not any(
        item["kind"] == "keep_baseline_guardrail"
        for item in admitted["policy_suggestions"]
    )

    assert fusion_cli_main(
        [
            "learning-report",
            "--scorecard-file",
            str(scorecard_path),
            "--output",
            str(blocked_output),
        ]
    ) == 2
    assert fusion_cli_main(
        [
            "learning-report",
            "--scorecard-file",
            str(scorecard_path),
            "--allow-benchmark-diagnostics",
            "--output",
            str(admitted_output),
        ]
    ) == 0
    assert json.loads(admitted_output.read_text(encoding="utf-8"))["benchmark_learning_contract"][
        "benchmark_scores_used_for_router_learning"
    ] is False


