def test_standalone_responses_text_fallback_preserves_native_tool_contract(monkeypatch):
    profile = normalize_profile(
        {
            "provider": "unit",
            "model": "responses-model",
            "api_format": "responses",
            "supports_tools": True,
        }
    )
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [{"role": "user", "content": "look this up"}],
            "tools": [
                {
                    "type": "function",
                    "function": {
                        "name": "lookup",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ],
        }
    )
    payloads = []

    def reject_typed_input(profile, path, payload, *, timeout, **kwargs):
        payloads.append(payload)
        raise provider_module.ProviderExecutionError(
            "typed input rejected",
            error_code="http_error",
            http_status=400,
        )

    monkeypatch.setattr(provider_module, "_post_json", reject_typed_input)

    with pytest.raises(provider_module.ProviderExecutionError):
        provider_module.HTTPProviderClient().complete_turn(
            profile,
            request,
            prompt=request.prompt,
            system=request.system,
            timeout=1.0,
        )

    assert len(payloads) == 1
    assert isinstance(payloads[0]["input"], list)
    assert payloads[0]["tools"]


def test_standalone_responses_text_fallback_remains_available_for_plain_text_turns(monkeypatch):
    profile = normalize_profile(
        {
            "provider": "unit",
            "model": "responses-model",
            "api_format": "responses",
        }
    )
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [{"role": "user", "content": "plain text request"}],
        }
    )
    payloads = []

    def typed_then_text(profile, path, payload, *, timeout, **kwargs):
        payloads.append(payload)
        if len(payloads) == 1:
            raise provider_module.ProviderExecutionError(
                "typed input rejected",
                error_code="http_error",
                http_status=400,
            )
        return {"output_text": "text fallback answer"}

    monkeypatch.setattr(provider_module, "_post_json", typed_then_text)
    completion = provider_module.HTTPProviderClient().complete_turn(
        profile,
        request,
        prompt=request.prompt,
        system=request.system,
        timeout=1.0,
    )

    assert completion.text == "text fallback answer"
    assert len(payloads) == 2
    assert isinstance(payloads[0]["input"], list)
    assert isinstance(payloads[1]["input"], str)


