def test_standalone_provider_retries_transient_post_failure_without_secret_leakage(monkeypatch):
    captured = []
    state = {"failures_before_success": 1, "always_fail": False}

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def fake_urlopen(request, timeout=None):
        headers = {key.lower(): value for key, value in request.header_items()}
        captured.append({"method": request.get_method(), "auth": headers.get("authorization", ""), "timeout": timeout})
        if state["always_fail"] or state["failures_before_success"] > 0:
            state["failures_before_success"] = max(0, state["failures_before_success"] - 1)
            raise urllib.error.HTTPError(
                request.full_url,
                503,
                "Service Unavailable",
                {},
                io.BytesIO(b"TRANSIENT_PROVIDER_BODY_SECRET retry-secret"),
            )
        return FakeResponse({"choices": [{"message": {"content": "retry ok"}}]})

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("RETRY_BASE_URL", "https://retry.example/v1")
    monkeypatch.setenv("RETRY_API_KEY", "retry-secret")
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_MAX_ATTEMPTS_PER_KEY", "2")
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_RETRY_BACKOFF_MS", "0")
    profile = normalize_profile(
        {
            "provider": "retry-provider",
            "model": "retry-chat",
            "api_format": "chat",
            "base_url_env": "RETRY_BASE_URL",
            "api_key_env": "RETRY_API_KEY",
        }
    )
    request = canonicalize_payload({"model": "axio-fast", "messages": [{"role": "user", "content": "hello"}]})

    text = provider_module.HTTPProviderClient().complete(
        profile,
        request,
        prompt=request.prompt,
        system=request.system,
        timeout=3.0,
    )
    state["always_fail"] = True
    captured_after_success = len(captured)
    try:
        provider_module.HTTPProviderClient().complete(
            profile,
            request,
            prompt=request.prompt,
            system=request.system,
            timeout=3.0,
        )
    except provider_module.ProviderExecutionError as exc:
        failure_text = str(exc)
    else:  # pragma: no cover - the fake transport must fail this branch
        raise AssertionError("expected ProviderExecutionError")

    assert text == "retry ok"
    assert captured_after_success == 2
    assert len(captured) == 4
    assert all(row["method"] == "POST" for row in captured)
    assert "transport_attempt_count=2" in failure_text
    assert "retry-secret" not in failure_text
    assert "TRANSIENT_PROVIDER_BODY_SECRET" not in failure_text
    assert "https://retry.example" not in failure_text
    assert "raw_provider_body_persisted=false" in failure_text
    assert "secrets_persisted=false" in failure_text


def test_standalone_nvidia_profile_requires_explicit_base_url_before_network_access(monkeypatch):
    calls = []
    base_url_env = "UNCONFIGURED_NVIDIA_BASE_URL_FOR_TEST"
    api_key_env = "UNCONFIGURED_NVIDIA_API_KEY_FOR_TEST"
    secret_key = "nvidia-missing-url-secret"

    def fail_urlopen(request, timeout=None):
        calls.append(request.full_url)
        raise AssertionError("a missing base URL must block before network access")

    monkeypatch.delenv(base_url_env, raising=False)
    monkeypatch.setenv(api_key_env, secret_key)
    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fail_urlopen)
    profile = normalize_profile(
        {
            "provider": "nvidia",
            "model": "nvidia-profile-without-explicit-endpoint",
            "api_format": "chat",
            "base_url_env": base_url_env,
            "api_key_env": api_key_env,
        }
    )
    request = canonicalize_payload(
        {"model": "axio-fast", "messages": [{"role": "user", "content": "hello"}]}
    )
    engine = FusionEngine([profile])

    models_status, _, models_body = handle_request(method="GET", path="/v1/models", engine=engine)
    models = json.loads(models_body.decode("utf-8"))
    try:
        provider_module.HTTPProviderClient().complete(
            profile,
            request,
            prompt=request.prompt,
            system=request.system,
        )
    except provider_module.ProviderExecutionError as exc:
        failure_text = str(exc)
        error_code = exc.error_code
    else:  # pragma: no cover - a missing endpoint must be rejected locally
        raise AssertionError("expected ProviderExecutionError")

    assert calls == []
    assert error_code == "base_url_missing"
    assert failure_text == "provider base URL is not configured"
    assert base_url_env not in failure_text
    assert secret_key not in failure_text
    assert models_status == 200
    assert models["registry_summary"]["live_credential_summary"]["credential_ready"] is False
    assert models["registry_summary"]["all_listed_models_live_usable"] is False


@pytest.mark.parametrize(
    ("unsafe_base_url", "expected_reason"),
    (
        ("ftp://provider.invalid/v1", "base_url_scheme_not_allowed"),
        ("https://operator:credential@provider.invalid/v1", "base_url_embedded_auth_not_allowed"),
        ("https://provider.invalid/v1?trace=private", "base_url_query_not_allowed"),
        ("https://provider.invalid/v1#private", "base_url_fragment_not_allowed"),
        ("https://provider.invalid:99999/v1", "base_url_invalid_port"),
        ("https://provider.invalid/v1 path", "base_url_contains_whitespace"),
    ),
)
def test_standalone_unsafe_provider_base_url_blocks_transport_and_readiness_without_leakage(
    monkeypatch,
    unsafe_base_url,
    expected_reason,
):
    calls = []
    base_url_env = "UNIT_UNSAFE_PROVIDER_BASE_URL"
    api_key_env = "UNIT_UNSAFE_PROVIDER_API_KEY"
    api_key = "unit-unsafe-provider-key"

    def fail_urlopen(request, timeout=None):
        del timeout
        calls.append(request.full_url)
        raise AssertionError("an invalid provider base URL must block before network access")

    monkeypatch.setenv(base_url_env, unsafe_base_url)
    monkeypatch.setenv(api_key_env, api_key)
    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fail_urlopen)
    profile = normalize_profile(
        {
            "provider": "unit-unsafe-provider",
            "model": "unit-unsafe-model",
            "api_format": "chat",
            "base_url_env": base_url_env,
            "api_key_env": api_key_env,
        }
    )
    request = canonicalize_payload(
        {"model": "axio-fast", "messages": [{"role": "user", "content": "validate endpoint"}]}
    )

    base_url_receipt = provider_module.provider_base_url_readiness(unsafe_base_url)
    credential_receipt = provider_module.profile_credential_readiness(profile)
    dry_discovery = provider_module._dry_model_discovery_report(profile)
    model_discovery = provider_module._safe_list_models(profile, timeout=1.0)
    with pytest.raises(provider_module.ProviderExecutionError) as exc_info:
        provider_module.HTTPProviderClient().complete(
            profile,
            request,
            prompt=request.prompt,
            system=request.system,
            timeout=1.0,
        )
    serialized = json.dumps(
        {
            "base_url": base_url_receipt,
            "credentials": credential_receipt,
            "dry": dry_discovery,
            "models": model_discovery,
            "error": str(exc_info.value),
        },
        ensure_ascii=False,
    )

    assert calls == []
    assert base_url_receipt["configured"] is True
    assert base_url_receipt["valid"] is False
    assert base_url_receipt["reason_code"] == expected_reason
    assert credential_receipt["base_url_configured"] is True
    assert credential_receipt["base_url_valid"] is False
    assert credential_receipt["base_url_reason_code"] == expected_reason
    assert credential_receipt["credential_ready"] is False
    assert dry_discovery["blockers"] == [expected_reason]
    assert model_discovery["blockers"] == [expected_reason]
    assert model_discovery["network_calls_performed"] is False
    assert exc_info.value.error_code == "base_url_invalid"
    assert str(exc_info.value) == "provider base URL is invalid"
    assert unsafe_base_url not in serialized
    assert api_key not in serialized


