    assert row["raw_provider_body_persisted"] is False
    assert row["raw_provider_url_persisted"] is False
    assert "fallback-secret" not in serialized
    assert "RESPONSES_TYPED_INPUT_SECRET" not in serialized
    assert "https://fallback.example" not in serialized
    assert report["secrets_persisted"] is False


