def test_standalone_provider_rotates_gemini_query_keys_and_sanitizes_failures(monkeypatch):
    captured_urls = []
    captured_payloads = []

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def fake_urlopen(request, timeout=None):
        captured_urls.append(request.full_url)
        if request.data:
            captured_payloads.append(json.loads(request.data.decode("utf-8")))
        if "bad-gemini-key" in request.full_url:
            raise urllib.error.HTTPError(
                request.full_url,
                429,
                "Too Many Requests",
                {},
                io.BytesIO(b"GEMINI_PROVIDER_BODY_SECRET bad-gemini-key"),
            )
        return FakeResponse(
            {
                "candidates": [
                    {"content": {"parts": [{"text": "gemini rotated ok"}]}}
                ]
            }
        )

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("GEMINI_BASE_URL", "https://gemini.example/v1")
    monkeypatch.setenv("GEMINI_API_KEY", "bad-gemini-key,good-gemini-key")
    profile = normalize_profile(
        {
            "provider": "gemini",
            "model": "gemini-test",
            "api_format": "gemini",
            "base_url_env": "GEMINI_BASE_URL",
            "api_key_env": "GEMINI_API_KEY",
            "traffic_control": {"rate_limit_key_pool": "independent"},
        }
    )
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "contents": [{"role": "user", "parts": [{"text": "hello"}]}],
            "generationConfig": {
                "temperature": 0,
                "maxOutputTokens": 77,
                "topP": 0.73,
                "stopSequences": ["END"],
            },
        },
        api_format="gemini",
    )
    explicit_zero_top_p_request = canonicalize_payload(
        {
            "model": "axio-fast",
            "contents": [{"role": "user", "parts": [{"text": "hello"}]}],
            "top_p": 0,
            "generationConfig": {"topP": 0.73},
        },
        api_format="gemini",
    )

    text = provider_module.HTTPProviderClient().complete(
        profile,
        request,
        prompt=request.prompt,
        system=request.system,
    )
    monkeypatch.setenv("GEMINI_API_KEY", "bad-gemini-key")
    try:
        provider_module.HTTPProviderClient().complete(
            profile,
            request,
            prompt=request.prompt,
            system=request.system,
        )
    except provider_module.ProviderExecutionError as exc:
        failure_text = str(exc)
    else:  # pragma: no cover - the fake transport must fail this branch
        raise AssertionError("expected ProviderExecutionError")

    assert text == "gemini rotated ok"
    assert request.temperature == 0.0
    assert request.top_p == 0.73
    assert explicit_zero_top_p_request.top_p == 0.0
    assert captured_payloads[0]["generationConfig"]["temperature"] == 0.0
    assert captured_payloads[0]["generationConfig"]["maxOutputTokens"] == 77
    assert captured_payloads[0]["generationConfig"]["topP"] == 0.73
    assert captured_payloads[0]["generationConfig"]["stopSequences"] == ["END"]
    assert "key=bad-gemini-key" in captured_urls[0]
    assert "key=good-gemini-key" in captured_urls[1]
    assert "bad-gemini-key" not in failure_text
    assert "good-gemini-key" not in failure_text
    assert "GEMINI_PROVIDER_BODY_SECRET" not in failure_text
    assert "key_attempt_count=1" in failure_text
    assert "raw_provider_body_persisted=false" in failure_text
    assert "secrets_persisted=false" in failure_text


