def test_standalone_model_scoped_provider_config_probes_without_provider_discovery(monkeypatch):
    _clear_fusion_provider_env_for_test(monkeypatch)
    provider_configs = {
        "providers": [
            {
                "provider": "model-scoped-channel",
                "models": [
                    {
                        "model": "scoped-chat-solver",
                        "api_format": "chat/completions",
                        "base_url_env": "SCOPED_CHAT_BASE_URL",
                        "api_key_env": "SCOPED_CHAT_API_KEY",
                        "capabilities": {"code": 0.92, "logic": 0.88},
                    },
                    {
                        "model": "scoped-responses-critic",
                        "api_format": "responses",
                        "base_url_env": "SCOPED_RESPONSES_BASE_URL",
                        "api_key_env": "SCOPED_RESPONSES_API_KEY",
                        "capabilities": {"critique": 0.95, "structured_output": 0.91},
                    },
                    {
                        "model": "scoped-anthropic-judge",
                        "api_format": "anthropic",
                        "base_url_env": "SCOPED_ANTHROPIC_BASE_URL",
                        "api_key_env": "SCOPED_ANTHROPIC_API_KEY",
                        "capabilities": {"critique": 0.97, "daily_work": 0.84},
                    },
                    {
                        "model": "scoped-gemini-worker",
                        "api_format": "gemini",
                        "base_url_env": "SCOPED_GEMINI_BASE_URL",
                        "api_key_env": "SCOPED_GEMINI_API_KEY",
                        "capabilities": {"multilingual": 0.93, "long_context": 0.9},
                    },
                ],
            }
        ]
    }
    captured = []

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def fake_urlopen(request, timeout=None):
        captured.append({"url": request.full_url, "method": request.get_method()})
        if request.get_method() == "GET":
            raise AssertionError("model-scoped configuration must not call provider /models")
        if request.full_url.endswith("/chat/completions"):
            return FakeResponse({"choices": [{"message": {"content": "AXIO_PROBE_OK"}}]})
        if request.full_url.endswith("/responses"):
            return FakeResponse({"output_text": "AXIO_PROBE_OK"})
        if request.full_url.endswith("/messages"):
            return FakeResponse({"content": [{"type": "text", "text": "AXIO_PROBE_OK"}]})
        if ":streamGenerateContent" in request.full_url or ":generateContent" in request.full_url:
            return FakeResponse({"candidates": [{"content": {"parts": [{"text": "AXIO_PROBE_OK"}]}}]})
        raise AssertionError(f"unexpected url {request.full_url}")

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_CONFIGS", json.dumps(provider_configs))
    monkeypatch.setenv("SCOPED_CHAT_BASE_URL", "https://scoped-chat-secret.example/v1")
    monkeypatch.setenv("SCOPED_CHAT_API_KEY", "scoped-chat-secret")
    monkeypatch.setenv("SCOPED_RESPONSES_BASE_URL", "https://scoped-responses-secret.example/v1")
    monkeypatch.setenv("SCOPED_RESPONSES_API_KEY", "scoped-responses-secret")
    monkeypatch.setenv("SCOPED_ANTHROPIC_BASE_URL", "https://scoped-anthropic-secret.example/v1")
    monkeypatch.setenv("SCOPED_ANTHROPIC_API_KEY", "scoped-anthropic-secret")
    monkeypatch.setenv("SCOPED_GEMINI_BASE_URL", "https://scoped-gemini-secret.example/v1")
    monkeypatch.setenv("SCOPED_GEMINI_API_KEY", "scoped-gemini-secret")

    profiles = load_registry()
    report = probe_exposed_provider_models(
        providers=["model-scoped-channel"],
        live=True,
        max_workers=1,
    )
    redacted = provider_module.redact_provider_probe_artifact(report)
    serialized = json.dumps({"report": report, "redacted": redacted}, ensure_ascii=False)

    assert {profile.model for profile in profiles} == {
        "scoped-chat-solver",
        "scoped-responses-critic",
        "scoped-anthropic-judge",
        "scoped-gemini-worker",
    }
    assert {profile.api_format for profile in profiles} == {"chat", "responses", "anthropic", "gemini"}
    assert report["provider_seed_count"] == 0
    assert report["discovered_model_count"] == 0
    assert report["configured_static_model_count"] == 4
    assert report["model_scoped_configured_model_count"] == 4
    assert report["candidate_model_count"] == 4
    assert report["probe_report"]["available_count"] == 4
    assert report["policy"]["model_discovery_attempted"] is False
    assert report["policy"]["provider_level_discovery_skipped_for_model_scoped_config"] is True
    assert all(row["method"] == "POST" for row in captured)
    assert any(row["url"].endswith("/chat/completions") for row in captured)
    assert any(row["url"].endswith("/responses") for row in captured)
    assert any(row["url"].endswith("/messages") for row in captured)
    assert any(":streamGenerateContent" in row["url"] for row in captured)
    assert "model-scoped-channel" not in json.dumps(redacted, ensure_ascii=False)
    assert "scoped-chat-solver" not in json.dumps(redacted, ensure_ascii=False)
    assert "SCOPED_CHAT_BASE_URL" not in json.dumps(redacted, ensure_ascii=False)
    assert "scoped-chat-secret" not in serialized
    assert "https://scoped-chat-secret.example" not in serialized
    assert "scoped-responses-secret" not in serialized
    assert "scoped-anthropic-secret" not in serialized
    assert "scoped-gemini-secret" not in serialized


def test_standalone_shared_endpoint_provider_without_static_models_is_selected_for_discovery(monkeypatch):
    _clear_fusion_provider_env_for_test(monkeypatch)
    provider_configs = {
        "providers": [
            {
                "provider": "shared-discovery-channel",
                "api_format": "responses",
                "base_url_env": "SHARED_DISCOVERY_BASE_URL",
                "api_key_env": "SHARED_DISCOVERY_API_KEY",
            }
        ]
    }
    calls = []

    def fail_urlopen(request, timeout=None):
        calls.append(request.full_url)
        raise AssertionError("dry-run discovery must not issue a network request")

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fail_urlopen)
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_CONFIGS", json.dumps(provider_configs))
    monkeypatch.setenv("SHARED_DISCOVERY_BASE_URL", "https://shared-discovery-secret.example/v1")
    monkeypatch.setenv("SHARED_DISCOVERY_API_KEY", "shared-discovery-secret")

    report = probe_exposed_provider_models(live=False)
    serialized = json.dumps(report, ensure_ascii=False)

    assert calls == []
    assert report["providers"] == ["shared-discovery-channel"]
    assert report["provider_seed_count"] == 1
    assert report["configured_static_model_count"] == 0
    assert report["candidate_model_count"] == 0
    assert report["provider_reports"][0]["status"] == "skipped"
    assert report["policy"]["model_discovery_attempted"] is False
    assert "shared-discovery-secret" not in serialized
    assert "https://shared-discovery-secret.example" not in serialized


def test_standalone_fusion_live_readiness_includes_shared_endpoint_discovery_provider(monkeypatch, tmp_path):
    _clear_fusion_provider_env_for_test(monkeypatch)
    manifest_dir = _write_fusion_live_readiness_manifest_set(tmp_path, ready=True)
    registry_path = _write_ready_live_registry_fixture(tmp_path)
    freeze_path, probe_evidence_path = _write_ready_provider_baseline_freeze_for_registry_fixture(
        tmp_path, registry_path
    )
    provider_configs = {
        "providers": [
            {
                "provider": "secret-shared-discovery-readiness-channel",
                "api_format": "responses",
                "base_url_env": "SECRET_SHARED_DISCOVERY_BASE_URL_ENV",
                "api_key_env": "SECRET_SHARED_DISCOVERY_API_KEY_ENV",
            }
        ]
    }
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_CONFIGS", json.dumps(provider_configs))
    monkeypatch.setenv("SECRET_SHARED_DISCOVERY_BASE_URL_ENV", "https://shared-readiness-secret.example/v1")
    monkeypatch.setenv("SECRET_SHARED_DISCOVERY_API_KEY_ENV", "shared-readiness-secret")

    readiness = build_fusion_live_readiness(
        registry_path=registry_path,
        benchmark_manifest_dir=manifest_dir,
        provider_baseline_freeze_path=freeze_path,
        provider_probe_evidence_audit_path=probe_evidence_path,
    )
    serialized = json.dumps(readiness, ensure_ascii=False)

    assert readiness["status"] == "ready"
    assert readiness["provider_env_readiness"]["custom_provider_seed_count"] == 1
    assert readiness["provider_env_readiness"]["custom_provider_profile_count"] == 0
    assert readiness["provider_env_readiness"]["credentialed_provider_count"] == 1
    # A credentialed discovery seed is an endpoint configuration, not a
    # routable model profile until /models discovery and admission publish it.
    assert readiness["provider_env_readiness"]["credentialed_configuration_channel_count"] == 1
    assert readiness["provider_env_readiness"]["credentialed_discovery_seed_count"] == 1
    assert readiness["provider_env_readiness"]["credentialed_provider_profile_count"] == 0
    assert readiness["provider_env_readiness"]["credentialed_api_format_counts"] == {}
    assert "secret-shared-discovery-readiness-channel" not in serialized
    assert "SECRET_SHARED_DISCOVERY_BASE_URL_ENV" not in serialized
    assert "https://shared-readiness-secret.example" not in serialized
    assert "shared-readiness-secret" not in serialized


def test_standalone_discovered_provider_models_inherit_config_priors_into_generated_registry(monkeypatch, tmp_path):
    provider_configs = {
        "providers": [
            {
                "provider": "custom-prior",
                "api_format": "responses",
                "base_url_env": "CUSTOM_PRIOR_BASE_URL",
                "api_key_env": "CUSTOM_PRIOR_API_KEY",
                "capabilities": {
                    "agentic_tool_calling": 0.72,
                    "critique": 0.83,
                    "structured_output": 0.84,
                    "multilingual": 0.78,
                },
                "input_cost_per_million": 0.11,
                "output_cost_per_million": 0.44,
                "context_tokens": 64000,
                "supports_tools": True,
                "supports_vision": True,
                "reasoning_transport": {
                    "status": "candidate",
                    "transport": "responses_reasoning",
                    "supported_efforts": ["low", "medium", "high"],
                },
                "privacy_tags": ["external_provider", "tenant-approved"],
            }
        ]
    }

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def fake_urlopen(request, timeout=None):
        if request.get_method() == "GET":
            return FakeResponse(
                {
                    "data": [
                        {"id": "custom-codex-tool", "object": "model"},
                        {"id": "custom-mini", "object": "model"},
                    ]
                }
            )
        return FakeResponse({"output_text": "AXIO_PROBE_OK"})

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_CONFIGS", json.dumps(provider_configs))
    monkeypatch.setenv("CUSTOM_PRIOR_BASE_URL", "https://custom-prior.example/v1")
    monkeypatch.setenv("CUSTOM_PRIOR_API_KEY", "custom-prior-secret")

    report = probe_exposed_provider_models(
        providers=["custom-prior"],
        live=True,
        max_workers=1,
    )
    probe_path = tmp_path / "custom_prior_probe.json"
    probe_path.write_text(json.dumps(report), encoding="utf-8")

    registry = build_registry_from_probe_artifacts(probe_paths=[probe_path])
    evidence = build_registry_from_probe_artifacts(
        probe_paths=[probe_path],
        redact_provider_identifiers=True,
    )
    by_model = {row["model"]: row for row in registry["models"]}
    codex = by_model["custom-codex-tool"]
    mini = by_model["custom-mini"]
    serialized_private = json.dumps({"report": report, "registry": registry}, ensure_ascii=False)
    serialized_evidence = json.dumps(evidence, ensure_ascii=False)

    assert report["policy"]["provider_config_priors_inherited"] is True
    assert report["policy"]["provider_prior_count"] == 1
    assert report["discovered_model_count"] == 2
    assert report["probe_report"]["available_count"] == 2
    assert all(row["base_url_env"] == "CUSTOM_PRIOR_BASE_URL" for row in report["probe_report"]["probes"])
    assert all(row["api_key_env"] == "CUSTOM_PRIOR_API_KEY" for row in report["probe_report"]["probes"])
    assert all(
        row["reasoning_transport"]["status"] == "candidate"
        and row["reasoning_transport"]["transport"] == "responses_reasoning"
        for row in report["probe_report"]["probes"]
    )
    assert registry["readiness"]["ready"] is True
    assert registry["readiness"]["api_format_counts"] == {"responses": 2}
    assert registry["readiness"]["judge_candidate_count"] == 2
    assert registry["readiness"]["structured_candidate_count"] == 2
    assert registry["readiness"]["tool_candidate_count"] == 2
    assert registry["readiness"]["pricing_known_count"] == 2
    assert registry["readiness"]["context_known_count"] == 2
    assert codex["provider"] == "custom-prior"
    assert codex["api_format"] == "responses"
    assert codex["base_url_env"] == "CUSTOM_PRIOR_BASE_URL"
    assert codex["api_key_env"] == "CUSTOM_PRIOR_API_KEY"
    assert codex["supports_tools"] is True
    assert codex["supports_vision"] is True
    assert codex["reasoning_transport"]["status"] == "candidate"
    assert codex["reasoning_transport"]["transport"] == "responses_reasoning"
    assert codex["context_tokens"] == 64000
    assert codex["input_cost_per_million"] == 0.11
    assert codex["output_cost_per_million"] == 0.44
    assert codex["capabilities"]["code"] >= 0.86
    assert codex["capabilities"]["agentic_tool_calling"] >= 0.72
    assert mini["capabilities"]["structured_output"] >= 0.84
    assert mini["reasoning_transport"]["status"] == "candidate"
    assert "custom-prior-secret" not in serialized_private
    assert "https://custom-prior.example" not in serialized_private
    assert "AXIO_PROBE_OK" not in serialized_private
    assert evidence["readiness"]["api_format_counts"] == {"responses": 2}
    assert evidence["readiness"]["provider_format_hash_counts"]
    assert evidence["model_receipts"][0]["pricing_known"] is True
    assert "custom-prior" not in serialized_evidence
    assert "custom-codex-tool" not in serialized_evidence
    assert "custom-mini" not in serialized_evidence
    assert "CUSTOM_PRIOR_API_KEY" not in serialized_evidence
    assert "CUSTOM_PRIOR_BASE_URL" not in serialized_evidence
    assert "custom-prior-secret" not in serialized_evidence
    assert "https://custom-prior.example" not in serialized_evidence


def test_standalone_live_discovery_inherits_per_model_provider_config_overrides(monkeypatch, tmp_path):
    provider_configs = {
        "providers": [
            {
                "provider": "mixed-live",
                "api_format": "responses",
                "base_url_env": "MIXED_LIVE_BASE_URL",
                "api_key_env": "MIXED_LIVE_API_KEY",
                "capabilities": {"structured_output": 0.7, "daily_work": 0.72},
                "models": [
                    {
                        "model": "per-model-chat",
                        "api_format": "chat/completions",
                        "capabilities": {"code": 0.93},
                        "input_cost_per_million": 0.02,
                        "output_cost_per_million": 0.08,
                    },
                    {
                        "model": "per-model-anthropic",
                        "apiFormat": "anthropic",
                        "baseUrlEnv": "MIXED_ANTHROPIC_BASE_URL",
                        "apiKeyEnv": "MIXED_ANTHROPIC_API_KEY",
                        "capabilities": {"critique": 0.96, "structured_output": 0.92},
                        "contextTokens": 200000,
                        "supportsTools": True,
                    },
                    {
                        "model": "per-model-gemini",
                        "apiFormat": "gemini",
                        "baseUrlEnv": "MIXED_GEMINI_BASE_URL",
                        "apiKeyEnv": "MIXED_GEMINI_API_KEY",
                        "capabilities": {"multilingual": 0.91, "long_context": 0.88},
                        "supportsVision": True,
                    },
                ],
            }
        ]
    }
    captured = []

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def fake_urlopen(request, timeout=None):
        payload = json.loads((request.data or b"{}").decode("utf-8")) if request.data else {}
        captured.append({"url": request.full_url, "method": request.get_method(), "payload": payload})
        if request.get_method() == "GET":
            return FakeResponse(
                {
                    "data": [
                        {"id": "per-model-chat"},
                        {"id": "per-model-anthropic"},
                        {"id": "per-model-gemini"},
                        {"id": "fallback-responses"},
                    ]
                }
            )
        if request.full_url.endswith("/chat/completions"):
            return FakeResponse({"choices": [{"message": {"content": "AXIO_PROBE_OK"}}]})
        if request.full_url.endswith("/messages"):
            return FakeResponse({"content": [{"type": "text", "text": "AXIO_PROBE_OK"}]})
        if request.full_url.endswith("/responses"):
            return FakeResponse({"output_text": "AXIO_PROBE_OK"})
        if ":streamGenerateContent" in request.full_url or ":generateContent" in request.full_url:
            return FakeResponse({"candidates": [{"content": {"parts": [{"text": "AXIO_PROBE_OK"}]}}]})
        raise AssertionError(f"unexpected url {request.full_url}")

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("AXIO_FUSION_PROVIDER_CONFIGS", json.dumps(provider_configs))
    monkeypatch.setenv("MIXED_LIVE_BASE_URL", "https://mixed-live.example/v1")
    monkeypatch.setenv("MIXED_LIVE_API_KEY", "mixed-live-secret")
    monkeypatch.setenv("MIXED_ANTHROPIC_BASE_URL", "https://mixed-anthropic-live.example/v1")
    monkeypatch.setenv("MIXED_ANTHROPIC_API_KEY", "mixed-anthropic-secret")
    monkeypatch.setenv("MIXED_GEMINI_BASE_URL", "https://mixed-gemini-live.example/v1")
    monkeypatch.setenv("MIXED_GEMINI_API_KEY", "mixed-gemini-secret")

    report = probe_exposed_provider_models(
        providers=["mixed-live"],
        live=True,
        max_workers=1,
    )
    probe_path = tmp_path / "mixed_live_probe.json"
    probe_path.write_text(json.dumps(report), encoding="utf-8")
    registry = build_registry_from_probe_artifacts(probe_paths=[probe_path])
    evidence = build_registry_from_probe_artifacts(
        probe_paths=[probe_path],
        redact_provider_identifiers=True,
    )
    by_model = {row["model"]: row for row in registry["models"]}
    serialized_private = json.dumps({"report": report, "registry": registry}, ensure_ascii=False)
    serialized_evidence = json.dumps(evidence, ensure_ascii=False)

    assert report["policy"]["provider_prior_count"] == 1
    assert report["policy"]["provider_model_prior_count"] == 3
    assert report["policy"]["discovered_model_prior_match_count"] == 3
    assert report["probe_report"]["available_count"] == 4
    assert any(row["url"].endswith("/chat/completions") for row in captured if row["method"] == "POST")
    assert any(row["url"].endswith("/messages") for row in captured if row["method"] == "POST")
    assert any(row["url"].endswith("/responses") for row in captured if row["method"] == "POST")
    assert any(":streamGenerateContent" in row["url"] for row in captured if row["method"] == "POST")
    assert registry["readiness"]["api_format_counts"] == {"anthropic": 1, "chat": 1, "gemini": 1, "responses": 1}
    assert by_model["per-model-chat"]["api_format"] == "chat"
    assert by_model["per-model-chat"]["input_cost_per_million"] == 0.02
    assert by_model["per-model-chat"]["capabilities"]["code"] >= 0.93
    assert by_model["per-model-anthropic"]["api_format"] == "anthropic"
    assert by_model["per-model-anthropic"]["base_url_env"] == "MIXED_ANTHROPIC_BASE_URL"
    assert by_model["per-model-anthropic"]["api_key_env"] == "MIXED_ANTHROPIC_API_KEY"
    assert by_model["per-model-anthropic"]["context_tokens"] == 200000
    assert by_model["per-model-anthropic"]["supports_tools"] is True
    assert by_model["per-model-gemini"]["api_format"] == "gemini"
    assert by_model["per-model-gemini"]["base_url_env"] == "MIXED_GEMINI_BASE_URL"
    assert by_model["per-model-gemini"]["api_key_env"] == "MIXED_GEMINI_API_KEY"
    assert by_model["per-model-gemini"]["supports_vision"] is True
    assert by_model["per-model-gemini"]["capabilities"]["multilingual"] >= 0.91
    assert by_model["fallback-responses"]["api_format"] == "responses"
    assert by_model["fallback-responses"]["capabilities"]["structured_output"] >= 0.7
    assert evidence["readiness"]["api_format_counts"] == {"anthropic": 1, "chat": 1, "gemini": 1, "responses": 1}
    assert "mixed-live-secret" not in serialized_private
    assert "mixed-anthropic-secret" not in serialized_private
    assert "mixed-gemini-secret" not in serialized_private
    assert "https://mixed-live.example" not in serialized_private
    assert "https://mixed-anthropic-live.example" not in serialized_private
