def test_standalone_live_fusion_can_mix_chat_responses_and_anthropic_provider_models(monkeypatch):
    captured = []

    class FakeResponse:
        status = 200

        def __init__(self, payload):
            self.payload = payload

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    def prompt_from_payload(payload):
        if "messages" in payload:
            messages = payload.get("messages") or []
            return str(messages[-1].get("content") or "") if messages else ""
        if "input" in payload:
            value = payload["input"]
            if isinstance(value, str):
                return value
            if isinstance(value, list) and value:
                content = value[-1].get("content") if isinstance(value[-1], dict) else []
                if isinstance(content, list) and content:
                    return str(content[-1].get("text") or "")
        return ""

    def fake_urlopen(request, timeout=None):
        payload = json.loads((request.data or b"{}").decode("utf-8"))
        prompt = prompt_from_payload(payload)
        captured.append({"url": request.full_url, "payload": payload})

        def endpoint_response(text):
            if request.full_url.endswith("/chat/completions"):
                return FakeResponse({"choices": [{"message": {"content": text}}]})
            if request.full_url.endswith("/responses"):
                return FakeResponse({"output_text": text})
            if request.full_url.endswith("/messages"):
                return FakeResponse({"content": [{"type": "text", "text": text}]})
            raise AssertionError(f"unexpected url {request.full_url}")

        if "Compare these Axio Fusion candidate answers" in prompt:
            return endpoint_response(
                json.dumps(
                    {
                        "consensus": [
                            {
                                "claim": "mixed provider panel is ready for synthesis",
                                "supporting_candidates": ["primary_solver", "independent_solver", "critic"],
                                "evidence_strength": 0.91,
                            }
                        ],
                        "contradictions": [],
                        "missing_coverage": [],
                        "collective_blind_spots": [],
                        "ranked_candidates": [
                            {"candidate_id": "critic", "score": 0.93},
                            {"candidate_id": "primary_solver", "score": 0.9},
                            {"candidate_id": "independent_solver", "score": 0.88},
                        ],
                        "follow_up_tasks": [],
                        "ready_for_synthesis": True,
                    }
                )
            )
        if "Synthesize one final answer" in prompt:
            return endpoint_response("mixed protocol final answer")
        if request.full_url.endswith("/chat/completions"):
            answer = "chat provider candidate emphasizes rollback windows"
        elif request.full_url.endswith("/responses"):
            answer = "responses provider candidate emphasizes approval gates"
        else:
            answer = "anthropic provider candidate emphasizes audit evidence"
        candidate = {
            "answer": answer,
            "evidence": [{"claim": "unit", "source": "fixture", "reliability": 0.87}],
            "assumptions": [],
            "uncertainties": [],
            "confidence": 0.87,
        }
        return endpoint_response(json.dumps(candidate))

    monkeypatch.setattr(provider_module.urllib.request, "urlopen", fake_urlopen)
    monkeypatch.setenv("MIXED_CHAT_BASE_URL", "https://mixed-chat.example/v1")
    monkeypatch.setenv("MIXED_CHAT_API_KEY", "mixed-chat-secret")
    monkeypatch.setenv("MIXED_RESPONSES_BASE_URL", "https://mixed-responses.example/v1")
    monkeypatch.setenv("MIXED_RESPONSES_API_KEY", "mixed-responses-secret")
    monkeypatch.setenv("MIXED_ANTHROPIC_BASE_URL", "https://mixed-anthropic.example/v1")
    monkeypatch.setenv("MIXED_ANTHROPIC_API_KEY", "mixed-anthropic-secret")
    profiles = [
        normalize_profile(
            {
                "provider": "mixed-chat",
                "model": "chat-solver",
                "api_format": "chat",
                "base_url_env": "MIXED_CHAT_BASE_URL",
                "api_key_env": "MIXED_CHAT_API_KEY",
                "capabilities": {"daily_work": 0.9, "logic": 0.88, "structured_output": 0.84, "critique": 0.72},
            }
        ),
        normalize_profile(
            {
                "provider": "mixed-responses",
                "model": "responses-solver",
                "api_format": "responses",
                "base_url_env": "MIXED_RESPONSES_BASE_URL",
                "api_key_env": "MIXED_RESPONSES_API_KEY",
                "capabilities": {"daily_work": 0.88, "logic": 0.86, "structured_output": 0.86, "critique": 0.74},
            }
        ),
        normalize_profile(
            {
                "provider": "mixed-anthropic",
                "model": "anthropic-judge",
                "api_format": "anthropic",
                "base_url_env": "MIXED_ANTHROPIC_BASE_URL",
                "api_key_env": "MIXED_ANTHROPIC_API_KEY",
                "capabilities": {"daily_work": 0.82, "logic": 0.8, "structured_output": 0.96, "critique": 0.98},
            }
        ),
    ]
    request = canonicalize_payload(
        {
            "model": "axio-pro",
            "quality_target": 0.92,
            "max_total_model_calls": 6,
            "messages": [{"role": "user", "content": "Review mixed provider routing."}],
        }
    )

    response = FusionEngine(profiles).complete(request, live=True)
    serialized = json.dumps({"trace": response.trace, "route_plan": response.route_plan}, ensure_ascii=False)

    assert response.text == "mixed protocol final answer"
    assert response.provider_calls_recorded is True
    assert response.trace["provider_call_count"] == 5
    assert response.judge_result["judge_provider_call"] is True
    assert {row["provider"] for row in response.route_plan["selected_models"]} == {"mixed-chat", "mixed-responses", "mixed-anthropic"}
    assert any(row["url"].endswith("/chat/completions") for row in captured)
    assert any(row["url"].endswith("/responses") for row in captured)
    assert any(row["url"].endswith("/messages") for row in captured)
    assert "mixed-chat-secret" not in serialized
    assert "mixed-responses-secret" not in serialized
    assert "mixed-anthropic-secret" not in serialized
    assert "https://mixed-chat.example" not in serialized
    assert "https://mixed-responses.example" not in serialized
    assert "https://mixed-anthropic.example" not in serialized


