def test_standalone_benchmark_matrix_and_dry_run_do_not_persist_raw_cases(tmp_path):
    secret = "SECRET_BENCHMARK_PROMPT_SHOULD_NOT_PERSIST"
    registry_path = _benchmark_registry_path(tmp_path)
    dataset_path = tmp_path / "fixture.jsonl"
    dataset_path.write_text(
        "\n".join(
            [
                json.dumps(
                    {
                        "question": f"What is 2 + 2? {secret}",
                        "options": {"A": "three", "B": "four", "C": "five"},
                        "answer": "B",
                        "category": "unit_math",
                    }
                ),
                json.dumps(
                    {
                        "question": "Which color is a clear daytime sky?",
                        "options": ["red", "blue", "green"],
                        "answer": "B",
                        "category": "unit_daily",
                    }
                ),
            ]
        ),
        encoding="utf-8",
    )

    matrix = build_benchmark_run_matrix(
        registry_path=registry_path,
        suite_ids=["arc_challenge"],
        include_provider_baselines=True,
        max_provider_baselines=1,
    )
    run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="axio-pro",
        registry_path=registry_path,
        limit=1,
        live=False,
    )
    matrix_path = tmp_path / "matrix.json"
    run_path = tmp_path / "run.json"

    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-matrix",
            "--suite-id",
            "arc_challenge",
            "--max-provider-baselines",
            "1",
            "--output",
            str(matrix_path),
        ]
    ) == 0
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-run",
            "--suite-id",
            "arc_challenge",
            "--dataset",
            str(dataset_path),
            "--candidate-id",
            "axio-pro",
            "--limit",
            "1",
            "--output",
            str(run_path),
        ]
    ) == 0

    serialized = json.dumps({"matrix": matrix, "run": run, "cli_run": json.loads(run_path.read_text(encoding="utf-8"))}, ensure_ascii=False)

    assert matrix["suite_count"] == 1
    assert matrix["run_count"] == matrix["run_unit_count"]
    assert matrix["axio_api_surface_run_unit_count"] == 12
    assert matrix["api_surface_contract"]["only_primary_surface_participates_in_superiority_claim"] is True
    assert any(candidate["candidate_id"].startswith("provider::") for candidate in matrix["candidates"])
    assert run["mode"] == "dry_run"
    assert run["case_results"][0]["status"] == "dry_run"
    assert run["anti_leakage_contract"]["raw_questions_persisted"] is False
    assert matrix_path.exists()
    assert secret not in serialized
    assert "What is 2 + 2" not in serialized
    assert "four" not in serialized
    assert "raw_model_output_persisted\": true" not in serialized


def test_standalone_benchmark_matrix_can_include_all_provider_baselines(tmp_path):
    registry_path = _benchmark_registry_path(tmp_path)
    output_path = tmp_path / "all_provider_matrix.json"

    matrix = build_benchmark_run_matrix(
        registry_path=registry_path,
        suite_ids=["arc_challenge"],
        include_provider_baselines=True,
        max_provider_baselines=None,
    )
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-matrix",
            "--suite-id",
            "arc_challenge",
            "--all-provider-baselines",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_matrix = json.loads(output_path.read_text(encoding="utf-8"))
    provider_candidates = [row for row in matrix["candidates"] if row["candidate_type"] == "provider"]
    cli_provider_candidates = [row for row in cli_matrix["candidates"] if row["candidate_type"] == "provider"]

    assert matrix["provider_baseline_selection"] == "all_available_provider_models"
    assert cli_matrix["provider_baseline_selection"] == "all_available_provider_models"
    assert len(provider_candidates) == matrix["available_provider_baseline_count"]
    assert len(cli_provider_candidates) == cli_matrix["available_provider_baseline_count"]
    assert all(row["candidate_id"].startswith("provider::") for row in provider_candidates)
    assert all(len(row["candidate_id"][len("provider::") :]) == 64 for row in provider_candidates)
    assert all("profile_id" not in row for row in provider_candidates)
    assert all("model" not in row for row in provider_candidates)
    assert all("provider_profile_hash" in row for row in provider_candidates)
    assert matrix["provider_baseline_census"]["selected_all_available_provider_baselines"] is True
    assert matrix["provider_baseline_census"]["selected_provider_baseline_count"] == len(provider_candidates)
    assert cli_matrix["provider_baseline_census"]["selected_provider_candidate_id_set_sha256"]
    assert matrix["comparison_contract"]["final_claims_require_externally_ranked_top_three_pre_registration"] is True
    assert matrix["comparison_contract"]["legacy_all_provider_baselines_are_diagnostic_only"] is True


