def test_standalone_canonical_identity_is_required_only_for_final_claim_freeze(tmp_path):
    registry_path = _write_live_runbook_registry_fixture(tmp_path)
    registry = json.loads(registry_path.read_text(encoding="utf-8"))
    registry["models"][0].pop("canonical_model_id")
    registry_path.write_text(json.dumps(registry), encoding="utf-8")

    template = build_external_provider_ranking_template(registry_path=registry_path)
    probe_evidence_path = _write_probe_evidence_audit_for_registry_fixture(
        tmp_path, registry_path
    )
    external_ranking_path = _write_external_ranking_manifest_for_registry_fixture(
        tmp_path, registry_path
    )
    freeze = build_provider_baseline_freeze_manifest(
        registry_path=registry_path,
        provider_probe_evidence_audit_path=probe_evidence_path,
        external_ranking_manifest_path=external_ranking_path,
    )

    assert template["ready_for_operator_ranking"] is False
    assert "canonical_model_identity_declaration_missing" in template["blockers"]
    assert freeze["final_claim_freeze_ready"] is False
    assert "external_provider_ranking_canonical_model_identity_missing" in freeze["blockers"]

    # Serving remains available for a provider whose channel alias is not yet
