def test_standalone_provider_baseline_freeze_rejects_identity_binding_drift(tmp_path):
    registry_path = _write_live_runbook_registry_fixture(tmp_path)
    probe_evidence_path = _write_probe_evidence_audit_for_registry_fixture(
        tmp_path, registry_path
    )
    external_ranking_path = _write_external_ranking_manifest_for_registry_fixture(
        tmp_path, registry_path
    )
    ranking = json.loads(external_ranking_path.read_text(encoding="utf-8"))
    ranking["candidate_inventory"][0]["canonical_model_id_sha256"] = sha256_text(
        "fixture-canonical-drift"
    )
    ranking["candidate_inventory"][1]["identity_attestation"][
        "model_alias_sha256"
    ] = sha256_text("fixture-wrong-channel-alias")
    external_ranking_path.write_text(json.dumps(ranking), encoding="utf-8")

    freeze = build_provider_baseline_freeze_manifest(
        registry_path=registry_path,
        provider_probe_evidence_audit_path=probe_evidence_path,
        external_ranking_manifest_path=external_ranking_path,
    )
    serialized = json.dumps(freeze, ensure_ascii=False)

    assert freeze["final_claim_freeze_ready"] is False
    assert "external_provider_ranking_canonical_model_identity_hash_mismatch" in freeze["blockers"]
    assert "external_provider_ranking_identity_attestation_model_alias_mismatch" in freeze["blockers"]
    assert "fixture-canonical-drift" not in serialized
    assert "fixture-wrong-channel-alias" not in serialized


