def test_standalone_routing_policy_lifecycle_applies_only_bounded_context_and_route_controls(
    tmp_path,
):
    profiles = [
        normalize_profile(
            {
                "provider": "secret-policy-provider-alpha",
                "model": "secret-policy-model-alpha",
                "api_format": "chat",
                "p50_latency_ms": 700,
                "capabilities": {
                    "logic": 0.9,
                    "agentic_tool_calling": 0.9,
                    "structured_output": 0.9,
                    "critique": 0.84,
                },
            }
        ),
        normalize_profile(
            {
                "provider": "secret-policy-provider-beta",
                "model": "secret-policy-model-beta",
                "api_format": "responses",
                "p50_latency_ms": 800,
                "capabilities": {
                    "logic": 0.88,
                    "agentic_tool_calling": 0.86,
                    "structured_output": 0.92,
                    "critique": 0.9,
                },
            }
        ),
    ]
    shadow_patch = {
        "schema": "axio_fusion_api.router_policy_shadow_patch.v1",
        "shadow_only": True,
        "safe_to_apply_automatically": False,
        "application_contract": {
            "production_policy_changed": False,
            "not_for_final_benchmark_claims": True,
        },
        "patch_candidate_count": 1,
        "patch_candidates": [
            {
                "patch_id": "policy-shadow-agentic",
                "target": {
                    "public_model": "axio-fast",
                    "strategy": "fast_direct_cascade",
                    "task_type": "all",
                },
                "action": "increase_agentic_verification_and_escalation",
                "evidence": {
                    "example_count": 8,
                    "accepted_rate": 0.42,
                    "average_score": -0.2,
                    "trace_joined_count": 8,
                },
                "suggested_policy_delta": {
                    "quality_target_delta": 0.12,
                    "targeted_escalation_enabled": True,
                    "fast_light_verify": True,
                },
            }
        ],
    }
    contamination_audit = {
        "schema": "axio_fusion_api.training_contamination_audit.v1",
        "final_claim_training_clean": True,
        "blocker_count": 0,
        "warning_count": 0,
        "benchmark_labels_used_for_training": False,
        "benchmark_scores_used_for_router_learning": False,
    }

    candidate = build_routing_policy_candidate(
        shadow_patch,
        profiles=profiles,
        min_examples=8,
        created_on="2026-07-18",
    )
    review = review_routing_policy_candidate(
        candidate,
        profiles=profiles,
        contamination_audit=contamination_audit,
        approved=True,
        reviewer_id="secret-policy-reviewer",
        reviewed_on="2026-07-18",
    )
    bundle = activate_routing_policy(
        candidate,
        review,
        profiles=profiles,
        activated_on="2026-07-18",
    )
    policy_path = tmp_path / "SECRET_POLICY_BUNDLE.json"
    write_routing_policy_json(policy_path, bundle)
    active_policy = load_active_routing_policy(profiles, path=policy_path)
    engine = FusionEngine(profiles, routing_policy=active_policy)
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [
                {
                    "role": "user",
                    "content": "Create an agent tool plan and verify assumptions.",
                }
            ],
            "max_total_model_calls": 6,
        },
        api_format="chat/completions",
    )
    route_plan = engine.complete(request, live=False).route_plan
    context = orchestrator_module._routing_context_for_prompt(
        route_plan, "primary_solver"
    )
    serialized = json.dumps(
        {
            "candidate": candidate,
            "review": review,
            "bundle": bundle,
            "routing_policy": route_plan["routing_policy"],
            "context": context,
        },
        ensure_ascii=False,
    )

    assert candidate["ready_for_review"] is True
    assert review["ready_for_activation"] is True
    assert bundle["activation_ready"] is True
    assert active_policy["active"] is True
    assert route_plan["routing_policy"]["applied"] is True
    assert route_plan["budget"]["fast_light_verify_requested"] is True
    assert "active_routing_policy_requires_fusion" in route_plan["fusion_admission"][
        "force_reasons"
    ]
    assert context["context_playbook"]["active"] is True
    assert "tool_schema_strict" in {
        row["id"] for row in context["context_playbook"]["directives"]
    }
    assert "secret-policy-provider-alpha" not in serialized
    assert "secret-policy-model-alpha" not in serialized
    assert "secret-policy-reviewer" not in serialized
    assert "Create an agent tool plan" not in serialized
    assert str(policy_path) not in serialized


def test_standalone_routing_policy_fails_closed_on_registry_drift_and_keeps_caller_cap(
    tmp_path,
):
    profiles = [
        normalize_profile(
            {
                "provider": "policy-alpha",
                "model": "policy-alpha-model",
                "api_format": "chat",
                "capabilities": {"logic": 0.9, "structured_output": 0.9},
            }
        ),
        normalize_profile(
            {
                "provider": "policy-beta",
                "model": "policy-beta-model",
                "api_format": "responses",
                "capabilities": {"logic": 0.88, "structured_output": 0.92},
            }
        ),
    ]
    shadow_patch = {
        "schema": "axio_fusion_api.router_policy_shadow_patch.v1",
        "shadow_only": True,
        "safe_to_apply_automatically": False,
        "application_contract": {
            "production_policy_changed": False,
            "not_for_final_benchmark_claims": True,
        },
        "patch_candidates": [
            {
                "patch_id": "policy-shadow-fast",
                "target": {"public_model": "axio-fast", "task_type": "all"},
                "action": "fast_claim_verification",
                "evidence": {"example_count": 4, "trace_joined_count": 4},
                "suggested_policy_delta": {"fast_light_verify": True},
            }
        ],
    }
    audit = {
        "schema": "axio_fusion_api.training_contamination_audit.v1",
        "final_claim_training_clean": True,
        "blocker_count": 0,
    }
    candidate = build_routing_policy_candidate(
        shadow_patch, profiles=profiles, min_examples=4, created_on="2026-07-18"
    )
    review = review_routing_policy_candidate(
        candidate,
        profiles=profiles,
        contamination_audit=audit,
        approved=True,
        reviewed_on="2026-07-18",
    )
    bundle = activate_routing_policy(
        candidate, review, profiles=profiles, activated_on="2026-07-18"
    )
    policy_path = tmp_path / "policy.json"
    write_routing_policy_json(policy_path, bundle)

    drifted_profiles = [
        normalize_profile(
            {
                "provider": "policy-alpha",
                "model": "policy-alpha-model-replaced",
                "api_format": "chat",
            }
        )
    ]
    drifted = load_active_routing_policy(drifted_profiles, path=policy_path)
    active = load_active_routing_policy(profiles, path=policy_path)
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [{"role": "user", "content": "verify this claim"}],
            "max_total_model_calls": 1,
        },
        api_format="chat/completions",
    )
    route_plan = FusionEngine(profiles, routing_policy=active).complete(
        request, live=False
    ).route_plan

    assert drifted["active"] is False
    assert "routing_policy_bundle_registry_binding_mismatch" in drifted["reason_codes"]
    assert route_plan["routing_policy"]["applied"] is True
    assert route_plan["budget"]["max_total_model_calls"] == 1
    assert route_plan["fusion_admission"]["activated"] is False


