def test_standalone_routing_policy_versioned_trace_learning_and_shadow_replay_are_safe(
    tmp_path,
):
    secret_provider = "secret-versioned-provider"
    secret_model = "secret-versioned-model"
    secret_prompt = "SECRET_VERSIONED_POLICY_PROMPT_MUST_NOT_PERSIST"
    profiles = [
        normalize_profile(
            {
                "provider": secret_provider,
                "model": secret_model,
                "api_format": "responses",
                "p50_latency_ms": 600,
                "capabilities": {
                    "logic": 0.92,
                    "agentic_tool_calling": 0.91,
                    "structured_output": 0.92,
                    "critique": 0.9,
                },
            }
        )
    ]
    shadow_patch = {
        "schema": "axio_fusion_api.router_policy_shadow_patch.v1",
        "shadow_only": True,
        "safe_to_apply_automatically": False,
        "application_contract": {
            "production_policy_changed": False,
            "not_for_final_benchmark_claims": True,
        },
        "patch_candidates": [
            {
                "patch_id": "versioned-shadow-agentic",
                "target": {"public_model": "axio-fast", "task_type": "all"},
                "action": "increase_agentic_verification_and_escalation",
                "evidence": {"example_count": 4, "trace_joined_count": 4},
                "suggested_policy_delta": {
                    "quality_target_delta": 0.12,
                    "targeted_escalation_enabled": True,
                    "fast_light_verify": True,
                },
            }
        ],
    }
    candidate = build_routing_policy_candidate(
        shadow_patch,
        profiles=profiles,
        min_examples=4,
        created_on="2026-07-18",
    )
    review = review_routing_policy_candidate(
        candidate,
        profiles=profiles,
        contamination_audit={
            "schema": "axio_fusion_api.training_contamination_audit.v1",
            "final_claim_training_clean": True,
            "blocker_count": 0,
        },
        approved=True,
        reviewed_on="2026-07-18",
    )
    bundle = activate_routing_policy(
        candidate,
        review,
        profiles=profiles,
        activated_on="2026-07-18",
    )
    policy_path = tmp_path / "policy.json"
    candidate_path = tmp_path / "candidate.json"
    write_routing_policy_json(policy_path, bundle)
    write_routing_policy_json(candidate_path, candidate)
    active_policy = load_active_routing_policy(profiles, path=policy_path)
    request = canonicalize_payload(
        {
            "model": "axio-fast",
            "messages": [{"role": "user", "content": secret_prompt}],
            "max_total_model_calls": 6,
        },
        api_format="chat/completions",
    )

    active_response = FusionEngine(profiles, routing_policy=active_policy).complete(
        request,
        live=False,
    )
    active_trace = safe_execution_trace(active_response)
    historical_response = FusionEngine(profiles).complete(request, live=False)
    historical_trace = safe_execution_trace(historical_response)
    trace_path = tmp_path / "traces.jsonl"
    trace_path.write_text(
        "\n".join(
            [
                json.dumps(active_trace, ensure_ascii=False),
                json.dumps(historical_trace, ensure_ascii=False),
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    feedback_path = tmp_path / "feedback.jsonl"
    feedback_path.write_text(
        "\n".join(
            [
                json.dumps(
                    {
                        "schema": "axio_fusion_api.feedback_receipt.v1",
                        "response_id": active_response.response_id,
                        "request_fingerprint": active_response.request.request_fingerprint,
                        "score": 0.8,
                        "accepted": True,
                        "route_snapshot": {
                            "public_model": "axio-fast",
                            "strategy": active_trace["routing_decision"]["strategy"],
                            "task_type": active_trace["request_analysis"]["task_type"],
                            "routing_policy": active_trace["routing_policy"],
                        },
                        "training_signal": {"eligible_for_router_learning": True},
                    },
                    ensure_ascii=False,
                ),
                json.dumps(
                    {
                        "schema": "axio_fusion_api.feedback_receipt.v1",
                        "response_id": historical_response.response_id,
                        "request_fingerprint": historical_response.request.request_fingerprint,
                        "score": -0.5,
                        "accepted": False,
                        "route_snapshot": {
                            "public_model": "axio-fast",
                            "strategy": historical_trace["routing_decision"]["strategy"],
                            "task_type": historical_trace["request_analysis"]["task_type"],
                            "routing_policy": historical_trace["routing_policy"],
                        },
                        "training_signal": {"eligible_for_router_learning": True},
                    },
                    ensure_ascii=False,
                ),
            ]
        )
        + "\n",
        encoding="utf-8",
    )

    learning = build_learning_signal_report(feedback_paths=[feedback_path])
    trace_report = build_trace_report([trace_path])
    replay = build_routing_policy_shadow_replay(
        candidate,
        trace_paths=[trace_path],
        feedback_paths=[feedback_path],
    )
    replay_path = tmp_path / "replay.json"

    assert fusion_cli_main(
        [
            "routing-policy-shadow-replay",
            "--candidate",
            str(candidate_path),
            "--trace-file",
            str(trace_path),
            "--feedback-file",
            str(feedback_path),
            "--output",
            str(replay_path),
        ]
    ) == 0

    serialized = json.dumps(
        {
            "active_trace": active_trace,
            "historical_trace": historical_trace,
            "learning": learning,
            "trace_report": trace_report,
            "replay": replay,
            "cli_replay": json.loads(replay_path.read_text(encoding="utf-8")),
        },
        ensure_ascii=False,
    )
    assert active_trace["routing_policy"]["applied"] is True
    assert (
        active_trace["routing_policy"]["policy_version_sha256"]
        == bundle["bundle_digest_sha256"]
    )
    assert learning["routing_policy_summary"]["policy_version_count"] == 1
    assert learning["routing_policy_summary"]["applied_count"] == 1
    assert trace_report["routing_policy_summary"]["policy_version_count"] == 1
    assert replay["status"] == "decision_replay_ready"
    assert replay["decision_summary"]["replayed_case_count"] == 2
    assert replay["decision_summary"]["candidate_policy_applied_count"] == 2
    assert replay["decision_summary"]["candidate_force_fusion_newly_requested_count"] == 1
    assert replay["quality_evidence"]["quality_comparison_available"] is False
    assert replay["quality_evidence"]["paired_case_count"] == 0
    assert replay["promotion_gate"]["eligible"] is False
    assert replay["application_contract"]["provider_calls_performed"] is False
    assert secret_provider not in serialized
    assert secret_model not in serialized
    assert secret_prompt not in serialized
    assert str(candidate_path) not in serialized
    assert str(trace_path) not in serialized
    assert str(feedback_path) not in serialized


