def test_standalone_provider_baseline_freeze_uses_normalized_common_source_rank(tmp_path):
    registry_path = _write_live_runbook_registry_fixture(tmp_path)
    probe_evidence_path = _write_probe_evidence_audit_for_registry_fixture(tmp_path, registry_path)
    external_ranking_path = _write_external_ranking_manifest_for_registry_fixture(tmp_path, registry_path)
    ranking = json.loads(external_ranking_path.read_text(encoding="utf-8"))
    inventory = ranking["candidate_inventory"]

    # The two common sources have different board sizes, but each source uses
    # one fixed population across the complete provider pool. The first
    # candidate wins the raw-rank mean while losing the normalized consensus.
    source_ranks = ((4, 1, 2, 3), (1, 5, 6, 7))
    source_populations = (4, 100)
    derived_inventory_indices = (1, 2, 3, 0)
    for index in range(len(inventory)):
        inventory[index]["screening_rank"] = derived_inventory_indices.index(index) + 1
        for source_index, evidence in enumerate(inventory[index]["screening_evidence"]):
            evidence["reported_rank"] = source_ranks[source_index][index]
            evidence["ranking_population_count"] = source_populations[source_index]
    for rank, inventory_index in enumerate(derived_inventory_indices[:3], start=1):
        ranking["rankings"][rank - 1]["profile_id_sha256"] = inventory[inventory_index][
            "profile_id_sha256"
        ]
        ranking["rankings"][rank - 1]["canonical_model_id_sha256"] = inventory[
            inventory_index
        ]["canonical_model_id_sha256"]
    external_ranking_path.write_text(json.dumps(ranking), encoding="utf-8")

    freeze = build_provider_baseline_freeze_manifest(
        registry_path=registry_path,
        provider_probe_evidence_audit_path=probe_evidence_path,
        external_ranking_manifest_path=external_ranking_path,
    )
    receipt = freeze["external_ranking_receipt"]

    assert freeze["final_claim_freeze_ready"] is True
    assert receipt["derived_pool_rank_rows"][0]["profile_id_sha256"] == inventory[1][
        "profile_id_sha256"
    ]
    assert receipt["candidate_screening"][0]["reported_rank_mean"] == 2.5
    assert receipt["candidate_screening"][0]["mean_normalized_rank_percentile"] == 0.5
    assert receipt["candidate_screening"][1]["reported_rank_mean"] == 4.5
    assert receipt["candidate_screening"][1]["mean_normalized_rank_percentile"] < 0.05


