    assert first["status"] == "live_complete"
    assert first["imported_task_count"] == 1
    assert first["task_receipts"][0]["preflight_status"] == "ready"
    assert second["status"] == "live_complete"
    assert second["task_receipts"][0]["resume_action"] == "existing_import_reused"
    assert calls == {"preflight": 1, "generate": 1, "evaluate": 1, "import": 1}
    assert persisted["campaign_state_digest_sha256"] == second["campaign_state_digest_sha256"]
    assert "SECRET_CAMPAIGN_DATASET" not in serialized
    assert "SECRET_CAMPAIGN_HARNESS" not in serialized
    assert "SECRET_CAMPAIGN_PRIVATE_ROOT" not in serialized
    assert "SECRET_CAMPAIGN_GATEWAY" not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


