def test_standalone_official_harness_bridge_pairs_frozen_provider_alias_with_same_cases(monkeypatch, tmp_path):
    class FakeProviderClient:
        def __init__(self):
            self.calls = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append(
                {
                    "profile_id": profile.profile_id,
                    "temperature": request.temperature,
                    "max_output_tokens": request.max_output_tokens,
                    "prompt": prompt,
                    "system": system,
                    "timeout": timeout,
                }
            )
            return "private provider response"

    reset_runtime_state_for_tests()
    harness_root = tmp_path / "SECRET_PROVIDER_IFEVAL_HARNESS"
