    assert evaluation["status"] == "evaluated"
    assert evaluation["candidate_id"] == provider_alias
    assert evaluation["candidate_kind"] == "provider_native"
    assert evaluation["generation_binding_digest_sha256"] == binding["generation_binding_digest_sha256"]
    assert evaluation["official_import_binding"]["candidate_id_sha256"] == sha256_text(provider_alias)
    assert evaluation["official_import_binding"]["case_set_matches_preflight"] is True
    assert evaluation["official_import_binding"]["prompt_protocol_sha256"] == sha256_text("provider-ifeval:prompt_protocol_sha256")
    assert evaluation["official_import_binding"]["decoding_config_sha256"] == sha256_text("provider-ifeval:decoding_config_sha256")

    imported = import_official_harness_evaluation(private_run_dir=private_run_dir)
