    assert imported.get("status") != "blocked", imported.get("reason_codes")
    assert imported["mode"] == "official_harness_import"
    assert imported["candidate_id"] == provider_alias
    assert imported["api_format"] == "provider_native"
    assert imported["official_harness_bridge"]["candidate_kind"] == "provider_native"
    assert imported["official_harness_bridge"]["provider_baseline_candidate_frozen"] is True
    assert imported["official_harness_bridge"]["provider_baseline_freeze_manifest_digest_sha256"] == freeze_payload["freeze_digest_sha256"]
    assert secret_prompt not in imported_serialized
    assert secret_provider not in imported_serialized
    assert secret_model not in imported_serialized


