def test_standalone_official_harness_execution_plan_from_pinned_import_template_is_safe(tmp_path):
    registry_path = tmp_path / "registry_secret_provider_models.json"
    secret_dataset_dir = tmp_path / "SECRET_EXECUTION_PLAN_DATASET_DIR"
    secret_import_dir = tmp_path / "SECRET_EXECUTION_PLAN_IMPORT_DIR"
    models = []
    for provider in ("cpa-plus", "aisz"):
        for index in range(9):
            models.append(
                {
                    "provider": provider,
                    "model": f"SECRET_{provider.upper()}_MODEL_{index}",
                    "api_format": "responses",
                    "capabilities": {
                        "logic": 0.72 + index / 100,
                        "math": 0.70 + index / 100,
                        "science_knowledge": 0.71 + index / 100,
                        "code": 0.68 + index / 100,
                        "structured_output": 0.75 + index / 100,
                    },
                }
            )
    registry_path.write_text(json.dumps({"models": models}), encoding="utf-8")
    checklist = build_benchmark_acquisition_checklist(
        registry_path=registry_path,
        base_dir=str(secret_dataset_dir),
        import_dir=str(secret_import_dir),
        include_provider_baselines=True,
        max_provider_baselines=None,
        min_cases_per_suite=100,
    )
    checklist_path = tmp_path / "SECRET_EXECUTION_PLAN_CHECKLIST.json"
    checklist_path.write_text(json.dumps(checklist), encoding="utf-8")
    harness_pin_path = tmp_path / "SECRET_EXECUTION_PLAN_HARNESS_PINS.json"
    harness_pin_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.benchmark_harness_pin_manifest.v1",
                "suites": [
                    {
                        "suite_id": suite["suite_id"],
                        "task_format": suite["task_format"],
                        "ready": True,
                        "harness_name": f"{suite['suite_id']} official",
                        "harness_name_sha256": sha256_text(f"{suite['suite_id']} official"),
                        "harness_version": f"commit:{suite['suite_id']}",
                        "harness_version_sha256": sha256_text(f"commit:{suite['suite_id']}"),
                        "dataset_snapshot_sha256": sha256_text(f"{suite['suite_id']}:dataset"),
                        "evaluator_config_sha256": sha256_text(f"{suite['suite_id']}:evaluator"),
                        "prompt_protocol_sha256": sha256_text(f"{suite['suite_id']}:prompt"),
                        "decoding_config_sha256": sha256_text(f"{suite['suite_id']}:decoding"),
                        "raw_local_paths_persisted": False,
                        "raw_provider_outputs_persisted": False,
                    }
                    for suite in benchmark_manifest()["suites"]
                    if _suite_requires_official_harness_for_test(suite)
                ],
            }
        ),
        encoding="utf-8",
    )
    import_template = build_official_import_batch_template(
        acquisition_checklist_path=checklist_path,
        harness_pin_manifest_path=harness_pin_path,
    )
    import_template_path = tmp_path / "SECRET_EXECUTION_PLAN_IMPORT_TEMPLATE.json"
    import_template_path.write_text(json.dumps(import_template), encoding="utf-8")
    acquisition_status_path = tmp_path / "SECRET_EXECUTION_PLAN_ACQUISITION_STATUS.json"
    acquisition_status_path.write_text(
        json.dumps(
            {
                "schema": "axio_fusion_api.benchmark_acquisition_status.v1",
                "ready_to_assemble_manifest": False,
                "official_import_expected_count": import_template["import_entry_count"],
                "official_import_provided_count": 0,
                "official_import_missing_count": import_template["import_entry_count"],
                "secrets_persisted": False,
            }
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "official_harness_execution_plan.safe.json"

    plan = build_official_harness_execution_plan(
        import_batch_template_path=import_template_path,
        acquisition_status_path=acquisition_status_path,
        harness_pin_manifest_path=harness_pin_path,
    )
    assert fusion_cli_main(
        [
            "benchmark-official-harness-execution-plan",
            "--import-batch-template",
            str(import_template_path),
            "--acquisition-status",
            str(acquisition_status_path),
            "--harness-pin-manifest",
            str(harness_pin_path),
            "--output",
            str(output_path),
        ]
    ) == 0
    cli_plan = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"plan": plan, "cli_plan": cli_plan}, ensure_ascii=False)
    expected_task_count = _benchmark_official_import_suite_count() * checklist["run_unit_count"]
    mt_bench_tasks = [task for task in plan["tasks"] if task["suite_id"] == "mt_bench_work"]
    first_task = plan["tasks"][0]

    assert plan["schema"] == "axio_fusion_api.official_harness_execution_plan.v1"
    assert plan["status"] == "ready_to_execute"
    assert plan["execution_task_count"] == expected_task_count
    assert plan["ready_task_count"] == expected_task_count
    assert plan["suite_count"] == _benchmark_official_import_suite_count()
    assert plan["harness_pin_complete_task_count"] == expected_task_count
    assert plan["source_template_complete_task_count"] == expected_task_count
    assert plan["position_balanced_task_count"] == checklist["run_unit_count"]
    assert plan["mt_bench_position_balanced_required"] is True
    assert all(task["position_balanced_required"] is True for task in mt_bench_tasks)
    assert first_task["candidate_placeholder"].startswith("<RUN_UNIT_")
    assert len(first_task["candidate_id_hash"]) == 64
    assert len(first_task["harness_name_sha256"]) == 64
    assert first_task["expected_source_layout"] == "<OFFICIAL_HARNESS_OUTPUT_DIR>/<suite_id>/<candidate_placeholder>.jsonl"
    assert "source_template_sha256" in first_task
    assert "source" not in first_task
    assert cli_plan["execution_task_count"] == plan["execution_task_count"]
    assert cli_plan["blocking_reason_counts"] == {}
    assert "SECRET_CPA-PLUS_MODEL" not in serialized
    assert "SECRET_AISZ_MODEL" not in serialized
    assert "SECRET_EXECUTION_PLAN_DATASET_DIR" not in serialized
    assert "SECRET_EXECUTION_PLAN_IMPORT_DIR" not in serialized
    assert str(registry_path) not in serialized
    assert str(checklist_path) not in serialized
    assert str(harness_pin_path) not in serialized
    assert str(import_template_path) not in serialized
    assert str(acquisition_status_path) not in serialized
    assert str(output_path) not in serialized
    assert '"raw_candidate_ids_persisted": true' not in serialized
    assert '"raw_source_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


def test_standalone_benchmark_harness_pin_manifest_is_hash_only(tmp_path):
    secret_harness_root = tmp_path / "SECRET_HARNESS_ROOT"
    secret_raw_root = tmp_path / "SECRET_RAW_ROOT"
    secret_harness_root.mkdir()
    secret_raw_root.mkdir()

    repo_files = {
        "LiveCodeBench": [
            "lcb_runner/evaluation/compute_code_generation_metrics.py",
            "lcb_runner/evaluation/compute_code_execution_metrics.py",
            "lcb_runner/evaluation/testing_util.py",
            "lcb_runner/evaluation/pass_k_utils.py",
        ],
        "human-eval": [
            "human_eval/evaluation.py",
            "human_eval/execution.py",
            "human_eval/evaluate_functional_correctness.py",
        ],
        "gorilla-bfcl": [
            "berkeley-function-call-leaderboard/bfcl_eval/__main__.py",
            "berkeley-function-call-leaderboard/bfcl_eval/utils.py",
            "berkeley-function-call-leaderboard/bfcl_eval/eval_checker/ast_eval/ast_checker.py",
            "berkeley-function-call-leaderboard/bfcl_eval/constants/category_mapping.py",
            "berkeley-function-call-leaderboard/openfunctions_evaluation.py",
        ],
        "tau-bench": [
            "run.py",
            "tau_bench/run.py",
            "tau_bench/agents/tool_calling_agent.py",
            "tau_bench/envs/__init__.py",
            "tau_bench/envs/base.py",
            "tau_bench/envs/user.py",
            "tau_bench/envs/retail/env.py",
            "tau_bench/envs/retail/tasks_test.py",
            "tau_bench/envs/retail/rules.py",
            "tau_bench/envs/retail/tools/__init__.py",
            "tau_bench/envs/airline/env.py",
            "tau_bench/envs/airline/tasks_test.py",
            "tau_bench/envs/airline/rules.py",
            "tau_bench/envs/airline/tools/__init__.py",
        ],
        "google-research-ifeval": [
            "instruction_following_eval/evaluation_main.py",
            "instruction_following_eval/evaluation_lib.py",
            "instruction_following_eval/instructions.py",
            "instruction_following_eval/instructions_registry.py",
            "instruction_following_eval/instructions_util.py",
        ],
        "FastChat": [
            "fastchat/llm_judge/common.py",
            "fastchat/llm_judge/gen_judgment.py",
            "fastchat/llm_judge/show_result.py",
            "fastchat/llm_judge/clean_judgment.py",
            "fastchat/llm_judge/data/judge_prompts.jsonl",
        ],
    }
    for repo_name, relpaths in repo_files.items():
        repo = secret_harness_root / repo_name
        for relpath in relpaths:
            path = repo / relpath
            path.parent.mkdir(parents=True, exist_ok=True)
            content = (
                'VERSION_PREFIX = "BFCL_v3"\n'
                if relpath.endswith("bfcl_eval/constants/category_mapping.py")
                else f"# fixture for {repo_name}/{relpath}\n"
            )
            path.write_text(content, encoding="utf-8")
        subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.email", "fixture@example.invalid"], cwd=repo, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Fixture"], cwd=repo, check=True, capture_output=True)
        subprocess.run(["git", "remote", "add", "origin", f"https://example.invalid/{repo_name}.git"], cwd=repo, check=True, capture_output=True)
        subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        subprocess.run(["git", "commit", "-m", "fixture"], cwd=repo, check=True, capture_output=True)

    raw_files = [
        "livecodebench/test_generation.parquet",
        "livecodebench/execution_v2_test.parquet",
        "humaneval/HumanEval.jsonl.gz",
        "bfcl/BFCL_v3_simple.json",
        "bfcl/BFCL_v3_multiple.json",
        "bfcl/BFCL_v3_parallel.json",
        "bfcl/BFCL_v3_parallel_multiple.json",
        "bfcl/BFCL_v3_exec_simple.json",
        "bfcl/BFCL_v3_exec_multiple.json",
        "bfcl/BFCL_v3_live_simple.json",
        "bfcl/BFCL_v3_live_multiple.json",
        "bfcl/BFCL_v3_rest.json",
        "bfcl/BFCL_v3_sql.json",
        "ifeval/input_data.jsonl",
        "mt_bench/question.jsonl",
        "mt_bench/reference_answer/gpt-4.jsonl",
    ]
    for relpath in raw_files:
        path = secret_raw_root / relpath
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(f"fixture data for {relpath}\n", encoding="utf-8")

    output_path = tmp_path / "harness_pins.safe.json"
    manifest = build_benchmark_harness_pin_manifest(
        harness_root=secret_harness_root,
        raw_root=secret_raw_root,
    )
    assert fusion_cli_main(
        [
            "benchmark-harness-pin-manifest",
            "--harness-root",
            str(secret_harness_root),
            "--raw-root",
            str(secret_raw_root),
            "--output",
            str(output_path),
        ]
    ) == 0
    cli_manifest = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"manifest": manifest, "cli": cli_manifest}, ensure_ascii=False)
    by_suite = {row["suite_id"]: row for row in manifest["suites"]}

    assert manifest["schema"] == "axio_fusion_api.benchmark_harness_pin_manifest.v1"
    assert manifest["ready_suite_count"] == 6
    assert manifest["blocked_suite_count"] == 0
    assert cli_manifest["ready_suite_count"] == 6
    assert by_suite["ifeval"]["repo"]["commit"]
    assert by_suite["ifeval"]["dataset_snapshot_sha256"]
    assert by_suite["mt_bench_work"]["position_balanced"] is True
    assert by_suite["tau_bench"]["embedded_dataset_in_harness"] is True
    assert all(row["raw_local_paths_persisted"] is False for row in manifest["suites"])
    assert "SECRET_HARNESS_ROOT" not in serialized
    assert "SECRET_RAW_ROOT" not in serialized
    assert str(secret_harness_root) not in serialized
    assert str(secret_raw_root) not in serialized
    assert '"raw_local_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


def test_standalone_benchmark_harness_pin_manifest_binds_bfcl_v3_override(tmp_path):
    shared_harness_root = tmp_path / "SECRET_SHARED_HARNESS_ROOT"
    bfcl_v3_root = tmp_path / "SECRET_BFCL_V3_HARNESS_ROOT"
    raw_root = tmp_path / "SECRET_BFCL_V3_RAW_ROOT"
    bfcl_v3_root.mkdir()
    raw_root.mkdir()
    for relpath, text in {
        "berkeley-function-call-leaderboard/bfcl_eval/__main__.py": "# cli fixture\n",
        "berkeley-function-call-leaderboard/bfcl_eval/utils.py": "# utils fixture\n",
        "berkeley-function-call-leaderboard/bfcl_eval/eval_checker/ast_eval/ast_checker.py": "# scorer fixture\n",
        "berkeley-function-call-leaderboard/bfcl_eval/constants/category_mapping.py": 'VERSION_PREFIX = "BFCL_v3"\n',
        "berkeley-function-call-leaderboard/openfunctions_evaluation.py": "# compatibility fixture\n",
    }.items():
        path = bfcl_v3_root / relpath
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    subprocess.run(["git", "init"], cwd=bfcl_v3_root, check=True, capture_output=True)
    subprocess.run(["git", "config", "user.email", "fixture@example.invalid"], cwd=bfcl_v3_root, check=True, capture_output=True)
    subprocess.run(["git", "config", "user.name", "Fixture"], cwd=bfcl_v3_root, check=True, capture_output=True)
    subprocess.run(["git", "remote", "add", "origin", "https://example.invalid/bfcl-v3.git"], cwd=bfcl_v3_root, check=True, capture_output=True)
    subprocess.run(["git", "add", "."], cwd=bfcl_v3_root, check=True, capture_output=True)
    subprocess.run(["git", "commit", "-m", "fixture"], cwd=bfcl_v3_root, check=True, capture_output=True)
    for filename in evaluation_module._BFCL_V3_CASESET_FILENAMES:
        (raw_root / "bfcl").mkdir(parents=True, exist_ok=True)
        (raw_root / "bfcl" / filename).write_text("{}\n", encoding="utf-8")

    manifest = build_benchmark_harness_pin_manifest(
        harness_root=shared_harness_root,
        raw_root=raw_root,
        bfcl_harness_root=bfcl_v3_root,
    )
    output_path = tmp_path / "bfcl_v3_harness_pins.safe.json"
    assert fusion_cli_main(
        [
            "benchmark-harness-pin-manifest",
            "--harness-root",
            str(shared_harness_root),
            "--raw-root",
            str(raw_root),
            "--bfcl-harness-root",
            str(bfcl_v3_root),
            "--output",
            str(output_path),
        ]
    ) == 0
    bfcl_pin = next(row for row in manifest["suites"] if row["suite_id"] == "bfcl")
    cli_bfcl_pin = next(
        row
        for row in json.loads(output_path.read_text(encoding="utf-8"))["suites"]
        if row["suite_id"] == "bfcl"
    )
    serialized = json.dumps({"pin": bfcl_pin, "cli_pin": cli_bfcl_pin}, ensure_ascii=False)

    assert bfcl_pin["ready"] is True
    assert bfcl_pin["bfcl_dataset_version"] == "v3"
    assert bfcl_pin["bfcl_dataset_harness_version_compatible"] is True
    assert bfcl_pin["suite_harness_root_override_applied"] is True
    assert cli_bfcl_pin["bfcl_harness_version_marker_sha256"] == bfcl_pin["bfcl_harness_version_marker_sha256"]
    assert "SECRET_BFCL_V3" not in serialized
    assert str(bfcl_v3_root) not in serialized
    assert '"raw_harness_version_marker_persisted": true' not in serialized

    version_file = bfcl_v3_root / "berkeley-function-call-leaderboard/bfcl_eval/constants/category_mapping.py"
    version_file.write_text('VERSION_PREFIX = "BFCL_v4"\n', encoding="utf-8")
    mismatched_manifest = build_benchmark_harness_pin_manifest(
        harness_root=shared_harness_root,
        raw_root=raw_root,
        bfcl_harness_root=bfcl_v3_root,
    )
    mismatched_bfcl_pin = next(row for row in mismatched_manifest["suites"] if row["suite_id"] == "bfcl")
    assert mismatched_bfcl_pin["ready"] is False
    assert "bfcl_v3_dataset_harness_version_mismatch" in mismatched_bfcl_pin["reason_codes"]


def test_standalone_benchmark_source_manifest_template_and_validation_are_safe(tmp_path):
    secret_dataset_dir = tmp_path / "SECRET_SOURCE_DATASET_DIR"
    secret_import_dir = tmp_path / "SECRET_SOURCE_IMPORT_DIR"
    template_path = tmp_path / "source_manifest.template.json"
    validation_path = tmp_path / "source_manifest.validation.json"
    filled_path = tmp_path / "SECRET_FILLED_SOURCE_MANIFEST.json"

    template = build_benchmark_source_manifest_template(
        base_dir=str(secret_dataset_dir),
        import_dir=str(secret_import_dir),
        min_cases_per_suite=100,
    )
    assert fusion_cli_main(
        [
            "benchmark-source-manifest-template",
            "--base-dir",
            str(secret_dataset_dir),
            "--import-dir",
            str(secret_import_dir),
            "--min-cases-per-suite",
            "100",
            "--output",
            str(template_path),
        ]
    ) == 0

    cli_template = json.loads(template_path.read_text(encoding="utf-8"))
    template_path.write_text(json.dumps(cli_template), encoding="utf-8")
    template_validation = validate_benchmark_source_manifest(
        source_manifest_path=template_path,
        min_cases_per_suite=100,
    )
    filled = json.loads(json.dumps(template))
    filled["schema"] = "axio_fusion_api.benchmark_source_manifest.v1"
    for row in filled["suites"]:
        suite_id = row["suite_id"]
        source_record = row["source_record"]
        for key, value in list(source_record.items()):
            if key.endswith("_sha256") and value:
                source_record[key] = sha256_text(f"{suite_id}:{key}:pinned")
        source_record["license_policy_id"] = f"approved-{suite_id}-license-policy"
    filled_path.write_text(json.dumps(filled), encoding="utf-8")

    ready_validation = validate_benchmark_source_manifest(
        source_manifest_path=filled_path,
        min_cases_per_suite=100,
    )
    assert fusion_cli_main(
        [
            "benchmark-source-manifest-validate",
            "--source-manifest",
            str(filled_path),
            "--min-cases-per-suite",
            "100",
            "--output",
            str(validation_path),
        ]
    ) == 0

    cli_validation = json.loads(validation_path.read_text(encoding="utf-8"))
    serialized = json.dumps(
        {
            "template": template,
            "cli_template": cli_template,
            "template_validation": template_validation,
            "ready_validation": ready_validation,
            "cli_validation": cli_validation,
        },
        ensure_ascii=False,
    )
    livecodebench_row = next(row for row in ready_validation["suite_rows"] if row["suite_id"] == "livecodebench")

    assert template["schema"] == "axio_fusion_api.benchmark_source_manifest_template.v1"
    assert template["suite_count"] == _benchmark_suite_count()
    assert cli_template["suite_count"] == _benchmark_suite_count()
    assert template_validation["all_required_sources_ready"] is False
    assert "missing_dataset_snapshot_sha256" in template_validation["blocking_reason_counts"]
    assert ready_validation["all_required_sources_ready"] is True
    assert ready_validation["ready_suite_count"] == _benchmark_suite_count()
    assert cli_validation["all_required_sources_ready"] is True
    assert livecodebench_row["official_harness_required"] is True
    assert livecodebench_row["hash_field_pass_count"] == livecodebench_row["required_hash_field_count"]
    assert secret_dataset_dir.name not in serialized
    assert secret_import_dir.name not in serialized
    assert str(filled_path) not in serialized
    assert '"raw_dataset_paths_persisted": true' not in serialized
    assert '"raw_dataset_content_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


def test_standalone_benchmark_acquisition_status_reconciles_partial_inputs_safely(tmp_path):
    registry_path = _benchmark_registry_path(tmp_path)
    dataset_dir = tmp_path / "SECRET_STATUS_DATASET_DIR"
    import_dir = tmp_path / "SECRET_STATUS_IMPORT_DIR"
    dataset_dir.mkdir()
    import_dir.mkdir()
    math_path = dataset_dir / "math_500.jsonl"
    math_path.write_text(
        json.dumps({"prompt": "SECRET_STATUS_MATH_PROMPT", "answer": "42"}) + "\n",
        encoding="utf-8",
    )
    source_path = tmp_path / "SECRET_STATUS_OFFICIAL_SOURCE.jsonl"
    source_path.write_text(
        json.dumps(
            {
                "id": "case-1",
                "prompt": "SECRET_STATUS_LCB_PROMPT",
                "reference": "SECRET_STATUS_LCB_REFERENCE",
                "output": "SECRET_STATUS_PROVIDER_OUTPUT",
                "passed": True,
                "latency_ms": 11.0,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    safe_import = import_official_benchmark_run(
        suite_id="livecodebench",
        candidate_id="axio-pro",
        source_path=source_path,
        task_format="python_code",
        harness_name="LiveCodeBench official",
        harness_version="commit:abc123",
        dataset_snapshot="release:2026-07",
        evaluator_config="python=3.11 timeout=5",
    )
    import_path = import_dir / "livecodebench_axio_pro.safe.json"
    import_path.write_text(json.dumps(safe_import), encoding="utf-8")
    output_path = tmp_path / "acquisition_status.json"

    status = build_benchmark_acquisition_status(
        registry_path=registry_path,
        dataset_dir=dataset_dir,
        import_dirs=[import_dir],
        include_provider_baselines=False,
        min_cases_per_suite=1,
    )
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-acquisition-status",
            "--dataset-dir",
            str(dataset_dir),
            "--import-dir",
            str(import_dir),
            "--no-provider-baselines",
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_status = json.loads(output_path.read_text(encoding="utf-8"))
    math_row = next(row for row in status["local_dataset_rows"] if row["suite_id"] == "math_500")
    lcb_row = next(row for row in status["official_import_rows"] if row["suite_id"] == "livecodebench")
    serialized = json.dumps({"status": status, "cli": cli_status}, ensure_ascii=False)

    assert status["schema"] == "axio_fusion_api.benchmark_acquisition_status.v1"
    assert status["candidate_count"] == 9
    assert status["run_unit_count"] == 18
    assert status["candidate_count_by_type"] == {"axio": 3, "baseline": 6}
    assert status["run_unit_count_by_type"] == {"axio": 12, "baseline": 6}
    assert status["ready_to_assemble_manifest"] is False
    assert status["ready_local_dataset_suite_count"] == 1
    assert status["official_import_expected_count"] == _benchmark_official_import_suite_count() * status["run_unit_count"]
    assert status["official_import_provided_count"] == 1
    assert status["official_import_valid_count"] == 1
    assert status["official_import_missing_count"] == status["official_import_expected_count"] - status["official_import_provided_count"]
    assert status["position_balanced_expected_count"] == status["run_unit_count"]
    assert math_row["ready"] is True
    assert math_row["valid_case_count"] == 1
    assert lcb_row["provided_import_count"] == 1
    assert lcb_row["valid_import_count"] == 1
    assert lcb_row["missing_import_count"] == lcb_row["expected_import_count"] - lcb_row["provided_import_count"]
    assert "official_import_receipts_missing" in lcb_row["reason_codes"]
    assert cli_status["official_import_valid_count"] == 1
    assert "candidate_id" not in lcb_row["imported_run_validation"]["receipts"][0]
    assert "SECRET_STATUS" not in serialized
    assert str(dataset_dir) not in serialized
    assert str(import_dir) not in serialized
    assert str(source_path) not in serialized
    assert "axio-pro" not in serialized
    assert '"raw_candidate_ids_persisted": true' not in serialized
    assert '"raw_dataset_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


