def test_standalone_suite_aware_min_cases_allow_complete_small_aime_slice(tmp_path):
    dataset_dir = tmp_path / "datasets"
    dataset_dir.mkdir()
    for suite_id in ("aime_recent", "math_500"):
        rows = [
            {"prompt": f"SECRET_{suite_id}_{index}", "answer": str(index)}
            for index in range(30)
        ]
        (dataset_dir / f"{suite_id}.jsonl").write_text(
            "\n".join(json.dumps(row) for row in rows) + "\n",
            encoding="utf-8",
        )
    template = build_benchmark_dataset_manifest_template(
        base_dir=str(dataset_dir),
        min_cases_per_suite=100,
    )
    source_template = build_benchmark_source_manifest_template(
        base_dir=str(dataset_dir),
        min_cases_per_suite=100,
    )
    status = build_benchmark_acquisition_status(
        dataset_dir=dataset_dir,
        include_provider_baselines=False,
        min_cases_per_suite=100,
    )
    manifest_path = tmp_path / "SECRET_SUITE_MIN_MANIFEST.json"
    manifest_path.write_text(
        json.dumps(
            assemble_benchmark_dataset_manifest(
                dataset_dir=dataset_dir,
                min_cases_per_suite=100,
            )
        ),
        encoding="utf-8",
    )
    case_manifest = build_benchmark_case_hash_manifest(
        dataset_manifest_path=manifest_path,
        min_cases_per_suite=100,
    )
    serialized = json.dumps(
        {
            "template": template,
            "source_template": source_template,
            "status": status,
            "case_manifest": case_manifest,
        },
        ensure_ascii=False,
    )
    template_rows = {row["suite_id"]: row for row in template["suites"]}
    source_rows = {row["suite_id"]: row for row in source_template["suites"]}
    status_rows = {row["suite_id"]: row for row in status["local_dataset_rows"]}
    case_rows = {row["suite_id"]: row for row in case_manifest["suite_rows"]}

    assert template_rows["aime_recent"]["min_cases"] == 30
    assert source_rows["aime_recent"]["min_cases"] == 30
    assert template_rows["math_500"]["min_cases"] == 100
    assert status_rows["aime_recent"]["ready"] is True
    assert status_rows["aime_recent"]["effective_min_cases"] == 30
    assert status_rows["aime_recent"]["suite_min_case_policy"]["suite_override_applied"] is True
    assert "insufficient_case_count" not in status_rows["aime_recent"]["reason_codes"]
    assert status_rows["math_500"]["ready"] is False
    assert "insufficient_case_count" in status_rows["math_500"]["reason_codes"]
    assert case_rows["aime_recent"]["ready"] is True
    assert case_rows["aime_recent"]["case_hash_count"] == 30
    assert case_rows["math_500"]["ready"] is False
    assert "insufficient_case_hash_count" in case_rows["math_500"]["reason_codes"]
    assert "SECRET_aime_recent" not in serialized
    assert "SECRET_math_500" not in serialized
    assert str(manifest_path) not in serialized


