def test_standalone_gpqa_diamond_materialization_uses_fixed_per_case_option_order(
    tmp_path,
    monkeypatch,
):
    raw_root = tmp_path / "SECRET_GPQA_RAW_ROOT"
    output_dir = tmp_path / "SECRET_GPQA_OUTPUT_DIR"
    manifest_path = tmp_path / "SECRET_GPQA_DOWNLOAD_MANIFEST.json"
    source_path = raw_root / "gpqa/gpqa_diamond.csv"
    source_path.parent.mkdir(parents=True)
    source_path.write_text(
        "\n".join(
            [
                "Question,Correct Answer,Incorrect Answer 1,Incorrect Answer 2,Incorrect Answer 3,High-level domain,Subdomain",
                "SECRET_GPQA_QUESTION_ONE,Correct One,Wrong One A,Wrong One B,Wrong One C,physics,synthetic",
                "SECRET_GPQA_QUESTION_TWO,Correct Two,Wrong Two A,Wrong Two B,Wrong Two C,chemistry,synthetic",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    source_bytes = source_path.read_bytes()
    blob_digest = hashlib.sha1()
    blob_digest.update(f"blob {len(source_bytes)}\0".encode("ascii"))
    blob_digest.update(source_bytes)
    source_blob_sha1 = blob_digest.hexdigest()
    monkeypatch.setattr(benchmark_acquisition_module, "GPQA_EXPECTED_BYTES", len(source_bytes))
    monkeypatch.setattr(
        benchmark_acquisition_module,
        "GPQA_EXPECTED_GIT_BLOB_SHA1",
        source_blob_sha1,
    )
    monkeypatch.setattr(benchmark_acquisition_module, "GPQA_EXPECTED_ROWS", 2)
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "gpqa_diamond",
                        "status": "downloaded",
                        "official_source": benchmark_acquisition_module.GPQA_OFFICIAL_SOURCE,
                        "source_revision": benchmark_acquisition_module.GPQA_REVISION,
                        "source_git_blob_sha1": source_blob_sha1,
                        "authorization_receipt": {
                            "accepted": True,
                            "terms_contract_sha256": (
                                benchmark_acquisition_module.GPQA_TERMS_CONTRACT_SHA256
                            ),
                        },
                        "files": [
                            {
                                "path": benchmark_acquisition_module.GPQA_RELATIVE_PATH,
                                "bytes": len(source_bytes),
                                "rows": 2,
                                "sha256": hashlib.sha256(source_bytes).hexdigest(),
                                "git_blob_sha1": source_blob_sha1,
                            }
                        ],
                    }
                ]
            }
        ),
        encoding="utf-8",
    )

    blocked_receipt = materialize_benchmark_datasets(
        raw_root=raw_root,
        output_dir=tmp_path / "SECRET_GPQA_UNAUTHORIZED_OUTPUT_DIR",
        download_manifest_path=None,
        suite_ids=["gpqa_diamond"],
        min_cases_per_suite=2,
    )

    first_receipt = materialize_benchmark_datasets(
        raw_root=raw_root,
        output_dir=output_dir,
        download_manifest_path=manifest_path,
        suite_ids=["gpqa_diamond"],
        min_cases_per_suite=2,
    )
    rows = [
        json.loads(line)
        for line in (output_dir / "gpqa_diamond.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    first_options = [dict(row["options"]) for row in rows]
    first_answers = [row["answer"] for row in rows]
    second_receipt = materialize_benchmark_datasets(
        raw_root=raw_root,
        output_dir=output_dir,
        download_manifest_path=manifest_path,
        suite_ids=["gpqa_diamond"],
        min_cases_per_suite=2,
        overwrite=True,
    )
    rerun_rows = [
        json.loads(line)
        for line in (output_dir / "gpqa_diamond.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    validation = validate_benchmark_dataset(
        suite_id="gpqa_diamond",
        dataset_path=output_dir / "gpqa_diamond.jsonl",
        task_format="multiple_choice",
    )
    serialized = json.dumps(
        {"first": first_receipt, "second": second_receipt, "validation": validation},
        ensure_ascii=False,
    )

    assert first_receipt["suite_rows"][0]["adapter_id"] == "gpqa_diamond_csv_fixed_per_case_option_order_v1"
    assert first_receipt["suite_rows"][0]["status"] == "materialized"
    assert first_receipt["suite_rows"][0]["materialized_case_count"] == 2
    assert first_receipt["suite_rows"][0]["gpqa_artifact_integrity"]["valid"] is True
    assert blocked_receipt["suite_rows"][0]["status"] == "blocked_gated"
    assert blocked_receipt["suite_rows"][0]["reason_codes"] == ["gpqa_authorized_download_status_required"]
    assert second_receipt["suite_rows"][0]["status"] == "materialized"
    assert first_options == [dict(row["options"]) for row in rerun_rows]
    assert first_answers == [row["answer"] for row in rerun_rows]
    assert all(set(options) == {"A", "B", "C", "D"} for options in first_options)
    assert validation["ready_for_scoring"] is True
    assert validation["label_leakage_suspected_count"] == 0
    assert "SECRET_GPQA" not in serialized
    assert str(raw_root) not in serialized
    assert str(output_dir) not in serialized
    assert str(manifest_path) not in serialized
    assert str(source_path) not in serialized
    assert '"raw_dataset_paths_persisted": true' not in serialized
    assert '"raw_dataset_content_persisted": true' not in serialized
    assert '"raw_labels_persisted": true' not in serialized


