def test_standalone_benchmark_ablation_candidates_use_explicit_provider_panels(tmp_path):
    class FakeAblationClient:
        def __init__(self):
            self.calls = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt, "system": system})
            if "Synthesize the final benchmark answer" in prompt:
                assert profile.profile_id == "strong/omega"
                return "B"
            if "Rank the candidates and select the best answer" in prompt:
                assert profile.profile_id == "cheap-c/critic-lite"
                return "B"
            if profile.profile_id == "cheap-a/alpha":
                return "A"
            if profile.profile_id == "cheap-b/beta":
                return "C"
            return "B"

    registry_path = tmp_path / "ablation_registry.json"
    registry_path.write_text(
        json.dumps(
            {
                "models": [
                    {
                        "provider": "cheap-a",
                        "model": "alpha",
                        "api_format": "chat",
                        "capabilities": {"logic": 0.55, "structured_output": 0.62, "critique": 0.25},
                        "input_cost_per_million": 0.1,
                        "output_cost_per_million": 0.1,
                        "p50_latency_ms": 100,
                    },
                    {
                        "provider": "cheap-b",
                        "model": "beta",
                        "api_format": "chat",
                        "capabilities": {"logic": 0.58, "structured_output": 0.64, "critique": 0.3},
                        "input_cost_per_million": 0.11,
                        "output_cost_per_million": 0.11,
                        "p50_latency_ms": 110,
                    },
                    {
                        "provider": "cheap-c",
                        "model": "critic-lite",
                        "api_format": "chat",
                        "capabilities": {"logic": 0.64, "structured_output": 0.86, "critique": 0.9},
                        "input_cost_per_million": 0.12,
                        "output_cost_per_million": 0.12,
                        "p50_latency_ms": 120,
                    },
                    {
                        "provider": "strong",
                        "model": "omega",
                        "api_format": "chat",
                        "capabilities": {"logic": 0.96, "structured_output": 0.96, "critique": 0.98},
                        "input_cost_per_million": 8.0,
                        "output_cost_per_million": 12.0,
                        "p50_latency_ms": 900,
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    secret = "SECRET_ABLATION_PROMPT_SHOULD_NOT_PERSIST"
    dataset_path = tmp_path / "ablation_mcq.jsonl"
    dataset_path.write_text(
        json.dumps(
            {
                "question": f"What is 2 + 2? {secret}",
                "options": ["three", "four", "five"],
                "answer": "B",
            }
        )
        + "\n",
        encoding="utf-8",
    )
    judge_client = FakeAblationClient()
    strong_client = FakeAblationClient()

    judge_run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="cheap_models_plus_judge",
        registry_path=registry_path,
        live=True,
        client=judge_client,
    )
    strong_run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="cheap_models_plus_strong_judge_synthesizer",
        registry_path=registry_path,
        live=True,
        client=strong_client,
    )
    serialized_runs = json.dumps({"judge": judge_run, "strong": strong_run}, ensure_ascii=False)

    assert judge_run["provider_call_count"] == 4
    assert strong_run["provider_call_count"] == 5
    assert judge_run["case_results"][0]["prediction"] == "B"
    assert strong_run["case_results"][0]["prediction"] == "B"
    assert [row["profile"] for row in judge_client.calls] == [
        "cheap-a/alpha",
        "cheap-b/beta",
        "cheap-c/critic-lite",
        "cheap-c/critic-lite",
    ]
    assert [row["profile"] for row in strong_client.calls] == [
        "cheap-a/alpha",
        "cheap-b/beta",
        "cheap-c/critic-lite",
        "cheap-c/critic-lite",
        "strong/omega",
    ]
    assert any("Rank the candidates and select the best answer" in row["prompt"] for row in judge_client.calls)
    assert not any("Synthesize the final benchmark answer" in row["prompt"] for row in judge_client.calls)
    assert any("Synthesize the final benchmark answer" in row["prompt"] for row in strong_client.calls)
    assert not any("Compare these Axio Fusion candidate answers" in row["prompt"] for row in judge_client.calls + strong_client.calls)
    assert secret not in serialized_runs
    assert "What is 2 + 2" not in serialized_runs
    assert "raw_model_output_persisted\": true" not in serialized_runs


def test_standalone_benchmark_dataset_validation_catches_schema_and_leakage(tmp_path):
    secret_answer = "SECRET_VALIDATION_ANSWER"
    dataset_path = tmp_path / "bad_math.jsonl"
    dataset_path.write_text(
        "\n".join(
            [
                json.dumps({"prompt": f"Return {secret_answer}", "answer": secret_answer}),
                json.dumps({"prompt": "duplicate prompt", "answer": "42"}),
                json.dumps({"prompt": "duplicate prompt", "answer": "42"}),
                json.dumps({"prompt": "missing answer"}),
            ]
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "validation.json"

    report = validate_benchmark_dataset(
        suite_id="math_500",
        dataset_path=dataset_path,
        task_format="exact_match",
    )

    assert fusion_cli_main(
        [
            "benchmark-validate-dataset",
            "--suite-id",
            "math_500",
            "--dataset",
            str(dataset_path),
            "--task-format",
            "exact_match",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_report = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"report": report, "cli": cli_report}, ensure_ascii=False)

    assert report["row_count"] == 4
    assert report["valid_case_count"] == 3
    assert report["invalid_reason_counts"]["missing_reference_answer"] == 1
    assert report["duplicate_case_hash_count"] == 1
    assert report["label_leakage_suspected_count"] == 1
    assert report["ready_for_scoring"] is False
    assert cli_report["ready_for_scoring"] is False
    assert secret_answer not in serialized
    assert "duplicate prompt" not in serialized
    assert str(dataset_path) not in serialized
    assert '"raw_dataset_content_persisted": true' not in serialized


def test_standalone_generic_benchmark_runner_supports_non_mcq_formats(monkeypatch, tmp_path):
    class FakeGenericBenchmarkClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            if "Return only Python code" in prompt:
                return "def add(a, b):\n    return a + b\n"
            if "Available tools JSON" in prompt:
                return '{"name":"search","arguments":{"query":"alpha"}}'
            if "Translate from" in prompt:
                return "bonjour"
            if "Return only the final answer" in prompt:
                return "42"
            return "alpha concise"

    monkeypatch.setenv("AXIO_FUSION_ALLOW_BENCHMARK_CODE_EXEC", "1")
    registry_path = _benchmark_registry_path(tmp_path)
    cases = {
        "math_500": (
            "exact_match",
            {"prompt": "SECRET_EXACT_PROMPT", "answer": "42"},
        ),
        "flores_translation_instruction": (
            "translation_chrf",
            {"source": "SECRET_TRANSLATION_SOURCE", "source_language": "fr", "target_language": "en", "reference": "bonjour"},
        ),
        "bfcl": (
            "tool_call_ast",
            {
                "prompt": "SECRET_TOOL_PROMPT",
                "tools": [{"name": "search", "parameters": {"query": "string"}}],
                "expected_tool_call": {"name": "search", "arguments": {"query": "alpha"}},
            },
        ),
        "ifeval": (
            "instruction_checks",
            {"prompt": "SECRET_IFEVAL_PROMPT", "checks": {"contains": ["alpha"], "not_contains": ["beta"], "max_words": 5}},
        ),
        "humaneval": (
            "python_code",
            {
                "prompt": "SECRET_CODE_PROMPT",
                "entry_point": "add",
                "tests": "def check():\n    assert add(2, 3) == 5\ncheck()\n",
            },
        ),
    }
    runs = []
    for suite_id, (task_format, row) in cases.items():
        dataset_path = tmp_path / f"{suite_id}.jsonl"
        dataset_path.write_text(json.dumps(row) + "\n", encoding="utf-8")
        runs.append(
            run_benchmark_dataset(
                suite_id=suite_id,
                dataset_path=dataset_path,
                candidate_id="axio-fast",
                task_format=task_format,
                registry_path=registry_path,
                live=True,
                client=FakeGenericBenchmarkClient(),
            )
        )

    by_suite = {run["suite_id"]: run for run in runs}
    serialized = json.dumps(runs, ensure_ascii=False)

    assert by_suite["math_500"]["accuracy"] == 1.0
    assert by_suite["flores_translation_instruction"]["mean_score"] == 1.0
    assert by_suite["bfcl"]["case_results"][0]["correct"] is True
    assert by_suite["ifeval"]["case_results"][0]["score"] == 1.0
    assert by_suite["humaneval"]["case_results"][0]["metric"] == "pass_at_1"
    assert by_suite["humaneval"]["case_results"][0]["correct"] is True
    assert by_suite["humaneval"]["harness_receipt"]["official_harness_required"] is True
    assert by_suite["humaneval"]["harness_receipt"]["final_claim_eligible"] is False
    assert by_suite["humaneval"]["execution_contract"]["python_code_execution_enabled"] is True
    assert "SECRET_" not in serialized
    assert "assert add" not in serialized
    assert "bonjour" not in serialized
    assert "raw_provider_outputs_persisted\": true" not in serialized


def test_standalone_exact_match_parser_handles_wrapped_final_answers_safely(tmp_path):
    class FakeWrappedAnswerClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            if "SECRET_EXACT_CASE_TWO" in prompt:
                return "I will keep the derivation out of the final artifact.\n#### 3.14."
            return "Reasoning omitted for the strict benchmark.\nFinal answer: \\boxed{42}."

    registry_path = _benchmark_registry_path(tmp_path)
    dataset_path = tmp_path / "wrapped_exact.jsonl"
    dataset_path.write_text(
        "\n".join(
            [
                json.dumps({"prompt": "SECRET_EXACT_CASE_ONE", "answer": "42"}),
                json.dumps({"prompt": "SECRET_EXACT_CASE_TWO", "answer": "3.14"}),
            ]
        ),
        encoding="utf-8",
    )

    run = run_benchmark_dataset(
        suite_id="math_500",
        dataset_path=dataset_path,
        candidate_id="axio-fast",
        task_format="exact_match",
        registry_path=registry_path,
        live=True,
        client=FakeWrappedAnswerClient(),
    )
    serialized = json.dumps(run, ensure_ascii=False)

    assert run["accuracy"] == 1.0
    assert run["correct_count"] == 2
    assert all(row["correct"] is True for row in run["case_results"])
    assert all(row["answer_parser"] == "final_answer_text_v1" for row in run["case_results"])
    assert "SECRET_EXACT_CASE" not in serialized
    assert "Reasoning omitted" not in serialized
    assert "raw_model_output_persisted\": true" not in serialized


def test_standalone_generic_benchmark_ablation_candidates_use_provider_panels(tmp_path):
    class FakeGenericAblationClient:
        def __init__(self):
            self.calls = []

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append({"profile": profile.profile_id, "prompt": prompt, "system": system})
            if "Synthesize the final benchmark output" in prompt:
                return "42"
            if "Select the best benchmark answer" in prompt:
                return "42"
            if profile.profile_id == "weak/low":
                return "41"
            return "42"

    registry_path = _benchmark_registry_path(tmp_path)
    secret = "SECRET_GENERIC_ABLATION_PROMPT"
    dataset_path = tmp_path / "exact.jsonl"
    dataset_path.write_text(json.dumps({"prompt": f"What is 6 * 7? {secret}", "answer": "42"}) + "\n", encoding="utf-8")
    vote_client = FakeGenericAblationClient()
    strong_client = FakeGenericAblationClient()

    vote_run = run_benchmark_dataset(
        suite_id="math_500",
        dataset_path=dataset_path,
        candidate_id="cheap_models_vote",
        task_format="exact_match",
        registry_path=registry_path,
        live=True,
        client=vote_client,
    )
    strong_run = run_benchmark_dataset(
        suite_id="math_500",
        dataset_path=dataset_path,
        candidate_id="cheap_models_plus_strong_judge_synthesizer",
        task_format="exact_match",
        registry_path=registry_path,
        live=True,
        client=strong_client,
    )
    serialized_runs = json.dumps({"vote": vote_run, "strong": strong_run}, ensure_ascii=False)

    assert vote_run["accuracy"] == 1.0
    assert strong_run["accuracy"] == 1.0
    assert vote_run["provider_call_count"] == 3
    assert strong_run["provider_call_count"] == 5
    assert len(vote_client.calls) == 3
    assert len(strong_client.calls) == 5
    assert any("Select the best benchmark answer" in row["prompt"] for row in strong_client.calls)
    assert any("Synthesize the final benchmark output" in row["prompt"] for row in strong_client.calls)
    assert not any("Compare these Axio Fusion candidate answers" in row["prompt"] for row in vote_client.calls + strong_client.calls)
    assert not any("Synthesize one final answer" in row["prompt"] for row in vote_client.calls + strong_client.calls)
    assert secret not in serialized_runs
    assert "What is 6 * 7" not in serialized_runs
    assert "raw_model_output_persisted\": true" not in serialized_runs


