def test_standalone_strict_live_campaign_preflight_blocks_before_model_calls(monkeypatch, tmp_path):
    class ExplodingCampaignClient:
        def __init__(self):
            self.calls = 0

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls += 1
            raise AssertionError("strict live preflight must block before provider calls")

    monkeypatch.delenv("AXIO_FUSION_ALLOW_BENCHMARK_CODE_EXEC", raising=False)
    registry_path = _benchmark_registry_path(tmp_path)
    exact_path = tmp_path / "strict_math.jsonl"
    exact_path.write_text(
        json.dumps({"prompt": "SECRET_STRICT_PREFLIGHT_PROMPT", "answer": "42"}) + "\n",
        encoding="utf-8",
    )
    manifest_path = tmp_path / "strict_manifest.json"
    manifest_path.write_text(
        json.dumps({"suites": [{"suite_id": "math_500", "dataset": str(exact_path), "task_format": "exact_match"}]}),
        encoding="utf-8",
    )
    probe_evidence_path = _write_probe_evidence_audit_for_registry_fixture(tmp_path, registry_path)
    client = ExplodingCampaignClient()
    output_dir = tmp_path / "strict_campaign"

    campaign = run_benchmark_campaign(
        dataset_manifest_path=manifest_path,
        output_dir=output_dir,
        registry_path=registry_path,
        live=True,
        strict_live_preflight=True,
        client=client,
        provider_probe_evidence_audit_path=probe_evidence_path,
        min_cases_per_suite=1,
    )

    cli_output_dir = tmp_path / "strict_campaign_cli"
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-campaign",
            "--dataset-manifest",
            str(manifest_path),
            "--output-dir",
            str(cli_output_dir),
            "--provider-probe-evidence-audit",
            str(probe_evidence_path),
            "--live",
            "--strict-live-preflight",
            "--min-cases-per-suite",
            "1",
        ]
    ) == 0

    campaign_from_disk = json.loads((output_dir / "campaign.json").read_text(encoding="utf-8"))
    cli_campaign = json.loads((cli_output_dir / "campaign.json").read_text(encoding="utf-8"))
    runs_from_disk = json.loads((output_dir / "runs.json").read_text(encoding="utf-8"))
    claim_from_disk = json.loads((output_dir / "claim_audit.json").read_text(encoding="utf-8"))
    freeze_from_disk = json.loads((output_dir / "provider_baseline_freeze.safe.json").read_text(encoding="utf-8"))
    contamination_from_disk = json.loads((output_dir / "training_contamination_audit.json").read_text(encoding="utf-8"))
    serialized = json.dumps(
        {
            "campaign": campaign,
            "disk": campaign_from_disk,
            "cli": cli_campaign,
            "runs": runs_from_disk,
            "claim": claim_from_disk,
            "freeze": freeze_from_disk,
            "contamination": contamination_from_disk,
        },
        ensure_ascii=False,
    )
    blockers = set(campaign["strict_live_preflight"]["blockers"])

    assert client.calls == 0
    assert campaign["schema"] == "axio_fusion_api.benchmark_campaign.v1"
    assert campaign["mode"] == "live_preflight_blocked"
    assert campaign["status"] == "blocked"
    assert campaign["completed_or_resumed_run_count"] == 0
    assert campaign["network_calls_performed"] is False
    assert campaign["provider_call_count"] == 0
    assert campaign["strict_live_preflight"]["blocked_before_run_loop"] is True
    assert campaign_from_disk["mode"] == "live_preflight_blocked"
    assert cli_campaign["mode"] == "live_preflight_blocked"
    assert cli_campaign["completed_or_resumed_run_count"] == 0
    assert runs_from_disk["run_count"] == 0
    assert claim_from_disk["run_count"] == 0
    assert contamination_from_disk["final_claim_training_clean"] is True
    assert freeze_from_disk["final_claim_freeze_ready"] is False
    assert (output_dir / "scorecard.json").exists()
    assert (output_dir / "methodology.json").exists()
    assert (output_dir / "provider_probe_evidence_audit.safe.json").exists()
    assert list((output_dir / "runs").iterdir()) == []
    assert "readiness_all_required_suites_not_ready" in blockers
    assert "readiness_registry_live_probe_not_proven" in blockers
    assert "readiness_provider_baselines_not_pre_registered" in blockers
    assert "provider_baseline_freeze_not_ready" in blockers
    assert "provider_baseline_freeze_not_externally_ranked_top_three" in blockers
    assert "provider_baseline_freeze_insufficient_live_probe_evidence" in blockers
    assert "source_manifest_not_final_claim_eligible" in blockers
    assert "case_hash_manifest_not_ready" in blockers
    assert "case_hash_manifest_source_digest_mismatch" in blockers
    assert "source_manifest_case_hash_binding_receipt_invalid" in blockers
    assert "official_import_audit_not_ready_for_campaign_preflight" in blockers
    assert "api_surface_protocol_self_test_not_ready_for_campaign_preflight" in blockers
    assert "provider_input_adapter_self_test_not_ready_for_campaign_preflight" in blockers
    assert "system_development_readiness_missing" in blockers
    assert "system_development_readiness_not_ready_for_campaign_preflight" in blockers
