def test_standalone_benchmark_campaign_progress_plan_guides_safe_resume(monkeypatch, tmp_path):
    class FakeCampaignClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            return "42"

    monkeypatch.delenv("AXIO_FUSION_ALLOW_BENCHMARK_CODE_EXEC", raising=False)
    registry_path = _benchmark_registry_path(tmp_path)
    secret_case = "SECRET_PROGRESS_PLAN_CASE_SHOULD_NOT_PERSIST"
    exact_path = tmp_path / "progress_math.jsonl"
    exact_path.write_text(json.dumps({"prompt": secret_case, "answer": "42"}) + "\n", encoding="utf-8")
    manifest_path = tmp_path / "progress_manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {"suite_id": "math_500", "dataset": str(exact_path), "task_format": "exact_match"},
                ]
            }
        ),
        encoding="utf-8",
    )
    output_dir = tmp_path / "progress_campaign"

    campaign = run_benchmark_campaign(
        dataset_manifest_path=manifest_path,
        output_dir=output_dir,
        registry_path=registry_path,
        live=True,
        client=FakeCampaignClient(),
        min_cases_per_suite=1,
    )
    run_files = sorted((output_dir / "runs").glob("*.json"))
    missing_file = run_files[0]
    unsafe_file = run_files[1]
    unsafe_payload = json.loads(unsafe_file.read_text(encoding="utf-8"))
    unsafe_payload["raw_provider_output_persisted"] = True
    unsafe_payload["debug_secret"] = "SECRET_PROGRESS_PLAN_RUN_PAYLOAD"
    unsafe_file.write_text(json.dumps(unsafe_payload), encoding="utf-8")
    missing_file.unlink()

    plan = build_benchmark_campaign_progress_plan(
        dataset_manifest_path=manifest_path,
        output_dir=output_dir,
        registry_path=registry_path,
        min_cases_per_suite=1,
    )
    output_path = tmp_path / "SECRET_PROGRESS_OUTPUT" / "campaign_progress.safe.json"
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-campaign-progress-plan",
            "--dataset-manifest",
            str(manifest_path),
            "--output-dir",
            str(output_dir),
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_plan = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"plan": plan, "cli": cli_plan, "campaign": campaign}, ensure_ascii=False)
    statuses = {row["status"] for row in plan["missing_or_invalid_run_receipts"]}
    invalid_receipt = next(row for row in plan["missing_or_invalid_run_receipts"] if row["status"] == "invalid")

    assert plan["schema"] == "axio_fusion_api.benchmark_campaign_progress_plan.v1"
    assert plan["expected_run_count"] == campaign["expected_run_count"]
    assert plan["completed_run_count"] == campaign["expected_run_count"] - 2
    assert plan["missing_run_count"] == 1
    assert plan["invalid_run_count"] == 1
    assert plan["resume_needed"] is True
    assert plan["ready_for_scorecard"] is False
    assert statuses == {"missing", "invalid"}
    assert "unsafe_raw_persistence_flag_detected" in invalid_receipt["reason_codes"]
    assert plan["next_action"] == "resume_or_repair_campaign"
    assert "benchmark-campaign --dataset-manifest" in plan["next_command_templates"]["resume_campaign"]
    assert cli_plan["progress_digest_sha256"] == plan["progress_digest_sha256"]
    assert plan["anti_leakage_contract"]["raw_run_paths_persisted"] is False
    assert secret_case not in serialized
    assert "SECRET_PROGRESS_PLAN_RUN_PAYLOAD" not in serialized
    assert str(exact_path) not in serialized
    assert str(manifest_path) not in serialized
    assert str(registry_path) not in serialized
    assert str(output_dir) not in serialized
    assert str(output_path) not in serialized
    assert "unit/" not in serialized
    assert '"raw_provider_output_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


def test_standalone_benchmark_readiness_and_imported_external_runs_are_safe(tmp_path):
    registry_path = _benchmark_registry_path(tmp_path)
    imported_run = _claim_audit_run("mt_bench_work", "axio-pro", 1, total=1)
    imported_run.pop("harness_receipt", None)
    imported_path = tmp_path / "imported_axio_pro.json"
