    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "mt_bench_work",
                        "task_format": "external_pairwise_judge",
                        "imported_runs": {"axio-pro": str(imported_path)},
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "readiness.json"

    readiness = audit_benchmark_campaign_readiness(
        dataset_manifest_path=manifest_path,
        registry_path=registry_path,
        min_cases_per_suite=1,
    )

    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-readiness",
            "--dataset-manifest",
            str(manifest_path),
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0

    campaign = run_benchmark_campaign(
        dataset_manifest_path=manifest_path,
        output_dir=tmp_path / "import_campaign",
        registry_path=registry_path,
        candidate_ids=["axio-pro"],
        include_provider_baselines=False,
        min_cases_per_suite=1,
    )
    imported_copy = json.loads((tmp_path / "import_campaign" / "runs.json").read_text(encoding="utf-8"))
    serialized = json.dumps({"readiness": readiness, "campaign": campaign, "runs": imported_copy}, ensure_ascii=False)

    mt_row = next(row for row in readiness["rows"] if row["suite_id"] == "mt_bench_work")
    assert readiness["all_required_suites_ready"] is False
    assert readiness["provider_baseline_selection"] == "top_3_registry_prior"
    assert readiness["final_claim_provider_baselines_exhaustive"] is False
    assert "provider_baseline_selection_not_pre_registered_top_three" in readiness["final_claim_blocking_reasons"]
    assert readiness["will_claim_audit_be_possible"] is False
    assert mt_row["ready"] is False
    assert "external_judge_imports_incomplete" in mt_row["reason_codes"]
    assert "invalid_imported_runs" not in mt_row["reason_codes"]
    invalid_receipts = [row for row in mt_row["imported_run_validation"]["receipts"] if row["valid"] is False]
    assert any("missing_import_path" in row["reason_codes"] for row in invalid_receipts)
    assert all("missing_official_harness_receipt" not in row["reason_codes"] for row in invalid_receipts)
    assert output_path.exists()
    assert campaign["completed_or_resumed_run_count"] == 4
    assert campaign["artifacts"][0]["status"] == "imported"
    assert imported_copy["runs"][0]["candidate_id"] == "axio-pro"
    assert str(imported_path) not in serialized
    assert '"raw_dataset_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


