            "axio-pro",
            "--source",
            str(source_path),
            "--task-format",
            "python_code",
            "--harness-name",
            "LiveCodeBench official",
            "--harness-version",
            "commit:abc123",
            "--dataset-snapshot",
            "release:2026-07",
            "--evaluator-config",
            "python=3.11 timeout=5",
            "--output",
            str(output_path),
