    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "livecodebench",
                        "task_format": "python_code",
                        "imported_runs": imported_runs,
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    readiness = audit_benchmark_campaign_readiness(
        dataset_manifest_path=manifest_path,
        registry_path=_benchmark_registry_path(tmp_path),
        candidate_ids=["axio-pro"],
        include_provider_baselines=False,
        min_cases_per_suite=2,
    )
    row = next(item for item in readiness["rows"] if item["suite_id"] == "livecodebench")
    serialized = json.dumps({"run": run, "cli": cli_run, "readiness": readiness}, ensure_ascii=False)

    assert run["mode"] == "official_import"
