    assert run["correct_count"] == 1
    assert run["accuracy"] == 0.5
    assert run["harness_receipt"]["official_or_audited_harness"] is True
    assert run["harness_receipt"]["final_claim_eligible"] is True
    assert cli_run["harness_receipt"]["harness_name_sha256"]
    assert row["ready"] is True
    assert row["case_count"] == 2
    assert row["expected_imported_run_count"] == 4
    assert row["provided_imported_run_count"] == 4
    assert row["valid_imported_run_count"] == 4
    assert row["missing_imported_run_count"] == 0
    assert row["invalid_imported_run_count"] == 0
    assert row["imported_run_validation"]["receipts"][0]["candidate_id_hash"]
    assert "candidate_id" not in row["imported_run_validation"]["receipts"][0]
    assert "SECRET_OFFICIAL" not in serialized
    assert "SECRET_PROVIDER_OUTPUT" not in serialized
    assert str(source_path) not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


