def test_standalone_official_import_case_alignment_blocks_mismatched_candidates(tmp_path):
    import_dir = tmp_path / "imports"
    import_dir.mkdir()
    first_source = tmp_path / "SECRET_ALIGN_SOURCE_ONE.jsonl"
    second_source = tmp_path / "SECRET_ALIGN_SOURCE_TWO.jsonl"
    first_source.write_text(
        json.dumps(
            {
                "id": "shared-visible-id-one",
                "prompt": "SECRET_ALIGN_PROMPT_ONE",
                "reference": "SECRET_ALIGN_REFERENCE_ONE",
                "output": "SECRET_ALIGN_OUTPUT_ONE",
                "passed": True,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    second_source.write_text(
        json.dumps(
            {
                "id": "different-visible-id-two",
                "prompt": "SECRET_ALIGN_PROMPT_TWO",
                "reference": "SECRET_ALIGN_REFERENCE_TWO",
                "output": "SECRET_ALIGN_OUTPUT_TWO",
                "passed": True,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    imported_runs = {}
    import_paths = []
    for model, source in (("axio-pro", first_source), ("axio-terra", second_source)):
        for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
            run = import_official_benchmark_run(
                suite_id="livecodebench",
                candidate_id=f"{model}@{_api_format_slug_for_test(api_format)}",
                source_path=source,
                task_format="python_code",
                api_format=api_format,
                harness_name="LiveCodeBench official",
                harness_version="commit:align",
                dataset_snapshot="release:2026-07",
                evaluator_config="python=3.11 timeout=5",
            )
            path = import_dir / f"{model}_{_api_format_slug_for_test(api_format)}.safe.json"
            path.write_text(json.dumps(run), encoding="utf-8")
            import_paths.append(path)
            imported_runs[run["api_surface_id"]] = str(path)
    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "livecodebench",
                        "task_format": "python_code",
                        "imported_runs": imported_runs,
                    }
                ]
            }
        ),
        encoding="utf-8",
    )

    readiness = audit_benchmark_campaign_readiness(
        dataset_manifest_path=manifest_path,
        registry_path=_benchmark_registry_path(tmp_path),
        candidate_ids=["axio-pro", "axio-terra"],
        include_provider_baselines=False,
        min_cases_per_suite=1,
    )
    status = build_benchmark_acquisition_status(
        registry_path=_benchmark_registry_path(tmp_path),
        dataset_dir=tmp_path / "datasets",
        import_dirs=[import_dir],
        candidate_ids=["axio-pro", "axio-terra"],
        include_provider_baselines=False,
        max_provider_baselines=0,
        min_cases_per_suite=1,
    )
    readiness_row = next(row for row in readiness["rows"] if row["suite_id"] == "livecodebench")
    status_row = next(row for row in status["official_import_rows"] if row["suite_id"] == "livecodebench")
    serialized = json.dumps({"readiness": readiness, "status": status}, ensure_ascii=False)

    assert readiness_row["provided_imported_run_count"] == 8
    assert readiness_row["valid_imported_run_count"] == 8
    assert readiness_row["ready"] is False
    assert "official_import_case_hashes_misaligned" in readiness_row["reason_codes"]
    assert readiness_row["imported_case_alignment"]["case_hash_sets_identical"] is False
    assert readiness_row["imported_case_alignment"]["common_case_hash_count"] == 0
    assert readiness_row["imported_case_alignment"]["union_case_hash_count"] == 2
    assert status_row["imported_case_alignment"]["case_hash_sets_identical"] is False
    assert "official_import_case_hashes_misaligned" in status_row["reason_codes"]
    assert "candidate_id" not in readiness_row["imported_case_alignment"]["candidate_receipts"][0]
    assert "SECRET_ALIGN" not in serialized
    assert str(first_source) not in serialized
    assert str(second_source) not in serialized
    assert all(str(path) not in serialized for path in import_paths)
    assert '"raw_import_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


