def test_standalone_official_source_case_hashes_bind_humaneval_and_ifeval_without_model_calls(tmp_path):
    human_source = tmp_path / "SECRET_HUMANEVAL_SOURCE.jsonl.gz"
    ifeval_source = tmp_path / "SECRET_IFEVAL_SOURCE.jsonl"
    secret_prompt = "SECRET_OFFICIAL_CASE_PROMPT_MUST_NOT_PERSIST"
    secret_test = "SECRET_HIDDEN_TEST_MUST_NOT_PERSIST"
    with gzip.open(human_source, "wt", encoding="utf-8") as handle:
        for index in range(2):
            handle.write(
                json.dumps(
                    {
                        "task_id": f"HumanEval/{index}",
                        "prompt": f"def secret_{index}(): {secret_prompt}",
                        "test": secret_test,
                        "canonical_solution": "return 1",
                    }
                )
                + "\n"
            )
    ifeval_source.write_text(
        "\n".join(
            json.dumps(
                {
                    "key": index,
                    "prompt": f"{secret_prompt}_{index}",
                    "instruction_id_list": ["length_constraints:number_words"],
                    "kwargs": [{"num_words": 3}],
                }
            )
            for index in range(2)
        )
        + "\n",
        encoding="utf-8",
    )
    manifest_path = tmp_path / "SECRET_OFFICIAL_CASE_DATASET_MANIFEST.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "humaneval",
                        "task_format": "python_code",
                        "official_case_source": str(human_source),
                    },
                    {
                        "suite_id": "ifeval",
                        "task_format": "instruction_checks",
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "official_case_hash_manifest.safe.json"

    direct = build_benchmark_case_hash_manifest(
        dataset_manifest_path=manifest_path,
        official_case_sources={"ifeval": ifeval_source},
        min_cases_per_suite=2,
    )
    assert fusion_cli_main(
        [
            "benchmark-case-hash-manifest",
            "--dataset-manifest",
            str(manifest_path),
            "--official-case-source",
            f"ifeval={ifeval_source}",
            "--min-cases-per-suite",
            "2",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_payload = json.loads(output_path.read_text(encoding="utf-8"))
    rows = {row["suite_id"]: row for row in direct["suite_rows"]}
    cli_rows = {row["suite_id"]: row for row in cli_payload["suite_rows"]}
    serialized = json.dumps({"direct": direct, "cli": cli_payload}, ensure_ascii=False)

    assert rows["humaneval"]["ready"] is True
    assert rows["humaneval"]["case_source_parser"] == "humaneval_task_id_v1"
    assert rows["humaneval"]["case_hash_count"] == 2
    assert rows["humaneval"]["official_harness_outputs_required_for_scoring"] is True
    assert rows["humaneval"]["official_harness_outputs_available"] is False
    assert rows["ifeval"]["ready"] is True
    assert rows["ifeval"]["case_source_parser"] == "ifeval_key_v1"
    assert rows["ifeval"]["case_hash_count"] == 2
    assert cli_rows["humaneval"]["materialized_case_hash_manifest_sha256"] == rows["humaneval"]["materialized_case_hash_manifest_sha256"]
    assert cli_rows["ifeval"]["materialized_case_hash_manifest_sha256"] == rows["ifeval"]["materialized_case_hash_manifest_sha256"]
    assert secret_prompt not in serialized
    assert secret_test not in serialized
    assert "SECRET_HUMANEVAL_SOURCE" not in serialized
    assert "SECRET_IFEVAL_SOURCE" not in serialized
    assert str(manifest_path) not in serialized
    assert '"raw_case_hashes_persisted": true' not in serialized
