def test_standalone_source_manifest_prepare_fills_hash_bindings_safely(tmp_path):
    dataset_dir = tmp_path / "SECRET_PREPARE_DATASETS"
    import_dir = tmp_path / "SECRET_PREPARE_IMPORTS"
    dataset_dir.mkdir()
    import_dir.mkdir()
    for suite in benchmark_manifest()["suites"]:
        suite_id = suite["suite_id"]
        task_format = suite["task_format"]
        if _suite_requires_official_harness_for_test(suite):
            imported = import_official_benchmark_run(
                suite_id=suite_id,
                candidate_id="axio-pro",
                source_path=_official_import_source_fixture(tmp_path),
                task_format=task_format,
                harness_name=f"{suite_id} official",
                harness_version=f"commit:{suite_id}",
                dataset_snapshot=f"snapshot:{suite_id}",
                evaluator_config=f"evaluator:{suite_id}",
                position_balanced=task_format == "external_pairwise_judge",
            )
            (import_dir / f"{suite_id}_axio_pro.safe.json").write_text(json.dumps(imported), encoding="utf-8")
            continue
        row = _minimal_dataset_row_for_format(task_format, suite_id=suite_id)
        (dataset_dir / f"{suite_id}.jsonl").write_text(json.dumps(row) + "\n", encoding="utf-8")
    dataset_manifest_path = tmp_path / "SECRET_PREPARE_DATASET_MANIFEST.json"
    dataset_manifest_path.write_text(
        json.dumps(
            assemble_benchmark_dataset_manifest(
                dataset_dir=dataset_dir,
                import_dirs=[import_dir],
                min_cases_per_suite=1,
            )
        ),
        encoding="utf-8",
    )
    case_manifest_path = tmp_path / "SECRET_PREPARE_CASE_HASH_MANIFEST.json"
    case_manifest = build_benchmark_case_hash_manifest(
        dataset_manifest_path=dataset_manifest_path,
        candidate_ids=["axio-pro"],
        min_cases_per_suite=1,
    )
    case_manifest_path.write_text(json.dumps(case_manifest), encoding="utf-8")
    harness_pin_manifest = {
        "schema": "axio_fusion_api.benchmark_harness_pin_manifest.v1",
        "suites": [
            {
                "suite_id": suite["suite_id"],
                "task_format": suite["task_format"],
                "ready": True,
                "harness_name_sha256": sha256_text(f"{suite['suite_id']}:harness"),
                "harness_version": f"commit:{suite['suite_id']}",
                "harness_version_sha256": sha256_text(f"commit:{suite['suite_id']}"),
                "dataset_snapshot_sha256": sha256_text(f"{suite['suite_id']}:dataset"),
                "evaluator_config_sha256": sha256_text(f"{suite['suite_id']}:evaluator"),
                "prompt_protocol_sha256": sha256_text(f"{suite['suite_id']}:prompt"),
                "decoding_config_sha256": sha256_text(f"{suite['suite_id']}:decoding"),
                "raw_local_paths_persisted": False,
                "raw_provider_outputs_persisted": False,
            }
            for suite in benchmark_manifest()["suites"]
            if _suite_requires_official_harness_for_test(suite)
        ],
        "raw_local_paths_persisted": False,
        "raw_provider_outputs_persisted": False,
    }
    harness_pin_manifest_path = tmp_path / "SECRET_PREPARE_HARNESS_PINS.json"
    harness_pin_manifest_path.write_text(json.dumps(harness_pin_manifest), encoding="utf-8")
    source_template_path = tmp_path / "SECRET_PREPARE_SOURCE_TEMPLATE.json"
    source_template_path.write_text(
        json.dumps(
            build_benchmark_source_manifest_template(
                base_dir=str(dataset_dir),
                import_dir=str(import_dir),
                min_cases_per_suite=1,
            )
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "prepared_source_manifest.json"

    prepared = prepare_benchmark_source_manifest(
        template_path=source_template_path,
        case_hash_manifest_path=case_manifest_path,
        harness_pin_manifest_path=harness_pin_manifest_path,
        min_cases_per_suite=1,
    )
    assert fusion_cli_main(
        [
            "benchmark-source-manifest-prepare",
            "--template",
            str(source_template_path),
            "--case-hash-manifest",
            str(case_manifest_path),
            "--harness-pin-manifest",
            str(harness_pin_manifest_path),
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0
    cli_prepared = json.loads(output_path.read_text(encoding="utf-8"))
    validation = validate_benchmark_source_manifest(
        source_manifest_path=output_path,
        min_cases_per_suite=1,
    )
    serialized = json.dumps({"prepared": prepared, "cli": cli_prepared, "validation": validation}, ensure_ascii=False)
    official_row = next(row for row in cli_prepared["suites"] if row["suite_id"] == "ifeval")

    assert prepared["schema"] == "axio_fusion_api.benchmark_source_manifest.v1"
    assert cli_prepared["source_manifest_preparation_receipt"]["case_hash_bound_suite_count"] == _benchmark_suite_count()
    assert (
        cli_prepared["source_manifest_preparation_receipt"]["official_harness_pin_bound_suite_count"]
        == _benchmark_official_import_suite_count()
    )
    assert validation["all_required_sources_ready"] is True
    assert validation["ready_suite_count"] == _benchmark_suite_count()
    assert official_row["source_record"]["official_harness_name_sha256"] == sha256_text("ifeval:harness")
    assert official_row["source_record"]["official_harness_version_sha256"] == sha256_text("commit:ifeval")
    assert "SECRET_PREPARE_DATASETS" not in serialized
    assert "SECRET_PREPARE_IMPORTS" not in serialized
    assert str(source_template_path) not in serialized
    assert str(case_manifest_path) not in serialized
    assert str(harness_pin_manifest_path) not in serialized
    assert '"raw_dataset_paths_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


def test_standalone_source_manifest_binds_case_hash_manifest_safely(tmp_path):
    dataset_dir = tmp_path / "SECRET_BIND_DATASETS"
    import_dir = tmp_path / "SECRET_BIND_IMPORTS"
    dataset_dir.mkdir()
    import_dir.mkdir()
    for suite in benchmark_manifest()["suites"]:
        suite_id = suite["suite_id"]
        task_format = suite["task_format"]
        if _suite_requires_official_harness_for_test(suite):
            imported = import_official_benchmark_run(
                suite_id=suite_id,
                candidate_id="axio-pro",
                source_path=_official_import_source_fixture(tmp_path),
                task_format=task_format,
                harness_name=f"{suite_id} official",
                harness_version="commit:bind-test",
                dataset_snapshot="snapshot:bind-test",
                evaluator_config="deterministic-evaluator",
                position_balanced=task_format == "external_pairwise_judge",
            )
            (import_dir / f"{suite_id}_axio_pro.safe.json").write_text(json.dumps(imported), encoding="utf-8")
            continue
        row = _minimal_dataset_row_for_format(task_format, suite_id=suite_id)
        (dataset_dir / f"{suite_id}.jsonl").write_text(json.dumps(row) + "\n", encoding="utf-8")
    dataset_manifest_path = tmp_path / "SECRET_BIND_DATASET_MANIFEST.json"
    dataset_manifest_path.write_text(
        json.dumps(
            assemble_benchmark_dataset_manifest(
                dataset_dir=dataset_dir,
                import_dirs=[import_dir],
                min_cases_per_suite=1,
            )
        ),
        encoding="utf-8",
    )
    case_manifest_path = tmp_path / "SECRET_BIND_CASE_HASH_MANIFEST.json"
    case_manifest = build_benchmark_case_hash_manifest(
        dataset_manifest_path=dataset_manifest_path,
        candidate_ids=["axio-pro"],
        min_cases_per_suite=1,
    )
    case_manifest_path.write_text(json.dumps(case_manifest), encoding="utf-8")
    source_template = build_benchmark_source_manifest_template(
        base_dir=str(dataset_dir),
        import_dir=str(import_dir),
        min_cases_per_suite=1,
    )
    source_template["schema"] = "axio_fusion_api.benchmark_source_manifest.v1"
    for row in source_template["suites"]:
        suite_id = row["suite_id"]
        source_record = row["source_record"]
        for key, value in list(source_record.items()):
            if key.endswith("_sha256") and value and key != "materialized_case_hash_manifest_sha256":
                source_record[key] = sha256_text(f"{suite_id}:{key}:bound")
        source_record["license_policy_id"] = f"approved-{suite_id}-policy"
    source_manifest_path = tmp_path / "SECRET_BIND_SOURCE_MANIFEST.json"
    source_manifest_path.write_text(json.dumps(source_template), encoding="utf-8")
    output_path = tmp_path / "bound_source_manifest.json"

    bound = bind_benchmark_source_manifest_case_hashes(
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_manifest_path,
        min_cases_per_suite=1,
    )
    assert fusion_cli_main(
        [
            "benchmark-source-manifest-bind-case-hashes",
            "--source-manifest",
            str(source_manifest_path),
            "--case-hash-manifest",
            str(case_manifest_path),
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_bound = json.loads(output_path.read_text(encoding="utf-8"))
    ready_validation = validate_benchmark_source_manifest(
        source_manifest_path=output_path,
        min_cases_per_suite=1,
    )
    serialized = json.dumps({"api": bound, "cli": cli_bound, "validation": ready_validation}, ensure_ascii=False)

    assert bound["case_hash_binding_receipt"]["all_required_case_hashes_bound"] is True
    assert bound["case_hash_binding_receipt"]["bound_suite_count"] == _benchmark_suite_count()
    assert cli_bound["case_hash_binding_receipt"]["bound_suite_count"] == _benchmark_suite_count()
    assert ready_validation["all_required_sources_ready"] is True
    assert ready_validation["ready_suite_count"] == _benchmark_suite_count()
    assert all(
        row["source_record"]["materialized_case_hash_manifest_sha256"]
        == next(
            case_row["materialized_case_hash_manifest_sha256"]
            for case_row in case_manifest["suite_rows"]
            if case_row["suite_id"] == row["suite_id"]
        )
        for row in cli_bound["suites"]
    )
    assert "SECRET_BIND_DATASETS" not in serialized
    assert "SECRET_BIND_IMPORTS" not in serialized
    assert str(source_manifest_path) not in serialized
    assert str(case_manifest_path) not in serialized
    assert "SECRET_OFFICIAL_PROMPT_ONE" not in serialized
    assert "SECRET_PROVIDER_OUTPUT_ONE" not in serialized
    assert '"raw_case_hashes_persisted": true' not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized


def test_standalone_benchmark_evidence_pack_is_safe_and_actionable(tmp_path):
    registry_path = _benchmark_registry_path(tmp_path)
    dataset_dir = tmp_path / "datasets"
    dataset_dir.mkdir()
    math_path = dataset_dir / "math_500.jsonl"
    secret_prompt = "SECRET_EVIDENCE_PACK_PROMPT"
    math_path.write_text(json.dumps({"prompt": f"What is 6 * 7? {secret_prompt}", "answer": "42"}) + "\n", encoding="utf-8")
    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "math_500",
                        "dataset": str(math_path),
                        "task_format": "exact_match",
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    output_path = tmp_path / "evidence_pack.json"

    pack = build_benchmark_evidence_pack(
        registry_path=registry_path,
        dataset_manifest_path=manifest_path,
        campaign_dir=tmp_path / "missing_campaign",
        include_provider_baselines=True,
        max_provider_baselines=None,
        min_cases_per_suite=1,
    )
    assert fusion_cli_main(
        [
            "--registry",
            str(registry_path),
            "benchmark-evidence-pack",
            "--dataset-manifest",
            str(manifest_path),
            "--campaign-dir",
            str(tmp_path / "missing_campaign"),
            "--all-provider-baselines",
            "--min-cases-per-suite",
            "1",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_pack = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"pack": pack, "cli": cli_pack}, ensure_ascii=False)

    assert pack["schema"] == "axio_fusion_api.benchmark_evidence_pack.v1"
    assert pack["readiness_level"] == "dataset_or_imports_incomplete"
    assert pack["required_suite_count"] == _benchmark_suite_count()
    assert pack["methodology_summary"]["suite_count"] == _benchmark_suite_count()
    assert pack["dataset_acquisition_summary"]["suite_count"] == _benchmark_suite_count()
    assert pack["dataset_acquisition_summary"]["local_jsonl_suite_count"] == _benchmark_local_jsonl_suite_count()
    assert pack["dataset_acquisition_summary"]["official_or_audited_import_suite_count"] == _benchmark_official_import_suite_count()
    campaign_candidate_count = pack["run_matrix_summary"]["candidate_count"]
    assert pack["dataset_acquisition_summary"]["campaign_candidate_count"] == campaign_candidate_count
    assert pack["dataset_acquisition_summary"]["candidate_count_source"] == "run_matrix_summary"
    campaign_run_unit_count = pack["run_matrix_summary"]["run_unit_count"]
    assert pack["dataset_acquisition_summary"]["campaign_run_unit_count"] == campaign_run_unit_count
    assert pack["dataset_acquisition_summary"]["required_official_import_receipt_count"] == _benchmark_official_import_suite_count() * campaign_run_unit_count
    assert pack["dataset_acquisition_summary"]["required_position_balanced_import_receipt_count"] == campaign_run_unit_count
    assert pack["dataset_acquisition_summary"]["import_receipt_count_assumes_all_campaign_candidates"] is True
    acquisition_by_suite = {row["suite_id"]: row for row in pack["dataset_acquisition_summary"]["suite_rows"]}
    assert acquisition_by_suite["math_500"]["input_mode"] == "local_jsonl"
    assert acquisition_by_suite["math_500"]["required_import_receipt_count"] == 0
    assert acquisition_by_suite["livecodebench"]["import_receipt_required_for_each_candidate"] is True
    assert acquisition_by_suite["livecodebench"]["required_import_receipt_count"] == campaign_run_unit_count
    assert acquisition_by_suite["mt_bench_work"]["position_balanced_import_required"] is True
    assert acquisition_by_suite["mt_bench_work"]["required_import_receipt_count"] == campaign_run_unit_count
    assert acquisition_by_suite["mt_bench_work"]["position_balanced_required_receipt_count"] == campaign_run_unit_count
    assert pack["run_matrix_summary"]["provider_baseline_selection"] == "externally_ranked_top_three_pre_registered"
    assert pack["readiness_summary"]["ready_suite_count"] == 0
    readiness_candidate_count = pack["readiness_summary"]["candidate_count"]
    readiness_run_unit_count = pack["readiness_summary"]["run_unit_count"]
    assert pack["readiness_summary"]["official_import_suite_count"] == _benchmark_official_import_suite_count()
    assert pack["readiness_summary"]["official_import_expected_count"] == _benchmark_official_import_suite_count() * readiness_run_unit_count
    assert pack["readiness_summary"]["official_import_provided_count"] == 0
    assert pack["readiness_summary"]["official_import_valid_count"] == 0
    assert pack["readiness_summary"]["official_import_missing_count"] == _benchmark_official_import_suite_count() * readiness_run_unit_count
    assert pack["readiness_summary"]["official_import_invalid_count"] == 0
    assert pack["readiness_summary"]["raw_candidate_ids_persisted"] is False
    assert pack["final_audit_summary"]["final_completion_allowed"] is False
    assert pack["missing_summary"]["final_missing_count"] > 0
    assert pack["execution_guidance"]["current_stage"] == "dataset_or_imports_incomplete"
    assert pack["execution_guidance"]["next_step"] == "complete_dataset_or_official_imports"
    assert pack["execution_guidance"]["next_command_template_step"] == "assemble_safe_dataset_manifest"
    assert pack["execution_guidance"]["dataset_manifest_ready"] is True
    assert pack["execution_guidance"]["datasets_or_imports_ready"] is False
    assert pack["execution_guidance"]["priority_checklist"][0]["step"] == "provider_registry"
    assert pack["execution_guidance"]["priority_checklist"][0]["status"] == "passed"
    assert any(item["step"] == "datasets_and_official_imports" and item["status"] == "blocked" for item in pack["execution_guidance"]["priority_checklist"])
    assert any(row["step"] == "create_benchmark_acquisition_checklist" for row in pack["next_command_templates"])
    assert any(row["step"] == "create_official_import_batch_template" for row in pack["next_command_templates"])
    assert any(row["step"] == "batch_import_official_or_audited_runs" for row in pack["next_command_templates"])
    assert any(row["step"] == "run_live_campaign" for row in pack["next_command_templates"])
    assert "<REGISTRY_JSON>" in serialized
    assert "<CAMPAIGN_DIR>" in serialized
    assert secret_prompt not in serialized
    assert "What is 6 * 7" not in serialized
    assert str(math_path) not in serialized
    assert str(manifest_path) not in serialized
    assert "raw_dataset_content_persisted\": true" not in serialized
    assert "raw_dataset_paths_persisted\": true" not in serialized
    assert "secrets_persisted\": true" not in serialized
    assert cli_pack["schema"] == pack["schema"]
    assert cli_pack["input_receipts"]["registry"]["raw_path_persisted"] is False
    assert cli_pack["execution_guidance"]["next_step"] == pack["execution_guidance"]["next_step"]


