def test_standalone_remote_api_execution_audit_blocks_local_inference_inputs(tmp_path):
    source_root = tmp_path / "isolated_fusion_source"
    source_root.mkdir()
    (source_root / "runtime.py").write_text(
        "import torch\nimport importlib\nimportlib.import_module('vllm')\n",
        encoding="utf-8",
    )
    (source_root / "model.safetensors").write_bytes(b"not-a-model")
    metadata_path = tmp_path / "pyproject.toml"
    metadata_path.write_text('[project]\ndependencies = ["transformers>=4"]\n', encoding="utf-8")

    audit = build_remote_api_execution_audit(
        source_root=source_root,
        package_metadata_path=metadata_path,
    )
    serialized = json.dumps(audit, ensure_ascii=False)

    assert audit["ready"] is False
    assert "remote_api_execution_local_inference_import_detected" in audit["reason_codes"]
    assert "remote_api_execution_local_inference_dynamic_import_detected" in audit["reason_codes"]
    assert "remote_api_execution_local_inference_dependency_detected" in audit["reason_codes"]
    assert "remote_api_execution_local_model_artifact_detected" in audit["reason_codes"]
    assert audit["source_audit"]["forbidden_import_roots"] == ["torch"]
    assert audit["source_audit"]["forbidden_dynamic_import_roots"] == ["vllm"]
    assert audit["dependency_audit"]["forbidden_dependency_roots"] == ["transformers"]
    assert audit["local_model_artifact_audit"]["local_model_artifact_suffix_counts"] == {".safetensors": 1}
    assert str(source_root) not in serialized
    assert "import torch" not in serialized
    assert "raw_source_persisted\": true" not in serialized


