def test_standalone_fusion_completion_audit_rejects_stale_runbook_command_templates(tmp_path):
    registry_path = _benchmark_registry_path(tmp_path)
    runs = _strong_claim_audit_runs_for_all_required_suites()
    campaign_dir, claim_audit = _write_complete_final_audit_campaign(tmp_path, runs, "completion_stale_runbook_commands")
    case_hash_manifest_path = _write_ready_case_hash_manifest_from_runs(tmp_path, runs, min_cases_per_suite=20)
    source_manifest_path = _write_ready_source_manifest(
        tmp_path,
        min_cases_per_suite=20,
        case_hash_manifest_path=case_hash_manifest_path,
    )
    final_audit = build_benchmark_final_audit(
        campaign_dir=campaign_dir,
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
        min_cases_per_suite=20,
        alpha=0.05,
    )
    evidence_pack = build_benchmark_evidence_pack(
        registry_path=registry_path,
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
        dataset_manifest_path=campaign_dir / "campaign.json",
        campaign_dir=campaign_dir,
        include_provider_baselines=True,
        max_provider_baselines=None,
        min_cases_per_suite=20,
        alpha=0.05,
    )
    runbook = build_fusion_live_runbook(
        registry_path=registry_path,
        min_cases_per_suite=20,
        alpha=0.05,
        include_provider_baselines=True,
        max_provider_baselines=None,
    )
    for stage in runbook["stages"]:
        if stage["stage_id"] == "05_manifest_and_readiness":
            stage["commands"] = [
                command
                for command in stage["commands"]
                if "benchmark-source-manifest-prepare" not in command["command_template"]
            ]
        for command in stage["commands"]:
            template = command["command_template"]
            if " benchmark-campaign " in template:
                template = template.replace(
                    " --api-surface-protocol <SAFE_WORK_DIR>/api_surface_protocol.safe.json",
                    "",
                ).replace(
                    " --provider-input-adapter <SAFE_WORK_DIR>/provider_input_adapter.safe.json",
                    "",
                )
            if " fusion-completion-audit " in template:
                template = template.replace(
                    " --failure-analysis <SAFE_WORK_DIR>/fusion_failure_analysis.safe.json",
                    "",
                ).replace(
                    " --system-development-readiness <SAFE_WORK_DIR>/system_development_readiness.safe.json",
                    "",
                )
            command["command_template"] = template
