def test_standalone_live_multiple_choice_scorecard_with_fake_client(tmp_path):
    class FakeBenchmarkClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            if "Synthesize one final answer" in prompt:
                return "B"
            if profile.profile_id == "weak/low":
                return "B" if "2 + 2" in prompt else "A"
            return json.dumps(
                {
                    "answer": "B",
                    "evidence": [{"claim": "unit", "source": "fixture", "reliability": 0.9}],
                    "assumptions": [],
                    "uncertainties": [],
                    "confidence": 0.91,
                }
            )

    registry_path = _benchmark_registry_path(tmp_path)
    dataset_path = tmp_path / "fixture.jsonl"
    dataset_path.write_text(
        "\n".join(
            [
                json.dumps({"question": "What is 2 + 2?", "options": ["three", "four", "five"], "answer": "B"}),
                json.dumps({"question": "Pick the blue option.", "options": ["red", "blue", "green"], "answer": "B"}),
            ]
        ),
        encoding="utf-8",
    )
    fake = FakeBenchmarkClient()

    axio_run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="axio-pro",
        registry_path=registry_path,
        live=True,
        client=fake,
    )
    provider_run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="provider::weak/low",
        registry_path=registry_path,
        live=True,
        client=fake,
    )
    scorecard = build_benchmark_scorecard([axio_run, provider_run])
    axio_path = tmp_path / "axio.json"
    provider_path = tmp_path / "provider.json"
    scorecard_path = tmp_path / "scorecard.json"
    axio_path.write_text(json.dumps(axio_run), encoding="utf-8")
    provider_path.write_text(json.dumps(provider_run), encoding="utf-8")

    assert fusion_cli_main(
        [
            "benchmark-scorecard",
            "--run-file",
            str(axio_path),
            "--run-file",
            str(provider_path),
            "--output",
            str(scorecard_path),
        ]
    ) == 0

    serialized = json.dumps({"axio": axio_run, "provider": provider_run, "scorecard": scorecard}, ensure_ascii=False)

    assert axio_run["correct_count"] == 2
    assert provider_run["correct_count"] == 1
    assert axio_run["estimated_cost_usd"] > 0
    assert provider_run["estimated_cost_usd"] > 0
    assert axio_run["provider_call_count"] >= 2
    assert provider_run["provider_call_count"] == 2
    assert axio_run["pricing_known_case_count"] == 2
    assert provider_run["pricing_known_case_count"] == 2
    assert all(row["estimated_cost_usd"] > 0 for row in axio_run["case_results"])
    assert all(row["pricing_known"] is True for row in provider_run["case_results"])
    by_candidate = {row["candidate_id"]: row for row in scorecard["candidates"]}
    provider_alias = f"provider::{sha256_text('weak/low')}"
    assert by_candidate["axio-pro"]["total_estimated_cost_usd"] == axio_run["estimated_cost_usd"]
    assert provider_run["candidate_id"] == provider_alias
    assert by_candidate[provider_alias]["total_estimated_cost_usd"] == provider_run["estimated_cost_usd"]
    assert by_candidate["axio-pro"]["cost_per_case_usd"] > 0
    assert by_candidate["axio-pro"]["primary_score_per_dollar"] > 0
    suite = scorecard["per_suite"][0]
    provider_tier = suite["provider_baseline_tiers"][0]
    comparison = suite["axio_target_comparisons"][0]
    assert provider_tier["estimated_cost_usd"] == provider_run["estimated_cost_usd"]
    assert comparison["axio_estimated_cost_usd"] == axio_run["estimated_cost_usd"]
    assert comparison["baseline_estimated_cost_usd"] == provider_run["estimated_cost_usd"]
    assert scorecard["comparison"]["axio_pro_beats_best_provider"] is True
    assert scorecard["comparison"]["superiority_claim_allowed"] is False
    assert scorecard_path.exists()
    assert "Pick the blue option" not in serialized
    assert "provider::weak/low" not in serialized
    assert "raw_labels_persisted\": true" not in serialized
    assert "raw_model_output_persisted\": true" not in serialized


def test_standalone_live_axio_benchmark_exercises_all_public_api_surfaces(monkeypatch, tmp_path):
    class FakeBenchmarkClient:
        def complete(self, profile, request, *, prompt, system, timeout=None):
            del profile, request, prompt, system, timeout
            return "B"

    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "LOCAL_BENCHMARK_KEY_SHOULD_NOT_PERSIST")
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_API_KEY", raising=False)
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_GATEWAY_URL", raising=False)
    registry_path = _benchmark_registry_path(tmp_path)
    dataset_path = tmp_path / "four_surface_fixture.jsonl"
    dataset_path.write_text(
        json.dumps(
            {
                "question": "SECRET_FOUR_SURFACE_QUESTION",
                "options": ["first", "second", "third"],
                "answer": "B",
            }
        )
        + "\n",
        encoding="utf-8",
    )
    endpoint_by_format = {
        "chat/completions": "/v1/chat/completions",
        "responses": "/v1/responses",
        "anthropic": "/v1/messages",
        "gemini": "/v1beta/models/axio-fast:generateContent",
    }
    axio_runs = []
    for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
        run = run_multiple_choice_benchmark(
            suite_id="arc_challenge",
            dataset_path=dataset_path,
            candidate_id="axio-fast",
            api_format=api_format,
            registry_path=registry_path,
            live=True,
            client=FakeBenchmarkClient(),
        )
        case = run["case_results"][0]
        invocation = case["public_api_invocation"]
        assert run["correct_count"] == 1
        assert case["status"] == "completed"
        assert invocation["public_api_surface_used"] is True
        assert invocation["api_format"] == api_format
        assert invocation["endpoint_path"] == endpoint_by_format[api_format]
        assert invocation["transport"] == "in_process_public_endpoint"
        assert invocation["network_calls_performed"] is False
        assert invocation["response_model_matches_request"] is True
        assert invocation["raw_prompt_persisted"] is False
        axio_runs.append(run)

    provider_run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="provider::weak/low",
        registry_path=registry_path,
        live=True,
        client=FakeBenchmarkClient(),
    )
    provider_invocation = provider_run["case_results"][0]["public_api_invocation"]
    serialized = json.dumps({"axio": axio_runs, "provider": provider_run}, ensure_ascii=False)

    assert provider_run["correct_count"] == 1
    assert provider_invocation["public_api_surface_used"] is False
    assert provider_invocation["candidate_kind"] == "provider_native"
    assert "SECRET_FOUR_SURFACE_QUESTION" not in serialized
    assert "LOCAL_BENCHMARK_KEY_SHOULD_NOT_PERSIST" not in serialized
    assert "unit/solver" not in serialized
    assert '"raw_response_text_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized


def test_standalone_public_benchmark_tool_calls_cover_four_api_surfaces_without_receipt_leakage(monkeypatch):
    class ToolBenchmarkClient:
        def complete_turn(self, profile, request, *, prompt, system, timeout=None):
            del profile, request, prompt, system, timeout
            from axio_fusion_api.providers import ProviderCompletion

            return ProviderCompletion(
                "",
                (
                    {
                        "id": "benchmark_call_1",
                        "type": "function",
                        "function": {
                            "name": "private_benchmark_lookup",
                            "arguments": '{"record":"private-42"}',
                        },
                    },
                ),
            )

        def complete(self, *args, **kwargs):
            raise AssertionError("native tool turn must not fall through to text completion")

    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "LOCAL_TOOL_BENCHMARK_KEY_MUST_NOT_PERSIST")
    profile = normalize_profile(
        {
            "provider": "tool-unit",
            "model": "tool-solver",
            "supports_tools": True,
            "capabilities": {
                "agentic_tool_calling": 0.99,
                "structured_output": 0.99,
                "logic": 0.9,
                "critique": 0.82,
            },
        }
    )
    declared_tools = (
        {
            "type": "function",
            "function": {
                "name": "private_benchmark_lookup",
                "description": "Private fixture declaration",
                "parameters": {
                    "type": "object",
                    "properties": {"record": {"type": "string"}},
                    "required": ["record"],
                },
            },
        },
    )
    expected_shapes = {
        "chat/completions": lambda payload: payload["tools"][0]["function"]["name"],
        "responses": lambda payload: payload["tools"][0]["name"],
        "anthropic": lambda payload: payload["tools"][0]["name"],
        "gemini": lambda payload: payload["tools"][0]["functionDeclarations"][0]["name"],
    }

    for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
        _, payload = evaluation_module._benchmark_public_api_payload(
            model="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_TOOL_BENCHMARK_PROMPT",
            system="PRIVATE_TOOL_BENCHMARK_SYSTEM",
            task_type="agentic_tool_calling",
            max_output_tokens=64,
            tools=declared_tools,
        )
        assert expected_shapes[api_format](payload) == "private_benchmark_lookup"

        completion = evaluation_module._complete_public_axio_benchmark_candidate(
            engine=FusionEngine([profile], client=ToolBenchmarkClient()),
            candidate_id="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_TOOL_BENCHMARK_PROMPT",
            system="PRIVATE_TOOL_BENCHMARK_SYSTEM",
            task_type="agentic_tool_calling",
            max_output_tokens=64,
            axio_gateway_url=None,
            tools=declared_tools,
        )
        invocation = completion.api_invocation
        serialized = json.dumps(invocation, ensure_ascii=False)

        assert completion.text == ""
        assert len(completion.tool_calls) == 1
        assert completion.tool_calls[0]["name"] == "private_benchmark_lookup"
        assert completion.tool_calls[0]["arguments"] == {"record": "private-42"}
        assert invocation["api_format"] == api_format
        assert invocation["tool_declaration_count"] == 1
        assert invocation["tool_call_count"] == 1
        assert invocation["raw_tool_names_persisted"] is False
        assert invocation["raw_tool_arguments_persisted"] is False
        assert "private_benchmark_lookup" not in serialized
        assert "private-42" not in serialized
        assert "PRIVATE_TOOL_BENCHMARK_PROMPT" not in serialized
        assert "LOCAL_TOOL_BENCHMARK_KEY_MUST_NOT_PERSIST" not in serialized


def test_standalone_public_benchmark_message_history_covers_four_api_surfaces_without_receipt_leakage(monkeypatch):
    class HistoryBenchmarkClient:
        def __init__(self):
            self.requests = []

        def complete_turn(self, profile, request, *, prompt, system, timeout=None):
            del profile, timeout
            self.requests.append(
                {
                    "prompt": prompt,
                    "system": system,
                    "history_count": len(request.history),
                }
            )
            from axio_fusion_api.providers import ProviderCompletion

            return ProviderCompletion("history-response")

        def complete(self, *args, **kwargs):
            raise AssertionError("history benchmark must use normalized turn execution")

    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "LOCAL_HISTORY_BENCHMARK_KEY_MUST_NOT_PERSIST")
    profile = normalize_profile(
        {
            "provider": "history-unit",
            "model": "history-solver",
            "capabilities": {"daily_work": 0.95, "structured_output": 0.9},
        }
    )
    history_messages = (
        {"role": "system", "content": "PRIVATE_HISTORY_SYSTEM"},
        {"role": "user", "content": "PRIVATE_HISTORY_FIRST_USER"},
        {"role": "assistant", "content": "PRIVATE_HISTORY_ASSISTANT"},
        {"role": "user", "content": "PRIVATE_HISTORY_CURRENT_USER"},
    )

    for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
        endpoint, payload = evaluation_module._benchmark_public_api_payload(
            model="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_HISTORY_FALLBACK_PROMPT",
            system="PRIVATE_HISTORY_FALLBACK_SYSTEM",
            task_type="daily_work",
            max_output_tokens=64,
            messages=history_messages,
        )
        assert endpoint
        if api_format == "chat/completions":
            assert [row["role"] for row in payload["messages"]] == ["system", "user", "assistant", "user"]
        elif api_format == "responses":
            assert payload["instructions"] == "PRIVATE_HISTORY_SYSTEM"
            assert [row["role"] for row in payload["input"]] == ["user", "assistant", "user"]
        elif api_format == "anthropic":
            assert payload["system"] == "PRIVATE_HISTORY_SYSTEM"
            assert [row["role"] for row in payload["messages"]] == ["user", "assistant", "user"]
        else:
            assert payload["systemInstruction"]["parts"][0]["text"] == "PRIVATE_HISTORY_SYSTEM"
            assert [row["role"] for row in payload["contents"]] == ["user", "model", "user"]

        client = HistoryBenchmarkClient()
        completion = evaluation_module._complete_public_axio_benchmark_candidate(
            engine=FusionEngine([profile], client=client),
            candidate_id="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_HISTORY_FALLBACK_PROMPT",
            system="PRIVATE_HISTORY_FALLBACK_SYSTEM",
            task_type="daily_work",
            max_output_tokens=64,
            axio_gateway_url=None,
            messages=history_messages,
        )
        serialized = json.dumps(completion.api_invocation, ensure_ascii=False)

        assert completion.text == "history-response"
        assert completion.api_invocation["request_message_count"] == 4
        assert completion.api_invocation["raw_message_content_persisted"] is False
        assert client.requests
        assert "PRIVATE_HISTORY_CURRENT_USER" in client.requests[0]["prompt"]
        assert "PRIVATE_HISTORY_SYSTEM" in client.requests[0]["system"]
        assert client.requests[0]["history_count"] >= 2
        assert "PRIVATE_HISTORY" not in serialized
        assert "LOCAL_HISTORY_BENCHMARK_KEY_MUST_NOT_PERSIST" not in serialized


def test_standalone_public_benchmark_tool_history_covers_four_api_surfaces_without_receipt_leakage(monkeypatch):
    class ToolHistoryBenchmarkClient:
        def __init__(self):
            self.requests = []

        def complete_turn(self, profile, request, *, prompt, system, timeout=None):
            del profile, prompt, system, timeout
            self.requests.append([dict(item) for item in request.history])
            from axio_fusion_api.providers import ProviderCompletion

            return ProviderCompletion("tool-history-response")

        def complete(self, *args, **kwargs):
            raise AssertionError("tool-history benchmark must use native turn execution")

    reset_runtime_state_for_tests()
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", "LOCAL_TOOL_HISTORY_KEY_MUST_NOT_PERSIST")
    profile = normalize_profile(
        {
            "provider": "tool-history-unit",
            "model": "tool-history-solver",
            "supports_tools": True,
            "capabilities": {"agentic_tool_calling": 0.99, "structured_output": 0.95},
        }
    )
    declared_tools = (
        {
            "type": "function",
            "function": {
                "name": "private_history_lookup",
                "parameters": {"type": "object", "properties": {"record": {"type": "string"}}},
            },
        },
    )
    history_messages = (
        {"role": "system", "content": "PRIVATE_TOOL_HISTORY_SYSTEM"},
        {"role": "user", "content": "PRIVATE_TOOL_HISTORY_FIRST_USER"},
        {
            "role": "assistant",
            "tool_calls": [
                {
                    "id": "private-history-call",
                    "type": "function",
                    "name": "private_history_lookup",
                    "arguments": {"record": "private-history-argument"},
                }
            ],
        },
        {
            "role": "tool",
            "tool_result": {
                "call_id": "private-history-call",
                "name": "private_history_lookup",
                "output": "PRIVATE_TOOL_HISTORY_RESULT",
            },
        },
        {"role": "user", "content": "PRIVATE_TOOL_HISTORY_CURRENT_USER"},
    )

    for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
        _, payload = evaluation_module._benchmark_public_api_payload(
            model="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_TOOL_HISTORY_FALLBACK_PROMPT",
            system="PRIVATE_TOOL_HISTORY_FALLBACK_SYSTEM",
            task_type="agentic_tool_calling",
            max_output_tokens=64,
            tools=declared_tools,
            messages=history_messages,
        )
        if api_format == "chat/completions":
            assert payload["messages"][2]["tool_calls"][0]["function"]["name"] == "private_history_lookup"
            assert payload["messages"][3]["role"] == "tool"
        elif api_format == "responses":
            assert payload["input"][1]["type"] == "function_call"
            assert payload["input"][2]["type"] == "function_call_output"
        elif api_format == "anthropic":
            assert payload["messages"][1]["content"][0]["type"] == "tool_use"
            assert payload["messages"][2]["content"][0]["type"] == "tool_result"
        else:
            assert "functionCall" in payload["contents"][1]["parts"][0]
            assert "functionResponse" in payload["contents"][2]["parts"][0]

        client = ToolHistoryBenchmarkClient()
        completion = evaluation_module._complete_public_axio_benchmark_candidate(
            engine=FusionEngine([profile], client=client),
            candidate_id="axio-fast",
            api_format=api_format,
            prompt="PRIVATE_TOOL_HISTORY_FALLBACK_PROMPT",
            system="PRIVATE_TOOL_HISTORY_FALLBACK_SYSTEM",
            task_type="agentic_tool_calling",
            max_output_tokens=64,
            axio_gateway_url=None,
            tools=declared_tools,
            messages=history_messages,
        )
        serialized = json.dumps(completion.api_invocation, ensure_ascii=False)

        assert completion.text == "tool-history-response"
        assert completion.api_invocation["request_message_count"] == 5
        assert client.requests
        assert any(isinstance(item.get("tool_calls"), list) for item in client.requests[0])
        assert any(isinstance(item.get("tool_result"), dict) for item in client.requests[0])
        assert any(
            item.get("tool_result", {}).get("name") == "private_history_lookup"
            for item in client.requests[0]
            if isinstance(item.get("tool_result"), dict)
        )
        assert "PRIVATE_TOOL_HISTORY" not in serialized
        assert "private_history_lookup" not in serialized
        assert "private-history-argument" not in serialized
        assert "LOCAL_TOOL_HISTORY_KEY_MUST_NOT_PERSIST" not in serialized


def test_standalone_benchmark_http_gateway_keeps_local_key_local_and_joins_gemini_path(monkeypatch, tmp_path):
    class FakeGatewayResponse:
        status = 200
        headers = {"Content-Type": "application/json"}

        def __init__(self, payload):
            self._body = json.dumps(payload).encode("utf-8")

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc_value, traceback):
            del exc_type, exc_value, traceback
            return False

        def getcode(self):
            return self.status

        def read(self):
            return self._body

    reset_runtime_state_for_tests()
    local_key = "LOCAL_SERVICE_KEY_MUST_NOT_REACH_REMOTE_GATEWAY"
    gateway_url = "https://benchmark-gateway.invalid/v1beta"
    monkeypatch.setenv("AXIO_FUSION_API_KEYS", local_key)
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_API_KEY", raising=False)
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_GATEWAY_URL", raising=False)
    calls = []

    def fake_urlopen(request, timeout=None):
        calls.append(
            {
                "url": request.full_url,
                "headers": dict(request.header_items()),
                "timeout": timeout,
            }
        )
        return FakeGatewayResponse(
            {
                "modelVersion": "axio-fast",
                "candidates": [
                    {
                        "content": {
                            "role": "model",
                            "parts": [{"text": "B"}],
                        }
                    }
                ],
                "usageMetadata": {"promptTokenCount": 3, "candidatesTokenCount": 1},
            }
        )

    monkeypatch.setattr(evaluation_module.urllib_request, "urlopen", fake_urlopen)
    registry_path = _benchmark_registry_path(tmp_path)
    dataset_path = tmp_path / "gateway_gemini_fixture.jsonl"
    dataset_path.write_text(
        json.dumps(
            {
                "question": "SECRET_GATEWAY_GEMINI_QUESTION",
                "options": ["first", "second", "third"],
                "answer": "B",
            }
        )
        + "\n",
        encoding="utf-8",
    )

    run = run_multiple_choice_benchmark(
        suite_id="arc_challenge",
        dataset_path=dataset_path,
        candidate_id="axio-fast",
        api_format="gemini",
        registry_path=registry_path,
        live=True,
        axio_gateway_url=gateway_url,
    )
    invocation = run["case_results"][0]["public_api_invocation"]
    serialized = json.dumps(run, ensure_ascii=False)

    assert run["correct_count"] == 1
    assert len(calls) == 1
    assert calls[0]["url"] == "https://benchmark-gateway.invalid/v1beta/models/axio-fast:generateContent"
    assert calls[0]["timeout"] == 90.0
    assert all(str(key).lower() != "authorization" for key in calls[0]["headers"])
    assert invocation["transport"] == "http_gateway"
    assert invocation["network_calls_performed"] is True
    assert invocation["gateway_url_sha256"] == sha256_text(gateway_url)
    assert invocation["raw_gateway_url_persisted"] is False
    assert gateway_url not in serialized
    assert local_key not in serialized
    assert "SECRET_GATEWAY_GEMINI_QUESTION" not in serialized
    assert '"secrets_persisted": true' not in serialized


def test_standalone_benchmark_scorecard_tracks_per_suite_provider_tiers_by_primary_metric():
    def scored_run(candidate_id, mean_score, accuracy):
        return {
            "schema": "axio_fusion_api.benchmark_run.v2",
            "suite_id": "flores_translation_instruction",
            "candidate_id": candidate_id,
            "task_format": "translation_chrf",
            "mode": "live",
            "case_count": 3,
            "attempted_count": 3,
            "correct_count": int(round(accuracy * 3)),
            "accuracy": accuracy,
            "mean_score": mean_score,
            "primary_metric": "chrF",
            "latency_ms": 1000 - int(mean_score * 100),
            "average_case_latency_ms": 100.0,
            "p50_case_latency_ms": 100.0,
            "p95_case_latency_ms": 100.0,
            "case_results": [
                {
                    "case_id": sha256_text(f"flores:{candidate_id}:{index}"),
                    "score": mean_score,
                    "correct": mean_score >= 0.5,
                    "latency_ms": 100.0,
                    "raw_input_persisted": False,
                    "raw_reference_persisted": False,
                    "raw_model_output_persisted": False,
                }
                for index in range(3)
            ],
            "raw_prompt_persisted": False,
            "raw_label_persisted": False,
            "raw_provider_output_persisted": False,
            "secrets_persisted": False,
        }

    runs = [
        scored_run("provider::rank-by-mean-1", 0.92, 0.10),
        scored_run("provider::rank-by-mean-2", 0.80, 0.95),
        scored_run("provider::rank-by-mean-3", 0.70, 0.90),
        scored_run("axio-pro", 0.95, 0.20),
        scored_run("axio-terra", 0.81, 0.20),
        scored_run("axio-fast", 0.71, 0.20),
    ]

    scorecard = build_benchmark_scorecard(runs)
    suite = scorecard["per_suite"][0]
    tiers = suite["provider_baseline_tiers"]
    comparisons = {row["axio_model"]: row for row in suite["axio_target_comparisons"]}
    serialized = json.dumps(scorecard, ensure_ascii=False)

    assert suite["suite_id"] == "flores_translation_instruction"
    assert suite["primary_metric"] == "chrF"
    assert tiers[0]["tier"] == "strongest_provider"
    assert tiers[0]["candidate_id"] == "provider::rank-by-mean-1"
    assert tiers[1]["candidate_id"] == "provider::rank-by-mean-2"
    assert tiers[2]["candidate_id"] == "provider::rank-by-mean-3"
    assert comparisons["axio-pro"]["target_tier"] == "strongest_provider"
    assert comparisons["axio-terra"]["target_tier"] == "second_strongest_provider"
    assert comparisons["axio-fast"]["target_tier"] == "third_strongest_provider"
    assert comparisons["axio-pro"]["beats_target"] is True
    assert comparisons["axio-terra"]["beats_target"] is True
    assert comparisons["axio-fast"]["beats_target"] is True
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["passed_suite_count"] == 1
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["all_scored_suites_passed"] is True
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["all_required_suites_present"] is False
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["all_required_suites_passed"] is False
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["missing_required_suite_count"] == _benchmark_suite_count() - 1
    assert scorecard["provider_tier_contract"]["axio-pro"] == "must beat strongest_provider on every required suite"
    assert "raw_provider_outputs_persisted\": true" not in serialized
    assert "raw_model_output_persisted\": true" not in serialized


def test_standalone_pre_registered_scorecard_comparison_uses_provider_pool_rank_one():
    def scored_run(candidate_id, mean_score, correct):
        return {
            "schema": "axio_fusion_api.benchmark_run.v2",
            "suite_id": "flores_translation_instruction",
            "candidate_id": candidate_id,
            "task_format": "translation_chrf",
            "mode": "live",
            "case_count": 1,
            "attempted_count": 1,
            "correct_count": int(correct),
            "accuracy": float(correct),
            "mean_score": mean_score,
            "primary_metric": "chrF",
            "latency_ms": 100.0,
            "average_case_latency_ms": 100.0,
            "p50_case_latency_ms": 100.0,
            "p95_case_latency_ms": 100.0,
            "case_results": [
                {
                    "case_id": sha256_text(f"pre-registered-scorecard:{candidate_id}"),
                    "score": mean_score,
                    "correct": bool(correct),
                    "latency_ms": 100.0,
                    "raw_input_persisted": False,
                    "raw_reference_persisted": False,
                    "raw_model_output_persisted": False,
                }
            ],
            "raw_prompt_persisted": False,
            "raw_label_persisted": False,
            "raw_provider_output_persisted": False,
            "secrets_persisted": False,
        }

    runs = [
        scored_run("provider::rank-1", 0.60, 0),
        scored_run("provider::rank-2", 0.70, 0),
        scored_run("provider::rank-3", 0.90, 1),
        scored_run("axio-pro", 0.95, 1),
        scored_run("axio-terra", 0.80, 1),
        scored_run("axio-fast", 0.75, 1),
    ]

    scorecard = build_benchmark_scorecard(
        runs,
        provider_baseline_freeze=_claim_provider_baseline_freeze_manifest(),
    )
    comparison = scorecard["comparison"]

    assert comparison["best_provider_baseline"]["candidate_id"] == "provider::rank-1"
    assert comparison["best_provider_baseline_source"] == (
        "externally_evidenced_pre_registered_provider_pool_rank_before_target_campaign"
    )
    assert comparison["suite_observed_best_provider_diagnostic"]["candidate_id"] == "provider::rank-3"
    assert comparison["suite_observed_best_provider_is_diagnostic_only"] is True


def test_standalone_api_surface_parity_report_guides_four_surface_repairs(tmp_path):
    runs = json.loads(json.dumps(_strong_claim_audit_runs_for_all_required_suites()))
    runs = [
        run
        for run in runs
        if not (
            run["suite_id"] == "arc_challenge"
            and run["candidate_id"] == "axio-fast"
            and run.get("api_format") == "gemini"
        )
    ]
    for run in runs:
        if run["suite_id"] == "math_500" and run["candidate_id"] == "axio-terra" and run.get("api_format") == "responses":
            run["correct_count"] = 20
            run["accuracy"] = 0.5
            for index, case in enumerate(run["case_results"]):
                case["correct"] = index < 20

    report = build_benchmark_api_surface_parity_report(runs, score_tolerance=0.02)
    run_path = tmp_path / "runs.json"
    output_path = tmp_path / "SECRET_SURFACE_OUTPUT" / "api_surface_parity.safe.json"
    run_path.write_text(json.dumps(build_benchmark_runs_payload(runs)), encoding="utf-8")
    assert fusion_cli_main(
        [
            "benchmark-api-surface-parity",
            "--run-file",
            str(run_path),
            "--score-tolerance",
            "0.02",
            "--output",
            str(output_path),
        ]
    ) == 0

    cli_report = json.loads(output_path.read_text(encoding="utf-8"))
    serialized = json.dumps({"report": report, "cli": cli_report}, ensure_ascii=False)
    rec_ids = {row["recommendation_id"] for row in report["recommendations"]}
    arc_fast = next(
        row
        for row in report["repair_queue"]
        if row["suite_id"] == "arc_challenge" and row["axio_model"] == "axio-fast"
    )
    math_terra = next(
        row
        for row in report["repair_queue"]
        if row["suite_id"] == "math_500" and row["axio_model"] == "axio-terra"
    )

    assert report["schema"] == "axio_fusion_api.benchmark_api_surface_parity_report.v1"
    assert report["run_set_receipt"]["run_set_digest_sha256"] == build_benchmark_runs_payload(runs)["run_set_digest_sha256"]
    assert report["source_run_set_digest_sha256"] == report["run_set_receipt"]["run_set_digest_sha256"]
    assert report["all_required_api_surfaces_ready"] is False
    assert report["failed_surface_row_count"] == 2
    assert report["blocking_reason_counts"]["missing_required_api_surface_runs"] == 1
    assert report["blocking_reason_counts"]["api_surface_score_delta_above_tolerance"] == 1
    assert report["missing_api_format_counts"]["gemini"] == 1
    assert "complete_missing_api_surface_runs" in rec_ids
    assert "investigate_surface_adapter_score_drift" in rec_ids
    assert arc_fast["missing_api_formats"] == ["gemini"]
    assert math_terra["max_primary_score_delta"] > 0.02
