def test_standalone_benchmark_claim_audit_rejects_terra_and_fast_tier_failures():
    runs = json.loads(json.dumps(_strong_claim_audit_runs_for_all_required_suites()))

    def weaken(run, correct_count):
        run["correct_count"] = correct_count
        run["accuracy"] = round(correct_count / run["case_count"], 6)
        for index, row in enumerate(run["case_results"]):
            row["correct"] = index < correct_count

    for run in runs:
        if run["candidate_id"] == "axio-terra":
            weaken(run, 17)
        elif run["candidate_id"] == "axio-fast":
            weaken(run, 15)

    audit = build_benchmark_claim_audit(runs, min_cases_per_suite=20, alpha=0.05)
    terra_failures = [row for row in audit["comparisons"] if row["axio_model"] == "axio-terra"]
    fast_failures = [row for row in audit["comparisons"] if row["axio_model"] == "axio-fast"]

    assert audit["all_required_suites_present"] is True
    assert audit["final_claims"]["axio_pro_beats_strongest_single_model_on_all_required_benchmarks"] is True
    assert audit["final_claims"]["axio_terra_beats_second_strongest_single_model_on_all_required_benchmarks"] is False
    assert audit["final_claims"]["axio_fast_beats_third_strongest_single_model_on_all_required_benchmarks"] is False
    assert audit["all_final_claims_allowed"] is False
    assert all("axio_primary_score_not_higher" in row["reason_codes"] for row in terra_failures)
    assert all("axio_primary_score_not_higher" in row["reason_codes"] for row in fast_failures)


def test_standalone_benchmark_claim_audit_requires_practical_effect_size():
    runs = []
    for suite in benchmark_manifest()["suites"]:
        suite_id = suite["suite_id"]
        runs.extend(
            [
                _claim_audit_run(suite_id, "provider::rank-1", 270, total=300),
                _claim_audit_run(suite_id, "provider::rank-2", 260, total=300),
                _claim_audit_run(suite_id, "provider::rank-3", 250, total=300),
            ]
        )
        for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS:
            runs.extend(
                [
                    _claim_audit_run(suite_id, "axio-pro", 282, total=300, api_format=api_format),
                    _claim_audit_run(suite_id, "axio-terra", 272, total=300, api_format=api_format),
                    _claim_audit_run(suite_id, "axio-fast", 262, total=300, api_format=api_format),
                ]
            )

    audit = build_benchmark_claim_audit(runs, min_cases_per_suite=100, alpha=0.05)
    failed_rows = [row for row in audit["comparisons"] if row["claim_allowed"] is not True]
    serialized = json.dumps(audit, ensure_ascii=False)

    assert audit["all_required_suites_present"] is True
    assert audit["multiple_comparison_correction"]["all_comparisons_significant_after_correction"] is True
    assert all(row["multiple_comparison_passed"] is True for row in audit["comparisons"])
    assert audit["all_final_claims_allowed"] is False
    assert len(failed_rows) == _benchmark_claim_family_size()
    assert all(row["effect_size_gate"]["primary_score_delta_passed"] is True for row in failed_rows)
    assert all(row["effect_size_gate"]["paired_net_win_rate_delta_passed"] is False for row in failed_rows)
    assert all("effect_size_paired_net_win_rate_below_minimum" in row["reason_codes"] for row in failed_rows)
    assert all(row["effect_size_gate"]["paired_net_win_rate_delta"] == 0.04 for row in failed_rows)
    assert "q:gpqa_diamond" not in serialized
    assert "A. " not in serialized
    assert '"raw_provider_outputs_persisted": true' not in serialized
    assert '"secrets_persisted": true' not in serialized
    assert any(item["kind"] == "model_claim_not_proven" and item["candidate_id"] == "axio-terra" for item in audit["missing_requirements"])
    assert any(item["kind"] == "model_claim_not_proven" and item["candidate_id"] == "axio-fast" for item in audit["missing_requirements"])


def test_standalone_benchmark_claim_audit_rejects_over_3x_latency_even_when_scores_win():
    runs = json.loads(json.dumps(_strong_claim_audit_runs_for_all_required_suites()))
    for run in runs:
        if (
            run["suite_id"] == "arc_challenge"
            and run["candidate_id"] == "axio-pro"
            and run.get("api_surface_is_primary_claim") is True
        ):
            run["p95_case_latency_ms"] = 400.0
            run["average_case_latency_ms"] = 350.0
            run["latency_ms"] = 16_000.0

    audit = build_benchmark_claim_audit(runs, min_cases_per_suite=20, alpha=0.05)
    scorecard = build_benchmark_scorecard(runs)
    comparison = next(
        row
        for row in audit["comparisons"]
        if row["suite_id"] == "arc_challenge" and row["axio_model"] == "axio-pro"
    )
    scorecard_comparison = next(
        row
        for row in scorecard["per_suite"]
        if row["suite_id"] == "arc_challenge"
    )["axio_target_comparisons"][0]
    serialized = json.dumps({"audit": audit, "scorecard": scorecard}, ensure_ascii=False)

    assert comparison["axio_primary_score"] > comparison["baseline_primary_score"]
    assert comparison["paired_case_stats"]["p_value_one_sided"] <= 0.05
    assert comparison["latency_within_3x_baseline"] is False
    assert comparison["latency_multiplier_vs_baseline"] > 4.5
    assert comparison["latency_gate"]["p50_latency_gate_passed"] is True
    assert comparison["latency_gate"]["p95_latency_gate_passed"] is False
    assert comparison["latency_gate"]["p95_latency_multiplier_vs_baseline"] > 4.5
    assert "axio_latency_exceeds_4.5x_baseline" in comparison["reason_codes"]
    assert "axio_p95_latency_exceeds_4.5x_baseline" in comparison["reason_codes"]
    assert comparison["claim_allowed"] is False
    assert audit["final_claims"]["axio_pro_beats_strongest_single_model_on_all_required_benchmarks"] is False
    assert audit["all_final_claims_allowed"] is False
    assert any(item["kind"] == "model_claim_not_proven" and item["candidate_id"] == "axio-pro" for item in audit["missing_requirements"])
    assert scorecard_comparison["latency_within_3x_baseline"] is False
    assert "axio_latency_exceeds_4.5x_baseline" in scorecard_comparison["reason_codes"]
    assert "axio_p95_latency_exceeds_4.5x_baseline" in scorecard_comparison["reason_codes"]
    assert scorecard["comparison"]["tier_target_summary"]["axio-pro"]["all_required_suites_passed"] is False
    assert "raw_provider_outputs_persisted\": true" not in serialized


def test_standalone_benchmark_claim_audit_rejects_over_3x_p50_latency_even_when_p95_passes():
    runs = json.loads(json.dumps(_strong_claim_audit_runs_for_all_required_suites()))
    for run in runs:
        if run["suite_id"] != "arc_challenge":
            continue
        if run["candidate_id"] == "provider::rank-1":
            run["p95_case_latency_ms"] = 100.0
        if (
            run["candidate_id"] == "axio-pro"
            and run.get("api_surface_is_primary_claim") is True
        ):
            run["p50_case_latency_ms"] = 40.0
            run["p95_case_latency_ms"] = 41.0

    audit = build_benchmark_claim_audit(runs, min_cases_per_suite=20, alpha=0.05)
    scorecard = build_benchmark_scorecard(runs)
    comparison = next(
        row
        for row in audit["comparisons"]
        if row["suite_id"] == "arc_challenge" and row["axio_model"] == "axio-pro"
    )
    scorecard_comparison = next(
        row
        for row in scorecard["per_suite"]
        if row["suite_id"] == "arc_challenge"
    )["axio_target_comparisons"][0]

    assert comparison["axio_primary_score"] > comparison["baseline_primary_score"]
    assert comparison["latency_within_3x_baseline"] is False
    assert comparison["latency_gate"]["p50_latency_gate_passed"] is False
    assert comparison["latency_gate"]["p95_latency_gate_passed"] is True
    assert comparison["latency_gate"]["p50_latency_multiplier_vs_baseline"] > 4.5
    assert comparison["latency_gate"]["p95_latency_multiplier_vs_baseline"] <= 3.0
    assert comparison["latency_multiplier_vs_baseline"] == comparison["latency_gate"]["p50_latency_multiplier_vs_baseline"]
    assert "axio_latency_exceeds_4.5x_baseline" in comparison["reason_codes"]
    assert "axio_p50_latency_exceeds_4.5x_baseline" in comparison["reason_codes"]
    assert "axio_p95_latency_exceeds_4.5x_baseline" not in comparison["reason_codes"]
    assert comparison["claim_allowed"] is False
    assert scorecard_comparison["latency_within_3x_baseline"] is False
    assert "axio_p50_latency_exceeds_4.5x_baseline" in scorecard_comparison["reason_codes"]


