def test_standalone_benchmark_final_audit_rejects_forged_claim_audit_even_with_matching_run_digest(tmp_path):
    runs = _strong_claim_audit_runs_for_all_required_suites()
    campaign_dir, _ = _write_complete_final_audit_campaign(
        tmp_path,
        runs,
        "forged_claim_audit",
    )
    case_hash_manifest_path = _write_ready_case_hash_manifest_from_runs(tmp_path, runs, min_cases_per_suite=20)
    source_manifest_path = _write_ready_source_manifest(
        tmp_path,
        min_cases_per_suite=20,
        case_hash_manifest_path=case_hash_manifest_path,
    )
    claim_audit_path = campaign_dir / "claim_audit.json"
    claim_audit = json.loads(claim_audit_path.read_text(encoding="utf-8"))
    target_row = next(
        row
        for row in claim_audit["comparisons"]
        if row["suite_id"] == "arc_challenge" and row["axio_model"] == "axio-pro"
    )
    target_row["baseline_candidate_id"] = "provider::rank-2"
    claim_audit_path.write_text(json.dumps(claim_audit), encoding="utf-8")

    audit = build_benchmark_final_audit(
        campaign_dir=campaign_dir,
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
        min_cases_per_suite=20,
        alpha=0.05,
    )
    kinds = {item["kind"] for item in audit["missing_requirements"]}
    serialized = json.dumps(audit, ensure_ascii=False)

    assert audit["cross_artifact_summary"]["claim_audit_run_set_digest_matches"] is True
    assert audit["deterministic_replay_summary"]["claim_audit_matches_recomputed"] is False
    assert "claim_audit_deterministic_replay_mismatch" in kinds
    assert audit["final_completion_allowed"] is False
    assert "provider::rank-2" not in serialized


