def test_standalone_benchmark_final_audit_rejects_digest_match_without_binding_receipt(tmp_path):
    runs = _strong_claim_audit_runs_for_all_required_suites()
    campaign_dir = tmp_path / "unbound_case_hash_receipt_campaign"
    campaign_dir.mkdir()
    claim_audit = build_benchmark_claim_audit(runs, min_cases_per_suite=20, alpha=0.05)
    scorecard = build_benchmark_scorecard(runs)
    methodology = build_benchmark_methodology_manifest()
    campaign = {
        "schema": "axio_fusion_api.benchmark_campaign.v1",
        "mode": "live",
        "suite_spec_count": len(benchmark_manifest()["suites"]),
        "candidate_count": 6,
        "expected_run_count": len(runs),
        "completed_or_resumed_run_count": len(runs),
        "missing_suite_count": 0,
        "candidate_ids": ["provider::rank-1", "provider::rank-2", "provider::rank-3", "axio-pro", "axio-terra", "axio-fast"],
        "claim_summary": {
            "all_required_suites_present": claim_audit["all_required_suites_present"],
            "all_final_claims_allowed": claim_audit["all_final_claims_allowed"],
        },
        "policy": {
            "include_provider_baselines": True,
            "provider_baseline_selection": "all_available_provider_models",
            "available_provider_baseline_count": 3,
            "min_cases_per_suite": 20,
            "alpha": 0.05,
        },
        "provider_baseline_census": _claim_provider_baseline_census(),
        "provider_registry_receipt": _claim_provider_registry_receipt(),
        "readiness_preflight_receipt": _claim_readiness_preflight_receipt(),
        "methodology_receipt": _claim_methodology_receipt(methodology),
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    (campaign_dir / "runs.json").write_text(
        json.dumps(build_benchmark_runs_payload(runs)),
        encoding="utf-8",
    )
    (campaign_dir / "scorecard.json").write_text(json.dumps(scorecard), encoding="utf-8")
    (campaign_dir / "claim_audit.json").write_text(json.dumps(claim_audit), encoding="utf-8")
    (campaign_dir / "methodology.json").write_text(json.dumps(methodology), encoding="utf-8")
    (campaign_dir / "campaign.json").write_text(json.dumps(campaign), encoding="utf-8")
    _write_training_contamination_audit(campaign_dir, clean=True)
    case_hash_manifest_path = _write_ready_case_hash_manifest_from_runs(tmp_path, runs, min_cases_per_suite=20)
    source_manifest_path = _write_ready_source_manifest(tmp_path, min_cases_per_suite=20)
    source_manifest = json.loads(source_manifest_path.read_text(encoding="utf-8"))
    case_manifest = json.loads(case_hash_manifest_path.read_text(encoding="utf-8"))
    case_digests = {
        row["suite_id"]: row["materialized_case_hash_manifest_sha256"]
        for row in case_manifest.get("suite_rows", [])
        if isinstance(row, dict)
    }
    for row in source_manifest["suites"]:
        row["source_record"]["materialized_case_hash_manifest_sha256"] = case_digests[row["suite_id"]]
    source_manifest.pop("case_hash_binding_receipt", None)
    unbound_source_manifest_path = tmp_path / "SECRET_UNBOUND_DIGEST_MATCH_SOURCE_MANIFEST.json"
    unbound_source_manifest_path.write_text(json.dumps(source_manifest), encoding="utf-8")

    audit = build_benchmark_final_audit(
        campaign_dir=campaign_dir,
        source_manifest_path=unbound_source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
        min_cases_per_suite=20,
        alpha=0.05,
    )
    kinds = {item["kind"] for item in audit["missing_requirements"]}
    binding_summary = audit["case_hash_manifest_summary"]["binding_receipt_summary"]
    serialized = json.dumps(audit, ensure_ascii=False)

    assert audit["final_completion_allowed"] is False
    assert audit["source_manifest_summary"]["all_required_sources_ready"] is True
    assert audit["case_hash_manifest_summary"]["source_digest_match"] is True
    assert binding_summary["binding_receipt_valid_for_current_inputs"] is False
    assert "case_hash_binding_receipt_missing" in binding_summary["reason_codes"]
    assert "source_manifest_case_hash_binding_receipt_invalid" in kinds
    assert audit["proof_contract"]["requires_source_manifest_case_hash_binding_receipt"] is True
    assert str(unbound_source_manifest_path) not in serialized
    assert str(case_hash_manifest_path) not in serialized
    assert "SECRET_READY_DATASET_DIR" not in serialized
    assert "raw_case_hashes_persisted\": true" not in serialized


