    assert audit["run_summary"]["all_runs_anti_leakage_clean"] is False
    assert arc_row["anti_leakage_issue_count"] == 1
    assert "run_anti_leakage_contract_failed" in arc_row["reason_codes"]
    assert len(issue_receipts) == 1
    assert issue_receipt["case_result_issue_count"] == 1
    assert "benchmark_labels_used_for_training" in issue_receipt["reason_codes"]
    assert "case_result_level_anti_leakage_failed" in issue_receipt["reason_codes"]
    assert issue_receipt["reason_counts"]["raw_label_or_reference_persisted"] == 1
    assert audit["proof_contract"]["requires_run_level_anti_leakage_contract_clean"] is True
    assert "raw_label_persisted\": true" not in serialized
    assert "SECRET" not in serialized


