def test_standalone_fusion_live_readiness_discovers_short_named_cohort_directory(tmp_path):
    source_dir = _write_fusion_live_readiness_manifest_set(tmp_path, ready=True)
    cohort_dir = tmp_path / "cohort_2026-07-21_v1"
    cohort_dir.mkdir()
    source_prefixes = {
        "materialization_status": "materialization_status_21_suites_",
        "case_hash_manifest": "benchmark_case_hash_manifest_21_suites_",
        "harness_pin_manifest": "harness_pin_manifest_21_suites_",
        "source_manifest_validation": "benchmark_source_manifest_prepared_validation_21_suites_",
        "import_batch_template": "import_batch_template_pinned_21_suites_",
        "official_harness_execution_plan": "official_harness_execution_plan_21_suites_",
        "official_import_audit": "official_import_audit_21_suites_",
        "acquisition_status": "acquisition_status_21_suites_",
    }
    short_names = {
        "materialization_status": "materialization_status.safe.json",
        "case_hash_manifest": "case_hash_manifest.safe.json",
        "harness_pin_manifest": "harness_pin_manifest.safe.json",
        "source_manifest_validation": "source_manifest_validation.safe.json",
        "import_batch_template": "official_import_batch_template.safe.json",
        "official_harness_execution_plan": "official_harness_execution_plan.safe.json",
        "official_import_audit": "official_import_audit.safe.json",
        "acquisition_status": "acquisition_status.safe.json",
    }
    for artifact_name, prefix in source_prefixes.items():
        source = next(source_dir.glob(f"{prefix}formal_top_three_unit.safe.json"))
        target = cohort_dir / short_names[artifact_name]
        target.write_text(source.read_text(encoding="utf-8"), encoding="utf-8")

    selected, discovery = evaluation_module._resolve_fusion_manifest_paths(
        {},
        manifest_dir=cohort_dir,
    )

    assert discovery["mode"] == "joint_common_cohort"
    assert discovery["ready"] is True
    assert discovery["common_cohort_available"] is True
    assert discovery["candidate_cohort_count"] == 1
    assert set(selected) == set(short_names)
    assert all(path is not None and path.parent == cohort_dir for path in selected.values())
    serialized = json.dumps(discovery, ensure_ascii=False)
    assert "cohort_2026-07-21_v1" not in serialized


