def test_standalone_benchmark_final_audit_rejects_tampered_live_probe_summary_digest(tmp_path):
    runs = _strong_claim_audit_runs_for_all_required_suites()
    campaign_dir, _ = _write_complete_final_audit_campaign(
        tmp_path,
        runs,
        "provider_probe_live_summary_tamper",
    )
    probe_evidence_path = campaign_dir / "provider_probe_evidence_audit.safe.json"
    probe_evidence = json.loads(probe_evidence_path.read_text(encoding="utf-8"))
    probe_evidence["artifact_summaries"]["private_probe"]["live_available_count"] = 0
    probe_evidence["artifact_summaries"]["private_probe"]["mode_counts"] = {"dry_run": 3}
    probe_evidence["artifact_summaries"]["private_probe"][
        "live_available_profile_set_sha256"
    ] = sha256_text(stable_json([]))
    probe_evidence["artifact_summaries"]["private_registry"]["readiness"][
        "live_probe_proven"
    ] = False
    probe_evidence["artifact_summaries"]["private_registry"]["readiness"][
        "final_claim_registry_ready"
    ] = False
    probe_evidence_path.write_text(json.dumps(probe_evidence), encoding="utf-8")
    case_hash_manifest_path = _write_ready_case_hash_manifest_from_runs(
        tmp_path,
        runs,
        min_cases_per_suite=20,
    )
    source_manifest_path = _write_ready_source_manifest(
        tmp_path,
        min_cases_per_suite=20,
        case_hash_manifest_path=case_hash_manifest_path,
    )

    audit = build_benchmark_final_audit(
        campaign_dir=campaign_dir,
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
        min_cases_per_suite=20,
        alpha=0.05,
    )
    kinds = {item["kind"] for item in audit["missing_requirements"]}
    serialized = json.dumps(audit, ensure_ascii=False)

    assert audit["final_completion_allowed"] is False
    assert audit["provider_probe_evidence_summary"]["audit_digest_matches"] is False
    assert audit["provider_probe_evidence_summary"]["private_probe_live_available_count"] == 0
    assert "provider_probe_evidence_audit_digest_mismatch" in kinds
    assert "provider_probe_evidence_private_probe_live_available_count_too_small" in kinds
    assert "provider_probe_evidence_private_probe_live_mode_count_too_small" in kinds
    assert "provider_probe_evidence_private_registry_live_probe_not_proven" in kinds
    assert "provider_probe_evidence_private_registry_not_final_claim_ready" in kinds
    assert str(probe_evidence_path) not in serialized
    assert "raw_provider_outputs_persisted\": true" not in serialized
    assert "secrets_persisted\": true" not in serialized


