def _write_ready_system_development_readiness_fixture(tmp_path, registry_path, *, min_cases_per_suite=1):
    code_receipt_path = tmp_path / "code_test_receipt.safe.json"
    protocol_path = tmp_path / "api_surface_protocol.safe.json"
    provider_adapter_path = tmp_path / "provider_input_adapter.safe.json"
    runbook_path = tmp_path / "fusion_live_runbook.safe.json"
    system_readiness_path = tmp_path / "system_development_readiness.safe.json"
    code_receipt_path.write_text(
        json.dumps(
            build_fusion_code_test_receipt(
                exit_code=0,
                passed_count=1,
                failed_count=0,
                duration_seconds=1.0,
            )
        ),
        encoding="utf-8",
    )
    protocol_path.write_text(
        json.dumps(build_api_surface_protocol_self_test(registry_path=str(registry_path))),
        encoding="utf-8",
    )
    provider_adapter_path.write_text(
        json.dumps(provider_module.build_provider_input_adapter_self_test(load_registry(registry_path))),
        encoding="utf-8",
    )
    runbook_path.write_text(
        json.dumps(
            build_fusion_live_runbook(
                registry_path=registry_path,
                min_cases_per_suite=min_cases_per_suite,
                alpha=0.05,
                include_provider_baselines=True,
                max_provider_baselines=None,
            )
        ),
        encoding="utf-8",
    )
    readiness = build_fusion_system_development_readiness(
        registry_path=registry_path,
        code_test_receipt_path=code_receipt_path,
        api_surface_protocol_path=protocol_path,
        provider_input_adapter_path=provider_adapter_path,
        live_runbook_path=runbook_path,
        min_cases_per_suite=min_cases_per_suite,
        alpha=0.05,
    )
    assert readiness["system_development_ready"] is True
    assert readiness["ready_for_21_suite_benchmark_validation"] is True
    system_readiness_path.write_text(json.dumps(readiness), encoding="utf-8")
    return system_readiness_path


