def _write_complete_final_audit_campaign(tmp_path, runs, name):
    campaign_dir = tmp_path / name
    campaign_dir.mkdir()
    provider_baseline_freeze = _claim_provider_baseline_freeze_manifest()
    claim_audit = build_benchmark_claim_audit(
        runs,
        min_cases_per_suite=20,
        alpha=0.05,
        provider_baseline_freeze=provider_baseline_freeze,
        require_http_gateway=True,
    )
    scorecard = build_benchmark_scorecard(
        runs,
        provider_baseline_freeze=provider_baseline_freeze,
        require_http_gateway=True,
    )
    methodology = build_benchmark_methodology_manifest()
    candidate_ids = ["provider::rank-1", "provider::rank-2", "provider::rank-3", "axio-pro", "axio-terra", "axio-fast"]
    run_unit_ids = [
        f"{model}@{_api_format_slug_for_test(api_format)}"
        for model in ("axio-pro", "axio-terra", "axio-fast")
        for api_format in AXIO_BENCHMARK_API_FORMATS_FOR_TESTS
    ] + ["provider::rank-1", "provider::rank-2", "provider::rank-3"]
    campaign = {
        "schema": "axio_fusion_api.benchmark_campaign.v1",
        "mode": "live",
        "suite_spec_count": len(benchmark_manifest()["suites"]),
        "candidate_count": len(candidate_ids),
        "run_unit_count": len(run_unit_ids),
        "expected_run_count": len(runs),
        "completed_or_resumed_run_count": len(runs),
        "missing_suite_count": 0,
        "candidate_ids": candidate_ids,
        "run_unit_ids": run_unit_ids,
        "api_surface_ids": run_unit_ids[:12],
        "claim_summary": {
            "all_required_suites_present": claim_audit["all_required_suites_present"],
            "all_final_claims_allowed": claim_audit["all_final_claims_allowed"],
        },
        "policy": {
            "include_provider_baselines": True,
            "provider_baseline_selection": "externally_ranked_top_three_pre_registered",
            "available_provider_baseline_count": 3,
            "min_cases_per_suite": 20,
            "alpha": 0.05,
        },
        "provider_baseline_census": _claim_provider_baseline_census(),
        "provider_registry_receipt": _claim_provider_registry_receipt(),
        "provider_baseline_freeze_receipt": provider_baseline_freeze["freeze_receipt"],
        "readiness_preflight_receipt": _claim_readiness_preflight_receipt(
            candidate_count=len(candidate_ids),
            run_unit_count=len(run_unit_ids),
        ),
        "methodology_receipt": _claim_methodology_receipt(methodology),
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    (campaign_dir / "runs.json").write_text(
        json.dumps(build_benchmark_runs_payload(runs)),
        encoding="utf-8",
    )
    (campaign_dir / "scorecard.json").write_text(json.dumps(scorecard), encoding="utf-8")
    (campaign_dir / "claim_audit.json").write_text(json.dumps(claim_audit), encoding="utf-8")
    (campaign_dir / "methodology.json").write_text(json.dumps(methodology), encoding="utf-8")
    (campaign_dir / "provider_probe_evidence_audit.safe.json").write_text(
        json.dumps(_claim_provider_probe_evidence_audit()),
        encoding="utf-8",
    )
    (campaign_dir / "provider_baseline_freeze.safe.json").write_text(
        json.dumps(provider_baseline_freeze),
        encoding="utf-8",
    )
    (campaign_dir / "official_import_audit.safe.json").write_text(
        json.dumps(_claim_official_import_audit_for_runs(runs)),
        encoding="utf-8",
    )
    (campaign_dir / "api_surface_parity.safe.json").write_text(
        json.dumps(build_benchmark_api_surface_parity_report(runs, require_http_gateway=True)),
        encoding="utf-8",
    )
    (campaign_dir / "campaign.json").write_text(json.dumps(campaign), encoding="utf-8")
    _write_training_contamination_audit(campaign_dir, clean=True)
    return campaign_dir, claim_audit


