def test_standalone_tau_bench_runner_exposes_only_visible_environment_state():
    hidden_goal = "SECRET_TAU_HIDDEN_GOAL"
    hidden_actions = "SECRET_TAU_HIDDEN_ACTIONS"
    hidden_reward = "SECRET_TAU_HIDDEN_REWARD"

    class Response:
        def __init__(self, observation, reward, done):
            self.observation = observation
            self.reward = reward
            self.done = done

    class FakeEnv:
        def __init__(self):
            self.tasks = [object()]
            self.task = {
                "instruction": hidden_goal,
                "actions": hidden_actions,
                "reward": hidden_reward,
            }
            self.wiki = "PUBLIC_TAU_WIKI"
            self.tools_info = [
                {
                    "type": "function",
                    "function": {
                        "name": "lookup_public_record",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ]
            self.actions = []

        def reset(self, task_index=None):
            assert task_index == 0
            return Response("PUBLIC_USER_REQUEST", 0.0, False)

        def step(self, action):
            self.actions.append(action)
            if action["name"] == "lookup_public_record":
                return Response("PUBLIC_TOOL_RESULT", 0.0, False)
            assert action["name"] == "respond"
            return Response("###STOP###", 1.0, True)

    class Candidate:
        def __init__(self):
            self.requests = []

        def complete(self, *, messages, tools, max_output_tokens):
            self.requests.append(
                {
                    "messages": [dict(message) for message in messages],
                    "tools": [dict(tool) for tool in tools],
                    "max_output_tokens": max_output_tokens,
                }
            )
            if len(self.requests) == 1:
                return tau_bench_runner_module.CandidateTurn(
                    text="",
                    tool_calls=(
                        {
                            "id": "public-call-1",
                            "name": "lookup_public_record",
                            "arguments": {},
                        },
                        {
                            "id": "discarded-call-2",
                            "name": "lookup_public_record",
                            "arguments": {},
                        },
                    ),
                    cost={
                        "input_tokens": 3,
                        "output_tokens": 2,
                        "estimated_cost_usd": 0.01,
                        "pricing_known": True,
                        "provider_call_count": 1,
                    },
                )
            return tau_bench_runner_module.CandidateTurn(
                text="PUBLIC_FINAL_RESPONSE",
                tool_calls=(),
                cost={
                    "input_tokens": 4,
                    "output_tokens": 2,
                    "estimated_cost_usd": 0.01,
                    "pricing_known": True,
                    "provider_call_count": 1,
                },
            )

    candidate = Candidate()
    rows, interactions = tau_bench_runner_module.run_tau_bench_cases(
        env_factory=lambda domain, task_index: FakeEnv(),
        action_factory=lambda name, kwargs: {"name": name, "kwargs": dict(kwargs)},
        candidate=candidate,
        domains=("retail",),
        case_limit=1,
        max_steps=3,
        max_output_tokens=77,
    )
    serialized_requests = json.dumps(candidate.requests, ensure_ascii=False)
    serialized_artifacts = json.dumps({"rows": rows, "interactions": interactions}, ensure_ascii=False)

    assert len(rows) == 1
    assert rows[0]["passed"] is True
    assert rows[0]["candidate_call_count"] == 2
    assert rows[0]["tool_action_count"] == 1
    assert rows[0]["tool_error_count"] == 0
    assert rows[0]["discarded_tool_call_count"] == 1
    assert len(candidate.requests) == 2
    assert candidate.requests[0]["max_output_tokens"] == 77
    assert candidate.requests[1]["messages"][-1]["role"] == "tool"
    assert candidate.requests[1]["messages"][-1]["tool_result"]["name"] == "lookup_public_record"
    assert hidden_goal not in serialized_requests
    assert hidden_actions not in serialized_requests
    assert hidden_reward not in serialized_requests
    assert hidden_goal not in serialized_artifacts
    assert hidden_actions not in serialized_artifacts
    assert hidden_reward not in serialized_artifacts


def test_standalone_tau_bench_official_bridge_imports_hash_only_results_and_rejects_tampering(monkeypatch, tmp_path):
    harness_root = tmp_path / "SECRET_TAU_HARNESS"
    for relative in official_harness_module._HARNESS_REQUIREMENTS["tau_bench"]:
        target = harness_root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text("# tau fixture\n", encoding="utf-8")
    (harness_root / "tau_bench/envs/retail/tasks_test.py").write_text(
        "TASKS_TEST = [Task(note='SECRET_TAU_RETAIL_TASK')]\n",
        encoding="utf-8",
    )
    (harness_root / "tau_bench/envs/airline/tasks_test.py").write_text(
        "TASKS = [Task(note='SECRET_TAU_AIRLINE_TASK')]\n",
        encoding="utf-8",
    )
    pin_path = tmp_path / "SECRET_TAU_PIN.json"
    pin_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "tau_bench",
                        "ready": True,
                        **{
                            field: sha256_text(f"tau-bridge:{field}")
                            for field in (
                                "harness_name_sha256",
                                "harness_version_sha256",
                                "dataset_snapshot_sha256",
                                "evaluator_config_sha256",
                                "prompt_protocol_sha256",
                                "decoding_config_sha256",
                            )
                        },
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    private_run_dir = tmp_path / "SECRET_TAU_PRIVATE_RUN"
    preflight_path = tmp_path / "tau_preflight.safe.json"
    monkeypatch.setattr(official_harness_module, "_tau_python_runtime_version", lambda value: (3, 11, True))

    common = {
        "suite_id": "tau_bench",
        "dataset_path": harness_root,
        "harness_root": harness_root,
        "private_run_dir": private_run_dir,
        "candidate_id": "axio-fast",
        "api_format": "gemini",
        "harness_pin_manifest_path": pin_path,
        "axio_gateway_url": "http://127.0.0.1:19191",
        "tau_user_model": "independent-user-simulator",
        "tau_user_provider": "independent-provider",
        "tau_user_strategy": "llm",
        "tau_environments": ("retail", "airline"),
        "tau_max_steps": 3,
        "tau_python_executable": sys.executable,
    }
    preflight = build_official_harness_bridge_preflight(**common)
    assert fusion_cli_main(
        [
            "benchmark-official-harness-preflight",
            "--suite-id",
            "tau_bench",
            "--dataset",
            str(harness_root),
            "--harness-root",
            str(harness_root),
            "--private-run-dir",
            str(private_run_dir),
            "--candidate-id",
            "axio-fast",
            "--api-format",
            "gemini",
            "--harness-pin-manifest",
            str(pin_path),
            "--axio-gateway-url",
            "http://127.0.0.1:19191",
            "--tau-user-model",
            "independent-user-simulator",
            "--tau-user-provider",
            "independent-provider",
            "--tau-user-strategy",
            "llm",
            "--tau-environment",
            "retail",
            "--tau-environment",
            "airline",
            "--tau-max-steps",
            "3",
            "--tau-python-executable",
            sys.executable,
            "--output",
            str(preflight_path),
        ]
    ) == 0
    duplicate_environment = build_official_harness_bridge_preflight(
        **{**common, "tau_environments": ("retail", "retail")}
    )
    zero_limit = build_official_harness_bridge_preflight(**{**common, "limit": 0})

    def fake_run(command, cwd, env, capture_output, text, timeout, check):
        del cwd, env, capture_output, text, timeout, check
        assert Path(command[1]).name == "tau_bench_bridge_runner.py"
        assert command[command.index("--gateway-url") + 1] == "http://127.0.0.1:19191"
        output_path = Path(command[command.index("--output") + 1])
        interactions_path = Path(command[command.index("--interactions-output") + 1])
        rows = []
        for index, source_identifier in enumerate(("retail:0", "airline:0")):
            digest = sha256_text(f"tau-private-trajectory:{source_identifier}")
            rows.append(
                {
                    "source_identifier": source_identifier,
                    "status": "completed",
                    "passed": index == 0,
                    "latency_ms": 10.0 + index,
                    "candidate_call_count": 2,
                    "tool_action_count": 1,
                    "tool_error_count": index,
                    "prediction_sha256": digest,
                    "output_sha256": digest,
                    "trajectory_sha256": digest,
                    "input_tokens": 7,
                    "output_tokens": 4,
                    "estimated_cost_usd": 0.002,
                    "pricing_known": True,
                    "provider_call_count": 2,
                }
            )
        output_path.write_text("\n".join(json.dumps(row) for row in rows) + "\n", encoding="utf-8")
        interactions_path.write_text(
            json.dumps({"message": "SECRET_TAU_PRIVATE_INTERACTION"}) + "\n",
            encoding="utf-8",
        )
        return subprocess.CompletedProcess(command, 0, "SECRET_TAU_WORKER_STDOUT", "SECRET_TAU_WORKER_STDERR")

    monkeypatch.setattr(official_harness_module.subprocess, "run", fake_run)
    generation = generate_official_harness_samples(**common, live=True)
    evaluation = evaluate_official_harness_samples(**common)
    imported = import_official_harness_evaluation(private_run_dir=private_run_dir)
    cli_preflight = json.loads(preflight_path.read_text(encoding="utf-8"))
    metadata = [
        json.loads(line)
        for line in (private_run_dir / "generation.safe.jsonl").read_text(encoding="utf-8").splitlines()
    ]
    serialized = json.dumps(
        {
            "preflight": preflight,
            "cli_preflight": cli_preflight,
            "generation": generation,
            "evaluation": evaluation,
            "imported": imported,
            "metadata": metadata,
        },
        ensure_ascii=False,
    )

    assert preflight["status"] == "ready"
    assert cli_preflight["status"] == "ready"
    assert preflight["task_format"] == "tool_call_ast"
    assert preflight["generation_protocol"]["task_type"] == "agentic_tool_calling"
    assert duplicate_environment["status"] == "blocked"
    assert "official_harness_tau_bench_environment_selection_invalid" in duplicate_environment["reason_codes"]
    assert zero_limit["status"] == "blocked"
    assert "official_harness_case_set_empty" in zero_limit["reason_codes"]
    assert generation["status"] == "generated"
    assert generation["case_count"] == 2
    assert evaluation["status"] == "evaluated"
    assert evaluation["primary_metric"] == "task_success_rate"
    assert evaluation["primary_score"] == 0.5
    assert evaluation["tool_action_count"] == 2
    assert evaluation["tool_error_count"] == 1
    assert evaluation["tool_error_rate"] == 0.5
    assert imported.get("status") != "blocked", imported.get("reason_codes")
    assert imported["primary_metric"] == "task_success_rate"
    assert imported["secondary_metrics"]["tool_error_rate"] == 0.5
    assert all(row["public_api_invocation"]["api_format"] == "gemini" for row in metadata)
    assert "SECRET_TAU_RETAIL_TASK" not in serialized
    assert "SECRET_TAU_AIRLINE_TASK" not in serialized
    assert "SECRET_TAU_PRIVATE_INTERACTION" not in serialized
    assert "SECRET_TAU_WORKER_STDOUT" not in serialized
    assert "SECRET_TAU_WORKER_STDERR" not in serialized
    assert "SECRET_TAU_HARNESS" not in serialized
    assert "SECRET_TAU_PRIVATE_RUN" not in serialized

    scored_path = private_run_dir / "official_scored_rows.safe.jsonl"
    tampered_rows = [json.loads(line) for line in scored_path.read_text(encoding="utf-8").splitlines()]
    tampered_rows[0]["tool_error_count"] = 5
    scored_path.write_text("\n".join(json.dumps(row) for row in tampered_rows) + "\n", encoding="utf-8")
    tampered_import = import_official_harness_evaluation(private_run_dir=private_run_dir)

    assert tampered_import["status"] == "blocked"
    assert "official_harness_import_bridge_scored_rows_digest_mismatch" in tampered_import["reason_codes"]


@pytest.mark.parametrize("api_format", AXIO_BENCHMARK_API_FORMATS_FOR_TESTS)
def test_standalone_mt_bench_bridge_uses_two_turn_public_surfaces_and_blocks_tampering(
    monkeypatch,
    tmp_path,
    api_format,
):
    class FakeMTBenchClient:
        def __init__(self):
            self.calls = []
            self.judge_call_count = 0

        def complete(self, profile, request, *, prompt, system, timeout=None):
            self.calls.append(
                {
                    "provider": profile.provider,
                    "prompt": prompt,
                    "system": system,
                    "history": list(request.history),
                    "temperature": request.temperature,
                    "max_output_tokens": request.max_output_tokens,
                    "timeout": timeout,
                }
            )
            if profile.provider == "mt-judge-provider":
                self.judge_call_count += 1
                # First question is a clean target win. The two positions for
                # the second question disagree, which must become a tie.
                return ("[[A]]", "[[B]]", "[[A]]", "[[A]]")[self.judge_call_count - 1]
            if profile.provider == "mt-comparison-provider":
                return f"comparison private answer {len(self.calls)}"
            return f"fusion private answer {len(self.calls)}"

    reset_runtime_state_for_tests()
    monkeypatch.delenv("AXIO_FUSION_API_KEYS", raising=False)
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_API_KEY", raising=False)
    monkeypatch.delenv("AXIO_FUSION_BENCHMARK_GATEWAY_URL", raising=False)
    secret_prompt = "SECRET_MT_BENCH_PROMPT_MUST_STAY_PRIVATE"
    secret_reference = "SECRET_MT_BENCH_REFERENCE_MUST_STAY_PRIVATE"
    harness_root = tmp_path / "SECRET_MT_BENCH_FASTCHAT_ROOT"
    question_path = harness_root / "fastchat/llm_judge/data/mt_bench/question.jsonl"
    reference_path = harness_root / "fastchat/llm_judge/data/mt_bench/reference_answer/gpt-4.jsonl"
    prompts_path = harness_root / "fastchat/llm_judge/data/judge_prompts.jsonl"
    for path, content in {
        harness_root / "fastchat/llm_judge/common.py": "# common fixture\n",
        harness_root / "fastchat/llm_judge/gen_judgment.py": "# judgment fixture\n",
    }.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    question_path.parent.mkdir(parents=True, exist_ok=True)
    reference_path.parent.mkdir(parents=True, exist_ok=True)
    source_rows = [
        {
            "question_id": "unit-writing",
            "category": "writing",
            "turns": [f"{secret_prompt} writing first", f"{secret_prompt} writing second"],
        },
        {
            "question_id": "unit-math",
            "category": "math",
            "turns": [f"{secret_prompt} math first", f"{secret_prompt} math second"],
        },
    ]
    question_path.write_text("\n".join(json.dumps(row) for row in source_rows) + "\n", encoding="utf-8")
    reference_path.write_text(
        json.dumps(
            {
                "question_id": "unit-math",
                "choices": [{"index": 0, "turns": [secret_reference, f"{secret_reference} second"]}],
            }
        )
        + "\n",
        encoding="utf-8",
    )
    prompt_rows = [
        {
            "name": "pair-v2-multi-turn",
            "type": "pairwise",
            "system_prompt": "Unit impartial judge",
            "prompt_template": "ordinary {question_1} {answer_a_1} {question_2} {answer_a_2} {answer_b_1} {answer_b_2}",
            "output_format": "[[A]]",
        },
        {
            "name": "pair-math-v1-multi-turn",
            "type": "pairwise",
            "system_prompt": "Unit math judge",
            "prompt_template": "math {question_1} {ref_answer_1} {question_2} {ref_answer_2} {answer_a_1} {answer_a_2} {answer_b_1} {answer_b_2}",
            "output_format": "[[A]]",
        },
    ]
    prompts_path.write_text("\n".join(json.dumps(row) for row in prompt_rows) + "\n", encoding="utf-8")
    pin_path = tmp_path / "SECRET_MT_BENCH_PIN.json"
    pin_path.write_text(
        json.dumps(
            {
                "suites": [
                    {
                        "suite_id": "mt_bench_work",
                        "ready": True,
                        **{
                            field: sha256_text(f"mt-bench-unit:{field}")
                            for field in (
                                "harness_name_sha256",
                                "harness_version_sha256",
                                "dataset_snapshot_sha256",
                                "evaluator_config_sha256",
                                "prompt_protocol_sha256",
                                "decoding_config_sha256",
                            )
                        },
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    registry_path = tmp_path / "SECRET_MT_BENCH_REGISTRY.json"
    comparison_provider = "mt-comparison-provider"
